@import "tailwindcss";

/*
 * POS global visual theme (POS-REACT-GLOBAL-SURFACE-THEME-V2)
 * Semantic --exits-* tokens are the single source of truth for surfaces,
 * accents, motion, and elevation. Prefer tokens over page-local hex.
 * Primary color preference: set data-primary on <html>
 * (green | blue | violet | orange | rose). data-accent mirrored for compatibility.
 */

@theme inline {
  --color-background: var(--exits-bg);
  --color-foreground: var(--exits-text);
  --color-surface: var(--exits-surface);
  --color-muted: var(--exits-text-muted);
  --color-primary: var(--exits-primary);
  --color-primary-foreground: var(--exits-primary-foreground);
  --color-destructive: var(--exits-danger);
  --color-warning: var(--exits-warning);
  --color-success: var(--exits-success);
  --color-border: var(--exits-border);
  --color-ring: var(--exits-ring);
  --font-sans: var(--exits-font-sans);
  --radius-sm: var(--exits-radius-sm);
  --radius-md: var(--exits-radius-md);
  --radius-lg: var(--exits-radius-lg);
}

/* ---- Light: Atlantis-like neutral page, white cards, Primary as accent ---- */
:root,
[data-theme="light"] {
  color-scheme: light;
  --exits-bg: #f4f5f7;
  --exits-surface: #ffffff;
  --exits-surface-elevated: #ffffff;
  --exits-surface-muted: #eef0f3;

  --exits-border: #e1e4ea;
  --exits-border-strong: #c5cad3;

  --exits-text: #151a23;
  --exits-text-muted: #5c6678;
  --exits-text-subtle: #7a8496;

  --exits-primary: #166534;
  --exits-primary-hover: #14532d;
  --exits-primary-soft: #eef6f1;
  --exits-primary-contrast: #ffffff;
  --exits-primary-foreground: #ffffff;
  --exits-primary-border: color-mix(in srgb, #166534 35%, transparent);

  --exits-success: #166534;
  --exits-success-soft: #eef6f0;
  /* Warn intent locked to Button Standard orange (#ff5722) — never brown. */
  --exits-warning: #ff5722;
  --exits-warning-soft: #ffedd5;
  --exits-warning-foreground: #ffffff;
  --exits-danger: #b42318;
  --exits-danger-soft: #fef2f1;
  --exits-info: #0f766e;

  --exits-focus: #166534;
  --exits-ring: #166534;

  --exits-shadow-sm: 0 1px 2px color-mix(in srgb, #0f172a 4%, transparent);
  --exits-shadow-md: 0 4px 12px color-mix(in srgb, #0f172a 6%, transparent);
  --exits-shadow-lg: 0 10px 24px color-mix(in srgb, #0f172a 8%, transparent);

  /* Unified app shell chrome (sidebar / topbar / content) — solid, no blur. */
  --exits-shell-sidebar-bg: #ffffff;
  --exits-shell-topbar-bg: #e8ecf2;
  --exits-shell-content-bg: #e8ecf2;
  --exits-shell-panel-bg: #ffffff;
  --exits-shell-divider: #d5dbe6;
  --exits-shell-nav-hover-bg: #eef1f6;
  --exits-shell-nav-active-bg: var(--exits-primary-soft);
  --exits-shell-nav-active-fg: var(--exits-primary);
  --exits-shell-nav-active-border: var(--exits-primary);
  --exits-shell-nav-font-size: 0.875rem;
  --exits-shell-icon-size: 1.25rem;
  --exits-shell-radius: 0.75rem;
  --exits-shell-transition: 130ms;

  /*
   * Diamond LIGHT severity palette (UI Standards Severities showcase).
   * Separate from configurable --exits-primary brand preference.
   * @see https://diamond.primeng.org/uikit/button
   */
  --exits-severity-primary: #10b981;
  --exits-severity-primary-foreground: #ffffff;
  --exits-severity-primary-hover: #059669;

  --exits-severity-secondary: #f1f5f9;
  --exits-severity-secondary-foreground: #334155;
  --exits-severity-secondary-hover: #e2e8f0;

  --exits-severity-success: #22c55e;
  --exits-severity-success-foreground: #ffffff;
  --exits-severity-success-hover: #16a34a;

  --exits-severity-info: #0ea5e9;
  --exits-severity-info-foreground: #ffffff;
  --exits-severity-info-hover: #0284c7;

  /* Align with locked Button Standard Warn intent (#ff5722). */
  --exits-severity-warn: #ff5722;
  --exits-severity-warn-foreground: #ffffff;
  --exits-severity-warn-hover: #e64a19;

  --exits-severity-help: #a855f7;
  --exits-severity-help-foreground: #ffffff;
  --exits-severity-help-hover: #9333ea;

  --exits-severity-danger: #ef4444;
  --exits-severity-danger-foreground: #ffffff;
  --exits-severity-danger-hover: #dc2626;

  --exits-severity-contrast: #020617;
  --exits-severity-contrast-foreground: #ffffff;
  --exits-severity-contrast-hover: #0f172a;
}

/* ---- Dark: cool neutral hierarchy (Atlantis cleanliness; Primary remains accent) ---- */
[data-theme="dark"] {
  color-scheme: dark;
  --exits-bg: #0f1218;
  --exits-surface: #171b22;
  --exits-surface-elevated: #1d222b;
  --exits-surface-muted: #1a1f28;

  --exits-border: #2a303c;
  --exits-border-strong: #3b4352;

  --exits-text: #e8eaef;
  --exits-text-muted: #9aa3b5;
  --exits-text-subtle: #7b8496;

  --exits-primary: #4ade80;
  --exits-primary-hover: #6ee7a0;
  --exits-primary-soft: color-mix(in srgb, #4ade80 14%, #171b22);
  --exits-primary-contrast: #06280f;
  --exits-primary-foreground: #06280f;
  --exits-primary-border: color-mix(in srgb, #4ade80 35%, transparent);

  --exits-success: #4ade80;
  --exits-success-soft: color-mix(in srgb, #4ade80 12%, #171b22);
  /* Warn stays orange-family (not amber gold). Locked light fill: #ff5722. */
  --exits-warning: #ff7043;
  --exits-warning-soft: color-mix(in srgb, #ff7043 12%, #171b22);
  --exits-warning-foreground: #431407;
  --exits-danger: #ff8a80;
  --exits-danger-soft: color-mix(in srgb, #ff8a80 12%, #171b22);
  --exits-info: #2dd4bf;

  --exits-focus: #4ade80;
  --exits-ring: #4ade80;

  --exits-shadow-sm: 0 1px 2px color-mix(in srgb, #000 12%, transparent);
  --exits-shadow-md: 0 4px 12px color-mix(in srgb, #000 16%, transparent);
  --exits-shadow-lg: 0 10px 24px color-mix(in srgb, #000 20%, transparent);

  /* Unified app shell chrome — deep slate, purple-tinted active nav. */
  --exits-shell-sidebar-bg: #12161e;
  --exits-shell-topbar-bg: var(--exits-bg);
  --exits-shell-content-bg: var(--exits-bg);
  --exits-shell-panel-bg: var(--exits-surface-elevated);
  --exits-shell-divider: var(--exits-border);
  --exits-shell-nav-hover-bg: #1a1f28;
  --exits-shell-nav-active-bg: color-mix(in srgb, #8b5cf6 16%, #171b22);
  --exits-shell-nav-active-fg: #c4b5fd;
  --exits-shell-nav-active-border: #8b5cf6;
  --exits-shell-nav-font-size: 0.875rem;
  --exits-shell-icon-size: 1.25rem;
  --exits-shell-radius: 0.75rem;
  --exits-shell-transition: 130ms;

  /* Dark severity palette (Aura-like lighter fills) — must not leak into light */
  --exits-severity-primary: #34d399;
  --exits-severity-primary-foreground: #18181b;
  --exits-severity-primary-hover: #6ee7b7;

  --exits-severity-secondary: #27272a;
  --exits-severity-secondary-foreground: #d4d4d8;
  --exits-severity-secondary-hover: #3f3f46;

  --exits-severity-success: #4ade80;
  --exits-severity-success-foreground: #052e16;
  --exits-severity-success-hover: #86efac;

  --exits-severity-info: #38bdf8;
  --exits-severity-info-foreground: #082f49;
  --exits-severity-info-hover: #7dd3fc;

  --exits-severity-warn: #ff7043;
  --exits-severity-warn-foreground: #431407;
  --exits-severity-warn-hover: #ff8a65;

  --exits-severity-help: #c084fc;
  --exits-severity-help-foreground: #3b0764;
  --exits-severity-help-hover: #d8b4fe;

  --exits-severity-danger: #f87171;
  --exits-severity-danger-foreground: #450a0a;
  --exits-severity-danger-hover: #fca5a5;

  --exits-severity-contrast: #ffffff;
  --exits-severity-contrast-foreground: #09090b;
  --exits-severity-contrast-hover: #f4f4f5;
}

@media (prefers-color-scheme: dark) {
  [data-theme="system"],
  :root:not([data-theme]) {
    color-scheme: dark;
    --exits-bg: #0f1218;
    --exits-surface: #171b22;
    --exits-surface-elevated: #1d222b;
