    --exits-warning: #ff7043;
    --exits-warning-soft: color-mix(in srgb, #ff7043 12%, #171b22);
    --exits-warning-foreground: #431407;
    --exits-danger: #ff8a80;
    --exits-danger-soft: color-mix(in srgb, #ff8a80 12%, #171b22);
    --exits-info: #2dd4bf;

    --exits-focus: #4ade80;
    --exits-ring: #4ade80;

    --exits-shadow-sm: 0 1px 2px color-mix(in srgb, #000 12%, transparent);
    --exits-shadow-md: 0 4px 12px color-mix(in srgb, #000 16%, transparent);
    --exits-shadow-lg: 0 10px 24px color-mix(in srgb, #000 20%, transparent);

    --exits-shell-sidebar-bg: #12161e;
    --exits-shell-topbar-bg: var(--exits-bg);
    --exits-shell-content-bg: var(--exits-bg);
    --exits-shell-panel-bg: var(--exits-surface-elevated);
    --exits-shell-divider: var(--exits-border);
    --exits-shell-nav-hover-bg: #1a1f28;
    --exits-shell-nav-active-bg: color-mix(in srgb, #8b5cf6 16%, #171b22);
    --exits-shell-nav-active-fg: #c4b5fd;
    --exits-shell-nav-active-border: #8b5cf6;
    --exits-shell-nav-font-size: 0.875rem;
    --exits-shell-icon-size: 1.25rem;
    --exits-shell-radius: 0.75rem;
    --exits-shell-transition: 130ms;

    --exits-severity-primary: #34d399;
    --exits-severity-primary-foreground: #18181b;
    --exits-severity-primary-hover: #6ee7b7;

    --exits-severity-secondary: #27272a;
    --exits-severity-secondary-foreground: #d4d4d8;
    --exits-severity-secondary-hover: #3f3f46;

    --exits-severity-success: #4ade80;
    --exits-severity-success-foreground: #052e16;
    --exits-severity-success-hover: #86efac;

    --exits-severity-info: #38bdf8;
    --exits-severity-info-foreground: #082f49;
    --exits-severity-info-hover: #7dd3fc;

    --exits-severity-warn: #ff7043;
    --exits-severity-warn-foreground: #431407;
    --exits-severity-warn-hover: #ff8a65;

    --exits-severity-help: #c084fc;
    --exits-severity-help-foreground: #3b0764;
