    --exits-severity-contrast: #ffffff;
    --exits-severity-contrast-foreground: #09090b;
    --exits-severity-contrast-hover: #f4f4f5;
  }
}

/* ---- Shared structure tokens (theme-independent) ---- */
:root {
  /** ~4px — compact square/tag chips (not sharp corners). */
  --exits-radius-xs: 0.25rem;
  --exits-radius-sm: 0.375rem;
  --exits-radius-md: 0.5rem;
  /** Soft button shape pilot (~11px) — between md and lg; not a pill. */
  --exits-radius-soft: 0.6875rem;
  --exits-radius-lg: 0.75rem;
  /** Standard shape for controls and form fields (6px). Cards / panels stay on --exits-radius-md. */
  --exits-radius-control: 0.375rem;
  /** Interactive control radius — Preferences control shape (standard | pill). Buttons / Search / filter chips. */
  --exits-control-radius: var(--exits-radius-control);
  /**
   * Form field radius — text/select/textarea/date inputs.
   * Intentionally independent of Control Shape (Pill must NOT pill form fields).
   */
  --exits-field-radius: var(--exits-radius-control);
  /* ---- Form Field Focus Standard (thin Primary-aware; matches Search restraint) ---- */
  --exits-field-border: var(--exits-border);
  --exits-field-border-hover: var(--exits-border-strong);
  --exits-field-border-focus: var(--exits-primary);
  --exits-field-focus-ring: color-mix(in srgb, var(--exits-primary) 28%, transparent);
  --exits-field-focus-ring-width: 1px;
  --exits-field-border-error: var(--exits-danger);
  --exits-field-focus-ring-error: color-mix(in srgb, var(--exits-danger) 28%, transparent);
  /** Alias used by a few older classNames — same soft Primary ring. */
  --exits-focus-ring: var(--exits-field-focus-ring);
  --exits-space-1: 0.25rem;
  --exits-space-2: 0.5rem;
  --exits-space-3: 0.75rem;
  --exits-space-4: 1rem;
  --exits-space-6: 1.5rem;
  --exits-font-sans: "IBM Plex Sans", "Source Sans 3", system-ui, sans-serif;
  --exits-font-weight-regular: 400;
  --exits-font-weight-medium: 500;
  --exits-font-weight-semibold: 600;
  --exits-font-weight-bold: 700;
  --exits-leading-tight: 1.2;
  --exits-leading-normal: 1.45;
  --exits-leading-relaxed: 1.6;
  --exits-tracking-normal: 0;
  --exits-tracking-eyebrow: 0.04em;
  --exits-text-xs: 0.75rem;
  --exits-text-sm: 0.875rem;
  --exits-text-md: 0.9375rem;
  --exits-text-lg: 1rem;
  --exits-text-xl: 1.25rem;
  --exits-type-caption: var(--exits-text-xs);
  --exits-type-label: var(--exits-text-sm);
  --exits-type-body: var(--exits-text-md);
  --exits-type-card-title: var(--exits-text-md);
  --exits-type-section-title: var(--exits-text-md);
  --exits-type-page-title: 1.125rem;
  --exits-type-kpi: clamp(1.15rem, 2.4vw, 1.45rem);
  --exits-type-hero-kpi: clamp(1.55rem, 3.6vw, 2rem);
  --exits-motion-instant: 60ms;
  --exits-motion-fast: 130ms;
  --exits-motion-normal: 180ms;
  --exits-motion-base: var(--exits-motion-normal);
  --exits-motion-slow: 240ms;
  --exits-motion-shell: 280ms;
  --exits-ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --exits-ease-emphasized: cubic-bezier(0.22, 1, 0.36, 1);
  /* Desktop Reveal navigation — expand slightly slower than collapse. */
  --exits-sidebar-reveal-duration: 280ms;
  --exits-sidebar-collapse-duration: 240ms;
  --exits-sidebar-label-fade-duration: 160ms;
  --exits-sidebar-collapse-grace: 140ms;
  --exits-sidebar-label-slide: -0.25rem;
  /* Authoritative desktop shell sidebar track (Standard / Compact / Reveal). */
  --exits-shell-sidebar-width: 15.5rem;
  /* Shared height for sidenav brand strip + content top bar (desktop shells). */
  --exits-shell-chrome-height: 4rem;
  /* Table defaults (balance / when density unset) */
  --exits-table-cell-x: 0.75rem;
  --exits-table-cell-y: 0.625rem;
  --exits-table-row-height: 2.75rem;
  --exits-table-header-height: 2.5rem;
  --exits-table-font-size: var(--exits-text-sm);
  --exits-table-inline-editor-height: 1.625rem;
  --exits-table-action-size: 1.75rem;
  --exits-touch-target-min: 2.75rem;
  /*
   * Visual control density (default = balance).
   * Touch chrome (bottom nav) may use --exits-touch-target-min separately.
   * Do not force every desktop toolbar control to the touch minimum.
   */
  --exits-control-height: 2.25rem;
  --exits-control-padding-x: 0.875rem;
  --exits-control-padding-y: 0;
  --exits-control-height-lg: 2.75rem;
  --exits-page-padding: 1rem;
  /*
   * Internal page-content gutter (inside the content region — not a shell/sidebar gap).
   * Balance default = 20px; density + breakpoints adjust below.
   */
  --exits-page-gutter-inline: 1.25rem;
  --exits-page-gutter-block: 0.75rem;
  --exits-page-gutter-ops-inline: 0.875rem;
  --exits-page-header-padding-block: 0.625rem;
  --exits-page-header-padding-inline: 0.75rem;
  --exits-page-header-to-content-gap: 0.75rem;

  --exits-chip-min-height: 2.25rem;
  --exits-chip-padding-y: 0.35rem;
  --exits-chip-padding-x: 0.85rem;
  --exits-chip-font-size: var(--exits-text-sm);
  --exits-chip-gap: 0.5rem;
  --exits-chip-index-size: 1.25rem;

  --exits-row-min-height: 2.75rem;
  --exits-toolbar-gap: 0.5rem;
  --exits-section-gap: 0.625rem;
  --exits-list-card-padding-y: 0.75rem;
  --exits-list-card-padding-x: 0.875rem;
  --exits-entity-card-gap: 0.55rem;
  --exits-entity-card-meta-gap: 0.35rem 0.85rem;

  /* Read-only status/attribute pills — separate from interactive filter chips */
  --exits-status-chip-height: 1.625rem;
  --exits-status-chip-padding-x: 0.625rem;
  --exits-status-chip-font-size: 0.75rem;
  --exits-status-chip-border-width: 1px;
  --exits-status-chip-gap: 0.3rem;
  --exits-status-chip-icon-size: 0.8125rem;

  /*
   * Compact square/tag chip tokens (shape=square) — denser than status pills.
   * Still density-aware; not Button-sized.
   */
  --exits-chip-square-height: 1.3125rem;
  --exits-chip-square-padding-x: 0.375rem;
  --exits-chip-square-padding-y: 0.0625rem;
  --exits-chip-square-font-size: var(--exits-text-xs);
  --exits-chip-square-gap: 0.2rem;
  --exits-chip-square-icon-size: 0.6875rem;
}

/*
 * Primary color palettes (Preferences Appearance).
 * data-primary is authoritative; data-accent kept as a mirror for legacy selectors.
 * Semantic success / warning / danger / info tokens stay independent.
 */
:root,
[data-primary="green"],
[data-accent="green"],
:root:not([data-primary]):not([data-accent]) {
  /* green tokens already set by light/dark theme blocks above */
}

[data-theme="light"][data-primary="violet"],
[data-theme="light"][data-accent="violet"],
:root[data-primary="violet"]:not([data-theme="dark"]),
:root[data-accent="violet"]:not([data-theme="dark"]) {
  --exits-primary: #6d28d9;
  --exits-primary-hover: #5b21b6;
  --exits-primary-soft: #f3eefc;
  --exits-primary-contrast: #ffffff;
  --exits-primary-foreground: #ffffff;
  --exits-primary-border: color-mix(in srgb, #6d28d9 35%, transparent);
  --exits-focus: #6d28d9;
  --exits-ring: #6d28d9;
}

[data-theme="dark"][data-primary="violet"],
[data-theme="dark"][data-accent="violet"] {
  --exits-primary: #c4b5fd;
  --exits-primary-hover: #ddd6fe;
  --exits-primary-soft: color-mix(in srgb, #c4b5fd 14%, #171b22);
  --exits-primary-contrast: #1e1035;
  --exits-primary-foreground: #1e1035;
  --exits-primary-border: color-mix(in srgb, #c4b5fd 35%, transparent);
  --exits-focus: #c4b5fd;
  --exits-ring: #c4b5fd;
}

[data-theme="light"][data-primary="teal"],
[data-theme="light"][data-accent="teal"],
:root[data-primary="teal"]:not([data-theme="dark"]),
:root[data-accent="teal"]:not([data-theme="dark"]) {
  --exits-primary: #0f766e;
  --exits-primary-hover: #115e59;
  --exits-primary-soft: #eef8f6;
  --exits-primary-contrast: #ffffff;
  --exits-primary-foreground: #ffffff;
  --exits-primary-border: color-mix(in srgb, #0f766e 35%, transparent);
  --exits-focus: #0f766e;
  --exits-ring: #0f766e;
}

[data-theme="dark"][data-primary="teal"],
[data-theme="dark"][data-accent="teal"] {
  --exits-primary: #2dd4bf;
  --exits-primary-hover: #5eead4;
  --exits-primary-soft: color-mix(in srgb, #2dd4bf 14%, #171b22);
  --exits-primary-contrast: #042f2e;
  --exits-primary-foreground: #042f2e;
  --exits-primary-border: color-mix(in srgb, #2dd4bf 32%, transparent);
  --exits-focus: #2dd4bf;
  --exits-ring: #2dd4bf;
}

[data-theme="light"][data-primary="indigo"],
[data-theme="light"][data-accent="indigo"],
:root[data-primary="indigo"]:not([data-theme="dark"]),
:root[data-accent="indigo"]:not([data-theme="dark"]) {
  --exits-primary: #4338ca;
  --exits-primary-hover: #3730a3;
  --exits-primary-soft: #eef0fb;
  --exits-primary-contrast: #ffffff;
  --exits-primary-foreground: #ffffff;
  --exits-primary-border: color-mix(in srgb, #4338ca 35%, transparent);
  --exits-focus: #4338ca;
  --exits-ring: #4338ca;
}

[data-theme="dark"][data-primary="indigo"],
[data-theme="dark"][data-accent="indigo"] {
