/* Control shape preference — buttons / search / action chips with shape="auto".
   Square, Standard, Soft, Pill match the button shapes. */
:root,
[data-control-shape="standard"] {
  --exits-control-radius: var(--exits-radius-control);
}

[data-control-shape="square"] {
  --exits-control-radius: 0;
}

[data-control-shape="soft"] {
  --exits-control-radius: var(--exits-radius-soft);
}

[data-control-shape="pill"] {
  --exits-control-radius: 9999px;
}

/* Form fields keep a professional rectangle under any Control Shape. */
:root,
[data-control-shape="square"],
[data-control-shape="standard"],
[data-control-shape="soft"],
[data-control-shape="pill"] {
  --exits-field-radius: var(--exits-radius-control);
}

/* Global scrollbars — Primary thumb on a transparent track (follows the Primary color preference). */
* {
  scrollbar-color: color-mix(in srgb, var(--exits-primary) 72%, transparent) transparent;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background-color: color-mix(in srgb, var(--exits-primary) 72%, transparent);
  background-clip: content-box;
}

::-webkit-scrollbar-thumb:hover {
  background-color: var(--exits-primary);
}

/* Forced reduced motion preference (also honor OS media query below) */
[data-motion="reduced"] {
  --exits-motion-instant: 0ms;
  --exits-motion-fast: 0ms;
  --exits-motion-normal: 0ms;
  --exits-motion-base: 0ms;
  --exits-motion-slow: 0ms;
  --exits-motion-shell: 0ms;
  --exits-sidebar-reveal-duration: 0ms;
  --exits-sidebar-collapse-duration: 0ms;
  --exits-sidebar-label-fade-duration: 0ms;
  --exits-sidebar-collapse-grace: 0ms;
}

[data-motion="reduced"] *,
[data-motion="reduced"] *::before,
[data-motion="reduced"] *::after {
  animation-duration: 0.01ms !important;
  transition-duration: 0.01ms !important;
}

/* Kill interaction transforms when Animations=Reduced (not duration-only). */
[data-motion="reduced"] .exits-motion-press:active,
[data-motion="reduced"] .exits-motion-lift:hover,
[data-motion="reduced"] .exits-motion-lift:active,
[data-motion="reduced"] .exits-settings-gear--ambient {
  transform: none !important;
  filter: none !important;
}

/* Semantic motion utilities — shared primitives first. */
.exits-motion-transition {
  transition-property: transform, opacity;
  transition-duration: var(--exits-motion-base);
  transition-timing-function: var(--exits-ease-standard);
}

.exits-motion-interaction {
  transition-property: background-color, border-color, color, box-shadow, transform, opacity;
  transition-duration: var(--exits-motion-fast);
  transition-timing-function: var(--exits-ease-standard);
}

.exits-motion-ambient {
  /* Continuous decorative motion only — Settings gear. */
}

