.exits-table__col--sku .exits-table__editor {
  width: 100%;
  min-width: 0;
  max-width: 100%;
}

.exits-table__col--numeric .exits-table__editor,
.exits-table__col--money .exits-table__editor {
  width: 100%;
  min-width: 0;
  max-width: 100%;
}

.exits-table__editor--start input {
  text-align: start;
}

/* Sticky Actions — SPECIAL USE / CANDIDATE (inline-end). */
.exits-table__cell--sticky-end,
.exits-table__head.exits-table__cell--sticky-end {
  position: sticky;
  inset-inline-end: 0;
  z-index: 2;
  background: var(--exits-surface, #fff);
  box-shadow: -6px 0 8px -6px color-mix(in srgb, var(--exits-foreground, #111) 18%, transparent);
}

[dir="rtl"] .exits-table__cell--sticky-end,
[dir="rtl"] .exits-table__head.exits-table__cell--sticky-end {
  box-shadow: 6px 0 8px -6px color-mix(in srgb, var(--exits-foreground, #111) 18%, transparent);
}

.exits-table__header .exits-table__cell--sticky-end {
  background: color-mix(in srgb, var(--exits-surface-muted, #eef2ef) 70%, transparent);
}

.exits-table__actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.2rem;
  white-space: nowrap;
  line-height: 1;
  vertical-align: middle;
}

/* Keep action icons denser than full form controls so they match table row rhythm. */
.exits-table__actions > button {
  width: var(--exits-table-action-size);
  height: var(--exits-table-action-size);
  min-width: var(--exits-table-action-size);
  min-height: var(--exits-table-action-size);
}

/* Quiet reset — ghost surface + Danger icon (not solid danger). */
.exits-table__action-reset {
  color: var(--exits-danger);
}

.exits-table__action-reset:hover {
  color: var(--exits-danger);
  background: color-mix(in srgb, var(--exits-danger-soft, #fef2f1) 70%, transparent);
}

.exits-table__action-reset:focus-visible {
  color: var(--exits-danger);
}

/* Quiet discard/cancel — ghost surface + Danger icon (not solid danger). */
.exits-table__action-cancel {
  color: var(--exits-danger);
}

.exits-table__action-cancel:hover {
  color: var(--exits-danger);
  background: color-mix(in srgb, var(--exits-danger-soft, #fef2f1) 70%, transparent);
}

.exits-table__action-cancel:focus-visible {
  color: var(--exits-danger);
}

.exits-table__editor {
  display: inline-flex;
  min-width: 0;
  max-width: 100%;
  width: 100%;
  flex-direction: column;
  justify-content: center;
  align-items: stretch;
  align-self: center;
  gap: 0;
  margin-inline-start: auto;
  min-height: var(--exits-table-inline-editor-height);
  line-height: 1;
  vertical-align: middle;
}

.exits-table__editor--start {
  margin-inline-start: 0;
  margin-inline-end: auto;
}

.exits-table__editor--end {
  margin-inline-start: auto;
  margin-inline-end: 0;
}

.exits-table__editor .exits-type-label {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Collapse Input label chrome so it cannot push the field below the row baseline. */
.exits-table__editor > div {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0 !important;
  min-height: var(--exits-table-inline-editor-height);
  width: 100%;
}

.exits-table__editor > div > div:first-child {
  display: none;
}

.exits-table__editor input,
.exits-table__editor select {
  height: var(--exits-table-inline-editor-height);
  min-height: var(--exits-table-inline-editor-height);
  max-height: var(--exits-table-inline-editor-height);
  padding-block: 0;
  padding-inline: 0.35rem;
  font-size: var(--exits-table-font-size);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

/* Stealth inline editor — table-native, not a dropped-in form control. */
.exits-table__editor--stealth input,
.exits-table__editor--stealth select {
  width: 100%;
  height: var(--exits-table-inline-editor-height) !important;
  min-height: var(--exits-table-inline-editor-height) !important;
  max-height: var(--exits-table-inline-editor-height) !important;
  padding-block: 0 !important;
  padding-inline: 0.35rem !important;
  background: transparent !important;
  border: 1px solid color-mix(in srgb, var(--exits-border, #d8e0da) 75%, transparent) !important;
  border-radius: var(--exits-radius-sm) !important;
  box-shadow: none !important;
  color: inherit;
  font: inherit;
  font-size: var(--exits-table-font-size) !important;
  font-weight: inherit;
  line-height: 1 !important;
  appearance: textfield;
  -moz-appearance: textfield;
}

.exits-table__editor--stealth input::-webkit-outer-spin-button,
.exits-table__editor--stealth input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.exits-table__editor--stealth input:hover,
.exits-table__editor--stealth select:hover {
  border-color: color-mix(in srgb, var(--exits-primary) 35%, var(--exits-border));
}

.exits-table__editor--stealth input:focus-visible,
.exits-table__editor--stealth select:focus-visible {
  outline: none !important;
  border-color: var(--exits-field-border-focus) !important;
  background: color-mix(in srgb, var(--exits-primary-soft, #e8f5e9) 40%, transparent) !important;
  box-shadow: 0 0 0 var(--exits-field-focus-ring-width) var(--exits-field-focus-ring) !important;
  --tw-ring-shadow: 0 0 #0000 !important;
}

.exits-table__editor--end input,
.exits-table__editor--end select {
  text-align: end;
}

.exits-table__editor--start input,
.exits-table__editor--start select {
  text-align: start;
}

.exits-table__editor--error input,
.exits-table__editor--error select,
.exits-table__editor--stealth.exits-table__editor--error input,
.exits-table__editor--stealth.exits-table__editor--error select {
  border-color: var(--exits-danger);
}

.exits-table__editor--stealth.exits-table__editor--error input:focus-visible,
.exits-table__editor--stealth.exits-table__editor--error select:focus-visible {
  border-color: var(--exits-field-border-error);
  background: color-mix(in srgb, var(--exits-danger-soft, #fee2e2) 35%, transparent);
  box-shadow: 0 0 0 var(--exits-field-focus-ring-width) var(--exits-field-focus-ring-error);
}

.exits-table__editor-error {
  margin: 0;
  max-width: 100%;
  color: var(--exits-danger);
  font-size: calc(var(--exits-table-font-size) * 0.85);
  line-height: 1.2;
  text-align: end;
}

.exits-table__editor--start .exits-table__editor-error {
  text-align: start;
}

.exits-table__row-error {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.35rem 0;
  color: var(--exits-danger);
  font-size: var(--exits-table-font-size);
}

.exits-table__row-validation {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.2rem var(--exits-table-cell-x) 0.45rem;
  color: var(--exits-danger);
  font-size: calc(var(--exits-table-font-size) * 0.9);
  line-height: 1.3;
}

.exits-table__row-validation-message {
  min-width: 0;
  flex: 1 1 auto;
}

.exits-table__row-validation-close {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: -0.15rem -0.25rem 0 0;
  padding: 0.15rem;
  border: 0;
  border-radius: var(--exits-radius-sm, 0.25rem);
  background: transparent;
  color: inherit;
  cursor: pointer;
  line-height: 1;
}

.exits-table__row-validation-close:hover {
  background: color-mix(in srgb, var(--exits-danger) 12%, transparent);
}

.exits-table__row-validation-close:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--exits-danger) 55%, transparent);
  outline-offset: 1px;
}

.exits-table__qty-edit {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.35rem;
  min-width: 0;
  width: 100%;
  min-height: var(--exits-table-inline-editor-height);
  line-height: 1;
  vertical-align: middle;
}

.exits-table__qty-edit .exits-table__editor {
  max-width: 4.25rem;
  flex: 0 1 auto;
  width: auto;
  min-width: 2.75rem;
}

.exits-table__uom {
  display: inline-flex;
  align-items: center;
  color: var(--exits-muted, #5b6b60);
  font-size: var(--exits-text-xs);
  line-height: 1;
  white-space: nowrap;
}

.exits-table .exits-table__uom {
  font-size: var(--exits-text-xs);
}

.exits-table__money-edit {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.25rem;
  min-width: 0;
  width: 100%;
  min-height: var(--exits-table-inline-editor-height);
  line-height: 1;
  vertical-align: middle;
}

.exits-table__money-edit .exits-table__editor {
  flex: 0 1 auto;
  width: auto;
  min-width: 3.5rem;
  max-width: 100%;
}

.exits-table__currency-prefix {
  display: inline-flex;
  align-items: center;
  color: var(--exits-muted, #5b6b60);
  font-size: var(--exits-table-font-size);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  white-space: nowrap;
}

.exits-table__cell--semibold {
  font-weight: var(--exits-font-weight-semibold);
}

.exits-table__cell--bold {
  font-weight: var(--exits-font-weight-bold);
}

.exits-table__footer {
  border-top: 1px solid var(--exits-border, #d8e0da);
  background: color-mix(in srgb, var(--exits-surface-muted, #eef2ef) 35%, transparent);
}

.exits-table__footer .exits-table__cell {
  height: var(--exits-table-row-height);
}

.exits-table-mobile {
  display: grid;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 0;
}

@media (min-width: 768px) {
  .exits-table-mobile {
    display: none;
  }
}

.exits-table-mobile__row {
  display: grid;
  gap: 0.2rem;
  padding: var(--exits-table-cell-y) var(--exits-table-cell-x);
  border-bottom: 1px solid color-mix(in srgb, var(--exits-border, #d8e0da) 60%, transparent);
  font-size: var(--exits-table-font-size);
}

.exits-table-mobile__row:last-child {
  border-bottom: none;
}

.exits-table-mobile__title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.exits-table-mobile__title {
  margin: 0;
  font-weight: var(--exits-font-weight-semibold);
}

.exits-table-mobile__total {
  margin: 0;
  font-weight: var(--exits-font-weight-semibold);
  font-variant-numeric: tabular-nums;
}

.exits-table-mobile__meta {
  margin: 0;
  color: var(--exits-muted, #5b6b60);
}

.exits-table-mobile__math {
  margin: 0;
  color: var(--exits-muted, #5b6b60);
  font-variant-numeric: tabular-nums;
}

/* ---- ExitsUpload (dropzone / tile / button) ---- */
.exits-upload {
  position: relative;
  min-width: 0;
}

.exits-upload--button {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.5rem;
}

.exits-upload__file-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
  max-width: 100%;
}

.exits-upload__file-chip {
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  gap: 0.25rem;
  min-height: 1.75rem;
  padding: 0.15rem 0.2rem 0.15rem 0.5rem;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-soft, var(--exits-radius-md));
  background: color-mix(in srgb, var(--exits-surface-muted) 50%, var(--exits-surface));
}

.exits-upload__file-name {
  max-width: 12rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--exits-text-xs, 0.75rem);
  color: var(--exits-foreground);
}

.exits-upload__file-remove {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  appearance: none;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--exits-muted);
  cursor: pointer;
}

.exits-upload__file-remove:hover {
  background: color-mix(in srgb, var(--exits-danger) 14%, transparent);
  color: var(--exits-danger);
}

.exits-upload__file-remove:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--exits-primary);
}

.exits-upload--dropzone,
.exits-upload--tile {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  border: 1px dashed color-mix(in srgb, var(--exits-border) 85%, var(--exits-muted));
  border-radius: var(--exits-radius-md);
  background: color-mix(in srgb, var(--exits-surface-muted) 55%, var(--exits-surface));
  color: var(--exits-muted);
  overflow: hidden;
  transition:
    border-color var(--exits-motion-fast) var(--exits-ease-standard),
    background-color var(--exits-motion-fast) var(--exits-ease-standard),
    box-shadow var(--exits-motion-fast) var(--exits-ease-standard);
}

.exits-upload--dropzone {
  min-height: 9.5rem;
  width: 100%;
}

.exits-upload--tile {
  width: 5.75rem;
  min-width: 5.75rem;
  height: 5.75rem;
  flex: 0 0 auto;
}

.exits-upload--dragging {
  border-color: var(--exits-primary);
  background: color-mix(in srgb, var(--exits-primary) 10%, var(--exits-surface));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--exits-primary) 25%, transparent);
}

.exits-upload--disabled {
  opacity: 0.55;
  pointer-events: none;
}

.exits-upload--filled {
  border-style: solid;
  background: var(--exits-surface);
}

.exits-upload__empty {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  min-height: inherit;
  padding: 0.75rem;
  cursor: pointer;
  text-align: center;
}

.exits-upload__empty:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--exits-primary);
}

.exits-upload__icon {
  width: 1.75rem;
  height: 1.75rem;
  color: color-mix(in srgb, var(--exits-muted) 80%, var(--exits-foreground));
}

.exits-upload--tile .exits-upload__icon {
  width: 1.35rem;
  height: 1.35rem;
}

.exits-upload__hint {
  margin: 0;
  max-width: 16rem;
  font-size: var(--exits-text-sm, 0.875rem);
  line-height: 1.35;
  color: var(--exits-muted);
}

.exits-upload__action {
  font-size: var(--exits-text-sm, 0.875rem);
  font-weight: var(--exits-font-weight-medium, 500);
  color: var(--exits-primary);
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

.exits-upload__preview {
  display: block;
  width: 100%;
  height: 100%;
  min-height: inherit;
  object-fit: cover;
}

.exits-upload--dropzone.exits-upload--filled {
  min-height: 10rem;
}

.exits-upload--dropzone .exits-upload__preview {
  position: absolute;
  inset: 0;
  min-height: 10rem;
}

.exits-upload--tile .exits-upload__preview {
  position: absolute;
  inset: 0;
}

.exits-upload__clear {
  position: absolute;
  top: 0.35rem;
  inset-inline-end: 0.35rem;
  z-index: 2;
  min-height: 1.75rem !important;
  min-width: 1.75rem !important;
  width: 1.75rem;
  height: 1.75rem;
  padding: 0 !important;
}

.exits-upload__replace {
  position: absolute;
  inset-inline-start: 0.5rem;
  bottom: 0.5rem;
  z-index: 2;
  appearance: none;
  border: 0;
  border-radius: var(--exits-radius-sm);
  background: color-mix(in srgb, var(--exits-surface) 88%, transparent);
  color: var(--exits-primary);
  font: inherit;
  font-size: var(--exits-text-xs, 0.75rem);
  font-weight: var(--exits-font-weight-medium, 500);
  text-decoration: underline;
  text-underline-offset: 0.12em;
  padding: 0.2rem 0.4rem;
  cursor: pointer;
}

.exits-upload__replace:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--exits-primary);
}

.exits-upload-gallery {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  min-width: 0;
}

/* ---- Responsive Data View (TABLE ↔ LIST) ---- */
.exits-responsive-data {
  min-width: 0;
}

.exits-responsive-data__toolbar {
  min-width: 0;
}

.exits-responsive-data--table .exits-responsive-data__list {
  display: none;
}

.exits-responsive-data--list .exits-responsive-data__table {
  display: none;
}

/* Override ExitsTable foundation md CSS when layout is driven by the shell. */
.exits-responsive-data--table .exits-table-scroll {
  display: block;
}

.exits-responsive-data--table .exits-table-mobile {
  display: none;
}

.exits-responsive-data--list .exits-table-scroll {
  display: none;
}

.exits-responsive-data--list .exits-table-mobile {
  display: grid;
}

/*
 * Exception only — keep tabular layout with intentional overflow-x.
 * Not the global default (prefer LIST on narrow viewports).
 */
.exits-responsive-data--h-scroll.exits-responsive-data--table .exits-table-scroll {
  display: block;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.exits-responsive-data--h-scroll .exits-responsive-data__list {
  display: none;
}

/* Structured list/card record (LIST mode). */
.exits-data-record {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.5rem;
  padding: var(--exits-table-cell-y, 0.5rem) var(--exits-table-cell-x, 0.75rem);
  border-bottom: 1px solid color-mix(in srgb, var(--exits-border) 60%, transparent);
  background: var(--exits-surface);
  color: var(--exits-text);
}

.exits-data-record:last-child {
  border-bottom: none;
}

.exits-data-record--selected {
  background: color-mix(in srgb, var(--exits-primary-soft) 80%, transparent);
}

.exits-data-record__top {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem 0.75rem;
}

.exits-data-record__identity {
  min-width: 0;
  flex: 1 1 10rem;
}

.exits-data-record__title {
  margin: 0;
  font-size: var(--exits-table-font-size, var(--exits-text-sm));
  font-weight: var(--exits-font-weight-semibold);
  line-height: 1.3;
}

.exits-data-record__subtitle {
  margin: 0.125rem 0 0;
  color: var(--exits-text-muted);
  font-size: var(--exits-text-xs);
  line-height: 1.35;
}

.exits-data-record__trailing {
  display: inline-flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.375rem;
}

.exits-data-record__actions {
  display: inline-flex;
  align-items: center;
  gap: 0.125rem;
}

.exits-data-record__fields {
  display: grid;
  margin: 0;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem 0.75rem;
}

@media (max-width: 379px) {
  .exits-data-record__fields {
    grid-template-columns: 1fr;
  }
}

.exits-data-record__field {
  min-width: 0;
}

.exits-data-record__field dt {
  margin: 0;
  color: var(--exits-text-muted);
  font-size: var(--exits-text-xs);
}

.exits-data-record__field dd {
  margin: 0.1rem 0 0;
  font-size: var(--exits-table-font-size, var(--exits-text-sm));
  font-variant-numeric: tabular-nums;
  line-height: 1.3;
}

.exits-data-record__value--emphasize {
  font-weight: var(--exits-font-weight-semibold);
}

.exits-data-record__details {
  min-width: 0;
  color: var(--exits-text-muted);
  font-size: var(--exits-text-xs);
}

.exits-data-record-list {
  display: grid;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 0;
  overflow: hidden;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
}

.exits-table-mobile__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: var(--exits-table-cell-y) var(--exits-table-cell-x);
  border-top: 1px solid var(--exits-border, #d8e0da);
  background: color-mix(in srgb, var(--exits-surface-muted, #eef2ef) 35%, transparent);
  font-size: var(--exits-table-font-size);
  font-weight: var(--exits-font-weight-bold);
}

.exits-table-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
