  gap: 0.5rem;
}

.stock-status-toolbar .exits-table-toolbar__controls {
  flex: 1 1 auto;
  flex-wrap: nowrap;
  align-items: center;
  min-width: 0;
  gap: 0.5rem;
}

.stock-status-toolbar .exits-table-toolbar__search {
