  min-width: 8rem;
  max-width: 12rem;
}

[data-testid="stock-status-table-desktop"] td.exits-table__col--flex {
  overflow: hidden;
}

[data-testid="stock-status-table-desktop"] .stock-status-col--product-link {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 767px) {
