.receive-remaining-table__head {
  white-space: normal;
  line-height: 1.25;
  vertical-align: bottom;
  overflow-wrap: anywhere;
}

.receive-remaining-table__grid {
  table-layout: auto;
}

.receive-remaining-table__row--unresolved {
  background: color-mix(in srgb, var(--exits-warning) 8%, transparent);
}

/* Transfer receive / review: long qty headers must not collide under fixed numeric widths. */
.transfer-receive-table .exits-table {
  min-width: 0;
  width: 100%;
  table-layout: auto;
}

.transfer-receive-table .exits-table__head {
  height: auto;
  min-height: var(--exits-table-header-height);
  white-space: normal;
  line-height: 1.25;
  vertical-align: bottom;
  overflow-wrap: anywhere;
  hyphens: auto;
}

.transfer-receive-table .exits-table__col--numeric {
  width: auto;
  min-width: 5.75rem;
  max-width: none;
}

.transfer-receive-table--review .exits-table {
  min-width: 0;
}

.transfer-receive-table--review .exits-table__col--numeric {
  min-width: 6.5rem;
}

@media (max-width: 47.99rem) {
  .receive-remaining-table__issue-col {
    display: none;
  }
}

.receive-remaining-choice {
  flex-wrap: nowrap;
  width: 100%;
  min-width: 0;
  gap: 0.375rem;
}

.receive-remaining-choice > button {
  flex: 1 1 0;
  min-width: 0;
}

.receive-remaining-choice > button > span {
  width: 100%;
  min-width: 0;
  padding-inline: 0.5rem;
  font-size: var(--exits-text-xs);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.incoming-order-stock-lines__table {
  min-width: 0;
}

.po-proposal-diff--down .po-document-totals__value {
  color: var(--exits-warning);
}

.po-proposal-diff--up .po-document-totals__value {
  color: var(--exits-success, #16a34a);
}

.incoming-order-print-root {
  display: none;
}

/* Off-screen host so Print/PDF work without embedding the A4 canvas in page flow */
.exits-bizdoc-print-host {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
  pointer-events: none;
}

/* Document preview overlay (desktop dialog / mobile full-screen) */
.exits-bizdoc-preview {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  align-items: stretch;
  justify-content: center;
}

.exits-bizdoc-preview__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
}

.exits-bizdoc-preview__panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100dvh;
  max-height: 100dvh;
  padding-top: env(safe-area-inset-top, 0px);
  padding-bottom: env(safe-area-inset-bottom, 0px);
  background: var(--exits-surface, #0f1218);
  border: 0;
  overflow: hidden;
}

.exits-bizdoc-preview__toolbar {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.65rem 0.85rem;
  border-bottom: 1px solid var(--exits-border, rgba(255, 255, 255, 0.12));
  background: var(--exits-surface, #0f1218);
}

.exits-bizdoc-preview__toolbar-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.5rem;
}

.exits-bizdoc-preview__canvas {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  -webkit-overflow-scrolling: touch;
  padding: 0.75rem;
  background: #e5e7eb;
}

.exits-bizdoc-preview__canvas .exits-bizdoc {
  width: 100%;
  max-width: 210mm;
  margin-inline: auto;
  background: #ffffff;
  color: #111827;
}

@media (min-width: 768px) {
  .exits-bizdoc-preview {
    align-items: center;
    padding: 1.25rem;
  }

  .exits-bizdoc-preview__panel {
    width: min(100%, 52rem);
    height: min(94dvh, 56rem);
    max-height: 94dvh;
    border-radius: var(--exits-radius-lg, 0.75rem);
    border: 1px solid var(--exits-border, rgba(255, 255, 255, 0.12));
    box-shadow: var(--exits-shadow-lg, 0 24px 64px rgba(0, 0, 0, 0.35));
    padding-top: 0;
    padding-bottom: 0;
  }

  .exits-bizdoc-preview__canvas {
    padding: 1.25rem 1.5rem;
  }
}

@media (max-width: 767px) {
  .exits-bizdoc-preview__canvas .exits-bizdoc {
    /* Fit width on narrow viewports; horizontal scroll if content needs A4 width */
    max-width: 100%;
  }
}

/* ===== ExItS Business Document shell (A4 / print / PDF) ===== */
.exits-bizdoc {
  --bizdoc-fg: #111827;
  --bizdoc-muted: #4b5563;
  --bizdoc-border: #d1d5db;
  --bizdoc-bg: #ffffff;
  box-sizing: border-box;
  width: 100%;
  max-width: 210mm;
  margin-inline: auto;
  padding: 12mm 14mm;
  color: var(--bizdoc-fg);
  background: var(--bizdoc-bg);
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 10.5pt;
  line-height: 1.35;
  overflow-x: hidden;
}

.exits-bizdoc--preview {
  border: 1px solid var(--exits-border, var(--bizdoc-border));
