  height: 3.25rem;
  object-fit: contain;
  flex-shrink: 0;
}

.exits-bizdoc__business-name {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.exits-bizdoc__branch-name,
.exits-bizdoc__identity-line {
  margin: 0.1rem 0 0;
  color: var(--bizdoc-muted);
  font-size: 0.92em;
  white-space: pre-wrap;
}

.exits-bizdoc__header-right {
  text-align: right;
  min-width: 9rem;
}

.exits-bizdoc__doc-title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.exits-bizdoc__doc-ref,
.exits-bizdoc__doc-date,
.exits-bizdoc__doc-status {
  margin: 0.25rem 0 0;
  color: var(--bizdoc-muted);
