}

.exits-bizdoc__doc-status {
  font-weight: 600;
  color: var(--bizdoc-fg);
}

.exits-bizdoc__parties {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1rem;
}

@media (max-width: 40rem) {
  .exits-bizdoc__header {
    grid-template-columns: 1fr;
  }

  .exits-bizdoc__header-right {
    text-align: left;
  }

  .exits-bizdoc__parties {
    grid-template-columns: 1fr;
  }
}

.exits-bizdoc__party-label,
.exits-bizdoc__section-title {
  margin: 0 0 0.35rem;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bizdoc-muted);
}

.exits-bizdoc__party-name {
  margin: 0;
  font-weight: 650;
}

.exits-bizdoc__party-line {
  margin: 0.15rem 0 0;
  color: var(--bizdoc-muted);
  font-size: 0.92em;
  white-space: pre-wrap;
}

.exits-bizdoc__meta {
  margin: 0;
  display: grid;
  gap: 0.35rem;
}

.exits-bizdoc__meta-row {
  display: grid;
  grid-template-columns: minmax(6rem, 40%) 1fr;
  gap: 0.5rem;
}

.exits-bizdoc__meta-row dt {
  margin: 0;
  color: var(--bizdoc-muted);
}

.exits-bizdoc__meta-row dd {
  margin: 0;
  font-weight: 550;
  text-align: right;
}

.exits-bizdoc__table {
  width: 100%;
  border-collapse: collapse;
  margin: 0.25rem 0 1rem;
}

.exits-bizdoc__table thead {
  display: table-header-group;
}

.exits-bizdoc__table th,
.exits-bizdoc__table td {
  border-bottom: 1px solid var(--bizdoc-border);
  padding: 0.4rem 0.35rem;
  vertical-align: top;
  text-align: left;
}

.exits-bizdoc__table th {
