}

/* Important: beat any later table/text utilities that reset cell alignment. */
.exits-bizdoc__table th.is-right,
.exits-bizdoc__table td.is-right {
  text-align: end !important;
}

.exits-bizdoc__table th.is-center,
.exits-bizdoc__table td.is-center {
  text-align: center !important;
}

.exits-bizdoc__table-row {
  break-inside: avoid;
  page-break-inside: avoid;
}

.exits-bizdoc__totals {
  margin-left: auto;
  width: min(100%, 16rem);
  display: grid;
  gap: 0.3rem;
  margin-bottom: 1rem;
}

.exits-bizdoc__totals-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.exits-bizdoc__totals-row.is-emphasize {
  margin-top: 0.25rem;
  padding-top: 0.35rem;
