  font-size: 1.05em;
}

.exits-bizdoc__notes {
  margin-bottom: 1rem;
}

.exits-bizdoc__notes-body {
  margin: 0;
  white-space: pre-wrap;
  color: var(--bizdoc-muted);
}

.exits-bizdoc__signatures {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: 1.5rem;
  margin: 1.75rem 0 1rem;
}

.exits-bizdoc__signature-line {
  border-bottom: 1px solid var(--bizdoc-fg);
  height: 2.25rem;
  margin-bottom: 0.35rem;
}

.exits-bizdoc__signature-label,
.exits-bizdoc__signature-name {
  margin: 0;
  font-size: 0.85em;
  color: var(--bizdoc-muted);
}

.exits-bizdoc__footer {
  margin-top: 1.25rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--bizdoc-border);
  text-align: center;
}

.exits-bizdoc__footer-thanks {
  margin: 0;
  font-weight: 550;
}

.exits-bizdoc__footer-contact,
.exits-bizdoc__footer-disclaimer,
.exits-bizdoc__footer-extended,
.exits-bizdoc__page-number {
  margin: 0.35rem 0 0;
  font-size: 0.82em;
  color: var(--bizdoc-muted);
}

.exits-bizdoc__footer-disclaimer {
  font-weight: 650;
  letter-spacing: 0.02em;
