  font-weight: 700;
  color: var(--exits-muted, #5b6b60);
  text-align: start;
}

.exits-table-pagination__range {
  margin: 0;
  flex: 1 1 auto;
}

.exits-table-pagination__size {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  white-space: nowrap;
  font-size: var(--exits-text-md, 0.9375rem);
}

.exits-table-pagination__size-label {
  color: inherit;
  font-size: inherit;
  font-weight: 500;
  line-height: 1.25;
}

/* Borderless closed field: value + space + solid caret (width auto). */
.exits-table-pagination__size-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  width: auto;
  min-width: 0;
  min-height: var(--exits-control-height);
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: inherit;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}

.exits-table-pagination__size-trigger:focus-visible {
  outline: 2px solid var(--exits-focus, var(--exits-primary));
  outline-offset: 2px;
  border-radius: 2px;
}

.exits-table-pagination__size-value {
  font-size: inherit;
  font-weight: 500;
  line-height: 1;
}

.exits-table-pagination__size-caret {
  display: inline-block;
  width: 0;
  height: 0;
  border-left: 0.32rem solid transparent;
  border-right: 0.32rem solid transparent;
  border-top: 0.4rem solid currentColor;
  opacity: 0.72;
}

/* Quasar QSelect/QItem page-size menu (standard, not dense). */
.exits-table-pagination__size-menu {
  min-width: 0 !important;
  width: max-content;
  max-width: none;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 4px;
  overflow: hidden;
  background: #fff;
  color: rgba(0, 0, 0, 0.87);
  box-shadow:
    0 1px 5px rgba(0, 0, 0, 0.2),
    0 2px 2px rgba(0, 0, 0, 0.14),
    0 3px 1px -2px rgba(0, 0, 0, 0.12);
}

/* Dense option rows: tighter vertical gap between 10 / 25 / …. */
.exits-table-pagination__size-menu .exits-table-pagination__size-option {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0 !important;
  box-sizing: border-box;
  min-width: 2.5rem;
  min-height: 32px;
  height: auto;
  margin: 0;
  padding: 2px 8px !important;
  border: 0;
  border-radius: 0;
  text-align: center;
  font-size: 14px !important;
  font-weight: 400 !important;
  line-height: 1.25;
  letter-spacing: 0.01em;
  font-variant-numeric: tabular-nums;
  color: inherit;
  background: transparent !important;
  transition: color 0.3s, background-color 0.3s;
}

/* Selected = primary color only (Quasar .q-item--active), not bold. */
.exits-table-pagination__size-menu .exits-table-pagination__size-option--selected {
  color: var(--exits-primary, #1976d2) !important;
  background: transparent !important;
  font-weight: 400 !important;
}

/* Hover/focus = full-width gray bar (Quasar focus helper). */
.exits-table-pagination__size-menu .exits-table-pagination__size-option:hover,
.exits-table-pagination__size-menu .exits-table-pagination__size-option:focus-visible {
  background: rgba(0, 0, 0, 0.15) !important;
}

.exits-table-pagination__size-menu .exits-table-pagination__size-option--selected:hover,
.exits-table-pagination__size-menu .exits-table-pagination__size-option--selected:focus-visible {
  color: var(--exits-primary, #1976d2) !important;
  background: rgba(0, 0, 0, 0.15) !important;
}

[data-theme="dark"] .exits-table-pagination__size-menu {
  background: #1d1d1d;
  color: #fff;
  box-shadow:
    0 1px 5px rgba(0, 0, 0, 0.5),
    0 2px 2px rgba(0, 0, 0, 0.36),
    0 3px 1px -2px rgba(0, 0, 0, 0.3);
}

[data-theme="dark"] .exits-table-pagination__size-menu .exits-table-pagination__size-option {
  color: #fff;
}

[data-theme="dark"] .exits-table-pagination__size-menu .exits-table-pagination__size-option--selected {
  color: #ffc107 !important;
}

[data-theme="dark"] .exits-table-pagination__size-menu .exits-table-pagination__size-option:hover,
[data-theme="dark"] .exits-table-pagination__size-menu .exits-table-pagination__size-option:focus-visible,
[data-theme="dark"] .exits-table-pagination__size-menu .exits-table-pagination__size-option--selected:hover,
[data-theme="dark"] .exits-table-pagination__size-menu .exits-table-pagination__size-option--selected:focus-visible {
  background: rgba(255, 255, 255, 0.15) !important;
}

.exits-table-pagination__nav {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

.exits-table-pagination__page {
  min-width: 1.5rem;
  text-align: center;
  font-variant-numeric: tabular-nums;
  color: var(--exits-text, inherit);
  font-weight: var(--exits-font-weight-medium);
}

.exits-table-pagination__btn {
  display: inline-flex;
  min-height: var(--exits-control-height);
  align-items: center;
  gap: 0.2rem;
  padding: 0 0.55rem;
  border: 1px solid var(--exits-border, #d8e0da);
  border-radius: var(--exits-radius-sm);
  background: var(--exits-surface, #fff);
  color: var(--exits-text, inherit);
  font: inherit;
  font-size: inherit;
  cursor: pointer;
}

.exits-table-pagination__btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.exits-table-pagination__btn:focus-visible {
  outline: 2px solid var(--exits-focus, var(--ring));
  outline-offset: 1px;
}

@media (max-width: 767px) {
  .exits-table-toolbar {
    align-items: stretch;
  }

  .exits-table-toolbar__end {
    width: 100%;
    margin-left: 0;
    justify-content: space-between;
  }

  .exits-table-output:not(.exits-table-output--icons) .exits-table-output__desktop {
    display: none;
  }

  .exits-table-output:not(.exits-table-output--icons) .exits-table-output__mobile {
    display: inline-flex;
  }

  .exits-table-output--icons .exits-table-output__desktop {
    display: inline-flex;
  }

  .exits-table-pagination {
    flex-direction: column;
    align-items: stretch;
  }

  .exits-table-pagination__nav {
    width: 100%;
    justify-content: center;
    gap: 0.5rem;
  }
}

/* Device-preview LIST mode (frame may be narrow while the browser viewport is still wide). */
.exits-responsive-data--list .exits-table-pagination {
  flex-direction: column;
  align-items: stretch;
}

.exits-responsive-data--list .exits-table-pagination__nav {
  width: 100%;
  justify-content: center;
  gap: 0.5rem;
}

body {
  margin: 0;
  background: var(--exits-bg);
  color: var(--exits-text);
  font-family: var(--exits-font-sans);
  font-size: var(--exits-type-body);
  font-weight: var(--exits-font-weight-regular);
  line-height: var(--exits-leading-normal);
  letter-spacing: var(--exits-tracking-normal);
  overflow-x: hidden;
}

/* Viewport-locked shells own vertical scroll. Prevent a second document scrollbar. */
html:has(.operations-shell--viewport-lock),
html:has(.admin-shell),
html:has(.personal-shell) {
  height: 100%;
  max-height: 100dvh;
  overflow: hidden;
}

html:has(.operations-shell--viewport-lock) body,
html:has(.admin-shell) body,
html:has(.personal-shell) body,
html:has(.operations-shell--viewport-lock) #root,
html:has(.admin-shell) #root,
html:has(.personal-shell) #root {
  height: 100%;
  max-height: 100dvh;
  overflow: hidden;
}

*:focus-visible {
  outline: 3px solid var(--exits-ring);
  outline-offset: 2px;
}

/* ---- Global surface primitives (semantic classes; prefer tokens inside) ---- */
.exits-page {
  background: var(--exits-bg);
  color: var(--exits-text);
  width: 100%;
  min-width: 0;
}

/* Mobile / narrow: slightly tighter content gutter (shell may also apply safe-area). */
@media (max-width: 767px) {
  :root,
  [data-density="balance"],
  [data-density="compact"],
  [data-density="comfort"] {
    --exits-page-gutter-inline: 0.875rem;
  }
}

@media (min-width: 768px) and (max-width: 1023px) {
  :root,
  [data-density="balance"] {
    --exits-page-gutter-inline: 1rem;
  }

  [data-density="compact"] {
    --exits-page-gutter-inline: 0.875rem;
  }

  [data-density="comfort"] {
    --exits-page-gutter-inline: 1.25rem;
  }
}

.exits-panel,
.exits-card {
  background: var(--exits-surface);
  color: var(--exits-text);
  border: 1px solid color-mix(in srgb, var(--exits-border) 88%, transparent);
  border-radius: var(--exits-radius-md);
  box-shadow: none;
}

.exits-card--raised,
.exits-panel--raised {
  background: var(--exits-surface-elevated);
  box-shadow: var(--exits-shadow-sm);
}

.exits-card--interactive,
.exits-panel--interactive {
  transition:
    border-color var(--exits-motion-fast) var(--exits-ease-standard),
    background-color var(--exits-motion-fast) var(--exits-ease-standard),
    box-shadow var(--exits-motion-fast) var(--exits-ease-standard);
}

.exits-card--interactive:hover,
.exits-panel--interactive:hover {
  border-color: var(--exits-border-strong);
  box-shadow: var(--exits-shadow-sm);
}

.exits-card[data-treatment="surface"] {
  background: color-mix(in srgb, var(--exits-surface-muted) 35%, var(--exits-surface));
  border-color: transparent;
  box-shadow: none;
}

.exits-card[data-treatment="bordered"] {
  background: var(--exits-surface);
  border-color: color-mix(in srgb, var(--exits-border) 88%, transparent);
  box-shadow: none;
}

.exits-card[data-treatment="elevated"],
.exits-card--raised {
  background: var(--exits-surface);
  border-color: color-mix(in srgb, var(--exits-border) 70%, transparent);
  box-shadow: var(--exits-shadow-md);
}

.exits-card[data-treatment="interactive"],
.exits-card--interactive {
  background: var(--exits-surface);
  border-color: color-mix(in srgb, var(--exits-primary) 28%, var(--exits-border));
  box-shadow: none;
  cursor: pointer;
}

.exits-card[data-treatment="interactive"]:hover,
.exits-card--interactive:hover {
  border-color: color-mix(in srgb, var(--exits-primary) 45%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-surface-muted) 55%, var(--exits-surface));
  box-shadow: var(--exits-shadow-sm);
}

.exits-card--selected,
.exits-panel--selected,
.exits-card[data-treatment="selected"],
.exits-card[data-selected="true"] {
  background: var(--exits-primary-soft);
  border-color: color-mix(in srgb, var(--exits-primary) 55%, var(--exits-border));
  box-shadow: none;
}

.exits-card[data-treatment="featured"] {
  background: color-mix(in srgb, var(--exits-primary) 6%, var(--exits-surface));
  border-color: color-mix(in srgb, var(--exits-primary) 45%, var(--exits-border));
  box-shadow: var(--exits-shadow-sm);
}

.exits-card[data-treatment="accent"][data-accent-position="tint"][data-accent-tone="primary"] {
  background: color-mix(in srgb, var(--exits-primary) 8%, var(--exits-surface));
  border-color: color-mix(in srgb, var(--exits-primary) 35%, var(--exits-border));
}

.exits-card[data-treatment="accent"][data-accent-position="tint"][data-accent-tone="info"] {
  background: color-mix(in srgb, var(--exits-info) 8%, var(--exits-surface));
  border-color: color-mix(in srgb, var(--exits-info) 35%, var(--exits-border));
}

.exits-card[data-treatment="accent"][data-accent-position="tint"][data-accent-tone="success"] {
  background: color-mix(in srgb, var(--exits-success) 8%, var(--exits-surface));
  border-color: color-mix(in srgb, var(--exits-success) 35%, var(--exits-border));
}

.exits-card[data-treatment="accent"][data-accent-position="tint"][data-accent-tone="warning"] {
  background: color-mix(in srgb, var(--exits-warning) 8%, var(--exits-surface));
  border-color: color-mix(in srgb, var(--exits-warning) 35%, var(--exits-border));
}

.exits-card[data-treatment="accent"][data-accent-position="tint"][data-accent-tone="danger"] {
  background: color-mix(in srgb, var(--exits-danger) 8%, var(--exits-surface));
  border-color: color-mix(in srgb, var(--exits-danger) 35%, var(--exits-border));
}

button.exits-card {
  font: inherit;
  color: inherit;
}

.exits-metric-surface {
  background: var(--exits-surface);
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-md);
}

.exits-alert-surface {
  background: var(--exits-warning-soft);
  border: 1px solid color-mix(in srgb, var(--exits-warning) 35%, var(--exits-border));
  border-radius: var(--exits-radius-md);
  color: var(--exits-text);
}

.exits-alert-surface--danger {
  background: var(--exits-danger-soft);
  border-color: color-mix(in srgb, var(--exits-danger) 35%, var(--exits-border));
}

.exits-alert-surface--success {
  background: var(--exits-success-soft);
  border-color: color-mix(in srgb, var(--exits-success) 35%, var(--exits-border));
}

/* ---- Global typography primitives ---- */
.exits-type-page-title {
  font-size: var(--exits-type-page-title);
  font-weight: var(--exits-font-weight-semibold);
  line-height: var(--exits-leading-tight);
  letter-spacing: -0.015em;
  color: var(--exits-text);
}

.exits-type-section-title {
  font-size: var(--exits-type-section-title);
  font-weight: var(--exits-font-weight-semibold);
  line-height: var(--exits-leading-tight);
  color: var(--exits-text);
}

.exits-type-card-title {
  font-size: var(--exits-type-card-title);
  font-weight: var(--exits-font-weight-medium);
  line-height: var(--exits-leading-tight);
  color: var(--exits-text);
}

.exits-type-label {
  font-size: var(--exits-type-label);
  font-weight: var(--exits-font-weight-medium);
  line-height: var(--exits-leading-normal);
}

.exits-type-body {
  font-size: var(--exits-type-body);
  font-weight: var(--exits-font-weight-regular);
  line-height: var(--exits-leading-normal);
}

.exits-type-muted {
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-regular);
  line-height: var(--exits-leading-relaxed);
  color: var(--exits-text-muted);
}

.exits-type-kpi {
  font-size: var(--exits-type-kpi);
  font-weight: var(--exits-font-weight-semibold);
  line-height: var(--exits-leading-tight);
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.exits-type-hero-kpi {
  font-size: var(--exits-type-hero-kpi);
  font-weight: var(--exits-font-weight-semibold);
  line-height: var(--exits-leading-tight);
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.exits-type-eyebrow {
  font-size: var(--exits-type-caption);
  font-weight: var(--exits-font-weight-medium);
  letter-spacing: var(--exits-tracking-eyebrow);
  text-transform: uppercase;
  color: var(--exits-text-muted);
  line-height: var(--exits-leading-tight);
}

/*
 * Slim read-only status / attribute pills.
 * Separate from interactive .exits-chip (filter/toolbar density).
 * Balance: 26px vs interactive chips 36px.
 */
.exits-status-chip {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: var(--exits-status-chip-gap);
  box-sizing: border-box;
  height: var(--exits-status-chip-height);
  min-height: var(--exits-status-chip-height);
  max-height: var(--exits-status-chip-height);
  padding: 0 var(--exits-status-chip-padding-x);
  border-style: solid;
  border-width: var(--exits-status-chip-border-width);
  border-radius: 9999px;
  font-size: var(--exits-status-chip-font-size);
  font-weight: var(--exits-font-weight-medium);
  letter-spacing: var(--exits-tracking-normal);
  line-height: 1;
  white-space: nowrap;
  cursor: default;
  user-select: none;
  pointer-events: none;
}

.exits-status-chip__icon {
  display: inline-flex;
  flex-shrink: 0;
  width: var(--exits-status-chip-icon-size);
  height: var(--exits-status-chip-icon-size);
}

.exits-status-chip__icon > svg {
  width: 100%;
  height: 100%;
}

/* Soft appearance (default) — quiet tinted fill + soft border. */
.exits-status-chip--success {
  color: var(--exits-success);
  border-color: color-mix(in srgb, var(--exits-success) 28%, transparent);
  background: var(--exits-success-soft);
}

.exits-status-chip--info {
  color: var(--exits-info);
  border-color: color-mix(in srgb, var(--exits-info) 28%, transparent);
  background: color-mix(in srgb, var(--exits-info) 12%, var(--exits-surface));
}

.exits-status-chip--warning {
  color: var(--exits-warning);
  border-color: color-mix(in srgb, var(--exits-warning) 28%, transparent);
  background: var(--exits-warning-soft);
}

.exits-status-chip--danger {
  color: var(--exits-danger);
  border-color: color-mix(in srgb, var(--exits-danger) 28%, transparent);
  background: var(--exits-danger-soft);
}

.exits-status-chip--neutral {
  color: var(--exits-text-muted);
  border-color: color-mix(in srgb, var(--exits-border-strong) 55%, transparent);
  background: color-mix(in srgb, var(--exits-surface-muted) 70%, var(--exits-surface));
}

.exits-status-chip--primary {
  color: var(--exits-primary);
  border-color: color-mix(in srgb, var(--exits-primary) 28%, transparent);
  background: var(--exits-primary-soft);
}

.exits-status-chip--secondary {
  color: var(--exits-severity-secondary-foreground);
  border-color: color-mix(in srgb, var(--exits-severity-secondary-foreground) 18%, transparent);
  background: var(--exits-severity-secondary);
}

.exits-status-chip--help {
  color: var(--exits-severity-help);
  border-color: color-mix(in srgb, var(--exits-severity-help) 28%, transparent);
  background: color-mix(in srgb, var(--exits-severity-help) 12%, var(--exits-surface));
}

.exits-status-chip--contrast {
  color: var(--exits-severity-contrast-foreground);
  border-color: var(--exits-severity-contrast);
  background: var(--exits-severity-contrast);
}

/*
 * Emphasis — Diamond Tag soft look: bold tone-colored ink on a pale wash.
 * Separate from Soft (quiet), Outline (border only), and Solid (filled contrast ink).
 */
.exits-status-chip--appearance-emphasis {
  font-weight: var(--exits-font-weight-bold);
  border-color: transparent;
}

.exits-status-chip--appearance-emphasis.exits-status-chip--success {
  color: color-mix(in srgb, var(--exits-severity-success) 42%, #14532d);
  background: color-mix(in srgb, var(--exits-severity-success) 16%, #ffffff);
}

.exits-status-chip--appearance-emphasis.exits-status-chip--info {
  color: color-mix(in srgb, var(--exits-severity-info) 48%, #0c4a6e);
  background: color-mix(in srgb, var(--exits-severity-info) 14%, #ffffff);
}

.exits-status-chip--appearance-emphasis.exits-status-chip--warning {
  color: color-mix(in srgb, var(--exits-severity-warn) 40%, #9a3412);
  background: color-mix(in srgb, var(--exits-severity-warn) 16%, #ffffff);
}

.exits-status-chip--appearance-emphasis.exits-status-chip--danger {
  color: color-mix(in srgb, var(--exits-severity-danger) 42%, #991b1b);
  background: color-mix(in srgb, var(--exits-severity-danger) 14%, #ffffff);
}

.exits-status-chip--appearance-emphasis.exits-status-chip--neutral {
  color: var(--exits-text-muted);
  background: color-mix(in srgb, var(--exits-surface-muted) 80%, var(--exits-surface));
}

.exits-status-chip--appearance-emphasis.exits-status-chip--primary {
  color: var(--exits-primary);
  background: color-mix(in srgb, var(--exits-primary) 14%, #ffffff);
}

.exits-status-chip--appearance-emphasis.exits-status-chip--secondary {
  color: var(--exits-severity-secondary-foreground);
  background: var(--exits-severity-secondary);
}

.exits-status-chip--appearance-emphasis.exits-status-chip--help {
  color: color-mix(in srgb, var(--exits-severity-help) 45%, #6b21a8);
  background: color-mix(in srgb, var(--exits-severity-help) 14%, #ffffff);
}

.exits-status-chip--appearance-emphasis.exits-status-chip--contrast {
  color: var(--exits-severity-contrast-foreground);
  background: var(--exits-severity-contrast);
}

[data-theme="dark"] .exits-status-chip--appearance-emphasis.exits-status-chip--success {
  color: var(--exits-severity-success);
  background: color-mix(in srgb, var(--exits-severity-success) 18%, var(--exits-surface));
}

[data-theme="dark"] .exits-status-chip--appearance-emphasis.exits-status-chip--info {
  color: var(--exits-severity-info);
  background: color-mix(in srgb, var(--exits-severity-info) 18%, var(--exits-surface));
}

[data-theme="dark"] .exits-status-chip--appearance-emphasis.exits-status-chip--warning {
  color: var(--exits-severity-warn);
  background: color-mix(in srgb, var(--exits-severity-warn) 18%, var(--exits-surface));
}

[data-theme="dark"] .exits-status-chip--appearance-emphasis.exits-status-chip--danger {
  color: var(--exits-severity-danger);
  background: color-mix(in srgb, var(--exits-severity-danger) 18%, var(--exits-surface));
}

[data-theme="dark"] .exits-status-chip--appearance-emphasis.exits-status-chip--primary {
  color: var(--exits-primary);
  background: color-mix(in srgb, var(--exits-primary) 18%, var(--exits-surface));
}

[data-theme="dark"] .exits-status-chip--appearance-emphasis.exits-status-chip--help {
  color: var(--exits-severity-help);
  background: color-mix(in srgb, var(--exits-severity-help) 18%, var(--exits-surface));
}

[data-theme="dark"] .exits-status-chip--appearance-emphasis.exits-status-chip--neutral {
  color: var(--exits-text-muted);
  background: color-mix(in srgb, var(--exits-surface-muted) 70%, var(--exits-surface));
}

/* Outline — border + label only; transparent fill. */
.exits-status-chip--appearance-outline {
  background: transparent;
}

.exits-status-chip--appearance-outline.exits-status-chip--success {
  border-color: color-mix(in srgb, var(--exits-success) 55%, transparent);
}

.exits-status-chip--appearance-outline.exits-status-chip--info {
  border-color: color-mix(in srgb, var(--exits-info) 55%, transparent);
}

.exits-status-chip--appearance-outline.exits-status-chip--warning {
  border-color: color-mix(in srgb, var(--exits-warning) 55%, transparent);
}

.exits-status-chip--appearance-outline.exits-status-chip--danger {
  border-color: color-mix(in srgb, var(--exits-danger) 55%, transparent);
}

.exits-status-chip--appearance-outline.exits-status-chip--neutral {
  border-color: color-mix(in srgb, var(--exits-border-strong) 75%, transparent);
}

.exits-status-chip--appearance-outline.exits-status-chip--primary {
  border-color: color-mix(in srgb, var(--exits-primary) 55%, transparent);
}

.exits-status-chip--appearance-outline.exits-status-chip--secondary {
  border-color: color-mix(in srgb, var(--exits-severity-secondary-foreground) 35%, transparent);
  color: var(--exits-severity-secondary-foreground);
}

.exits-status-chip--appearance-outline.exits-status-chip--help {
  border-color: color-mix(in srgb, var(--exits-severity-help) 55%, transparent);
  color: var(--exits-severity-help);
}

.exits-status-chip--appearance-outline.exits-status-chip--contrast {
  border-color: var(--exits-severity-contrast);
  color: var(--exits-severity-contrast);
}

/* Solid — filled tone surface; contrast ink. */
.exits-status-chip--appearance-solid.exits-status-chip--success {
  color: #ffffff;
  border-color: var(--exits-success);
  background: var(--exits-success);
}

.exits-status-chip--appearance-solid.exits-status-chip--info {
  color: #ffffff;
  border-color: var(--exits-info);
  background: var(--exits-info);
}

.exits-status-chip--appearance-solid.exits-status-chip--warning {
  color: #ffffff;
  border-color: var(--exits-warning);
  background: var(--exits-warning);
}

.exits-status-chip--appearance-solid.exits-status-chip--danger {
  color: #ffffff;
  border-color: var(--exits-danger);
  background: var(--exits-danger);
}

.exits-status-chip--appearance-solid.exits-status-chip--neutral {
  color: var(--exits-text);
  border-color: var(--exits-border-strong);
  background: var(--exits-surface-muted);
}

.exits-status-chip--appearance-solid.exits-status-chip--primary {
  color: var(--exits-primary-foreground);
  border-color: var(--exits-primary);
  background: var(--exits-primary);
}

.exits-status-chip--appearance-solid.exits-status-chip--secondary {
  color: var(--exits-severity-secondary-foreground);
  border-color: var(--exits-severity-secondary);
  background: var(--exits-severity-secondary);
}

.exits-status-chip--appearance-solid.exits-status-chip--help {
  color: var(--exits-severity-help-foreground);
  border-color: var(--exits-severity-help);
  background: var(--exits-severity-help);
}

.exits-status-chip--appearance-solid.exits-status-chip--contrast {
  color: var(--exits-severity-contrast-foreground);
  border-color: var(--exits-severity-contrast);
  background: var(--exits-severity-contrast);
}

[data-theme="dark"] .exits-status-chip--appearance-solid.exits-status-chip--success,
[data-theme="dark"] .exits-status-chip--appearance-solid.exits-status-chip--info,
[data-theme="dark"] .exits-status-chip--appearance-solid.exits-status-chip--warning,
[data-theme="dark"] .exits-status-chip--appearance-solid.exits-status-chip--danger,
[data-theme="dark"] .exits-status-chip--appearance-solid.exits-status-chip--help {
  color: var(--exits-bg);
}

/* Shape — independent from tone / appearance (default pill via base border-radius). */
.exits-status-chip--shape-auto {
  border-radius: var(--exits-control-radius);
}

.exits-status-chip--shape-standard {
  border-radius: var(--exits-radius-control);
}

.exits-status-chip--shape-soft {
  /* Align with Button / Preferences Control Shape Soft (not appearance soft). */
  border-radius: var(--exits-radius-soft);
}

.exits-status-chip--shape-square {
  border-radius: var(--exits-radius-xs);
  height: var(--exits-chip-square-height);
  min-height: var(--exits-chip-square-height);
  max-height: var(--exits-chip-square-height);
  padding: var(--exits-chip-square-padding-y) var(--exits-chip-square-padding-x);
  font-size: var(--exits-chip-square-font-size);
  gap: var(--exits-chip-square-gap);
}

.exits-status-chip--shape-square .exits-status-chip__icon {
  width: var(--exits-chip-square-icon-size);
  height: var(--exits-chip-square-icon-size);
}

/* Control density — match adjacent Button height + text-sm (process headers). */
.exits-status-chip--control {
  height: var(--exits-control-height);
  min-height: var(--exits-control-height);
  max-height: var(--exits-control-height);
  padding: 0 var(--exits-control-padding-x);
  gap: 0.5rem;
  font-size: var(--exits-text-sm);
}

.exits-status-chip--control .exits-status-chip__icon {
  width: 1rem;
  height: 1rem;
}

/*
 * Reusable management entity / list card foundation.
 * Content-driven height; density tokens own padding/gaps.
 * Apply first to Branches; migrate Staff/Suppliers/etc. later.
 */
.exits-entity-card {
  display: flex;
  flex-direction: column;
  gap: var(--exits-entity-card-gap);
  min-width: 0;
  width: 100%;
  height: auto;
  padding: var(--exits-list-card-padding-y) var(--exits-list-card-padding-x);
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
  color: var(--exits-text);
  box-shadow: none;
  transition:
    border-color var(--exits-motion-fast) var(--exits-ease-standard),
    box-shadow var(--exits-motion-fast) var(--exits-ease-standard),
    background-color var(--exits-motion-fast) var(--exits-ease-standard);
}

.exits-entity-card--interactive:hover {
  border-color: var(--exits-border-strong);
  box-shadow: var(--exits-shadow-sm);
}

.exits-entity-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.65rem;
  min-width: 0;
}

.exits-entity-card__identity {
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 0.15rem;
}

.exits-entity-card__title-row {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.45rem;
}

.exits-entity-card__title {
  margin: 0;
  min-width: 0;
  font-size: var(--exits-type-card-title);
  font-weight: var(--exits-font-weight-semibold);
  line-height: var(--exits-leading-tight);
  letter-spacing: -0.01em;
  color: var(--exits-text);
  overflow-wrap: anywhere;
}

.exits-entity-card__code-sep {
  color: var(--exits-text-subtle);
  font-weight: 400;
}

.exits-entity-card__code {
  margin: 0;
  min-width: 0;
  font-size: var(--exits-text-sm);
  font-weight: 400;
  line-height: 1.3;
  color: var(--exits-text-muted);
  overflow-wrap: anywhere;
}

.exits-entity-card__subtitle {
  margin: 0;
  min-width: 0;
  font-size: var(--exits-text-sm);
  font-weight: 400;
  line-height: 1.3;
  color: var(--exits-text-muted);
  overflow-wrap: anywhere;
}

.exits-entity-card__badges {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.3rem;
  max-width: 46%;
}

.exits-entity-card__meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--exits-entity-card-meta-gap);
  margin: 0;
  min-width: 0;
}

.exits-entity-card__meta-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 0.35rem 0.5rem;
  min-width: 0;
}

.exits-entity-card__meta-item dt {
  margin: 0;
  min-width: 0;
  font-size: var(--exits-text-xs);
  font-weight: 400;
  color: var(--exits-text-muted);
  line-height: 1.25;
}

.exits-entity-card__meta-item dd {
  margin: 0;
  min-width: 0;
  font-size: var(--exits-text-sm);
  font-weight: 500;
  color: var(--exits-text);
  line-height: 1.25;
  text-align: right;
  overflow-wrap: anywhere;
}

.exits-entity-card__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--exits-toolbar-gap);
  min-width: 0;
}

@media (min-width: 640px) {
  .exits-entity-card__meta {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .exits-entity-card__meta-item {
    grid-template-columns: 1fr;
    gap: 0.1rem;
  }

  .exits-entity-card__meta-item dd {
    text-align: left;
  }

  .exits-entity-card__badges {
    max-width: none;
  }
}

@media (min-width: 1024px) {
  .exits-entity-card__title-row .exits-entity-card__code-sep {
    display: inline;
  }

  .exits-entity-card__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--exits-entity-card-meta-gap);
  }

  .exits-entity-card__meta-item {
    display: inline-flex;
    flex: 0 1 auto;
    align-items: baseline;
    gap: 0.35rem;
    grid-template-columns: none;
  }

  .exits-entity-card__meta-item dt {
    font-size: var(--exits-text-sm);
  }

  .exits-entity-card__meta-item dd {
    text-align: left;
  }

  .exits-entity-card__actions {
    justify-content: flex-end;
  }
}

@media (max-width: 639px) {
  .exits-entity-card__title-row .exits-entity-card__code-sep {
    display: none;
  }

  .exits-entity-card__title-row .exits-entity-card__code {
    flex: 1 1 100%;
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.sr-only:focus,
.sr-only:focus-visible {
  position: fixed;
  width: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  clip: auto;
  white-space: normal;
}

/* POS-REACT-IMPL-04 / UX REPAIR 01 sell-floor responsive layout */
.sell-cart-landscape {
  min-height: 0;
  overflow: hidden;
}

.sell-cart-panel {
  min-height: 0;
  height: 100%;
}

/* Detail-items cart Ã¢â‚¬â€ dense list, footer pinned */
.sell-cart-lines {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1 1 auto;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.sell-cart-footer {
  flex: 0 0 auto;
  z-index: 1;
  margin-top: auto;
  padding-top: 0.5rem;
  border-top: 1px solid var(--exits-border);
  background: var(--exits-surface);
}

.sell-cart-footer__total-row {
  min-width: 0;
}

.sell-cart-footer__total-label {
  color: var(--exits-text-muted);
}

.sell-cart-footer__total-amount {
  color: var(--exits-text);
}

.sell-cart-line {
  display: grid;
  grid-template-columns: 2.75rem minmax(0, 1fr);
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--exits-border);
}

.sell-cart-line:last-child {
  border-bottom: none;
}

.sell-cart-line__media {
  display: flex;
  width: 2.75rem;
  height: 2.75rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: var(--exits-radius-md);
  background: color-mix(in srgb, var(--exits-primary) 10%, var(--exits-surface-muted));
  border: 1px solid color-mix(in srgb, var(--exits-primary) 18%, var(--exits-border));
}

.sell-cart-line__image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sell-cart-line__initial {
  font-size: var(--exits-text-md);
  font-weight: 700;
  line-height: 1;
  color: var(--exits-primary);
}

.sell-cart-line__body {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.125rem;
}

.sell-cart-line__top {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.375rem;
}

.sell-cart-line__price-actions {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.125rem;
}

.sell-cart-line__name {
  margin: 0;
  min-width: 0;
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--exits-text-sm);
  font-weight: 600;
  line-height: 1.25;
}

.sell-cart-line__amount {
  font-size: var(--exits-text-sm) !important;
  font-weight: 600 !important;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.sell-cart-line__remove {
  min-height: 1.75rem !important;
  width: 1.75rem;
  padding: 0 !important;
  color: var(--exits-danger) !important;
}

.sell-cart-line__remove:hover {
  color: var(--exits-danger) !important;
  background: color-mix(in srgb, var(--exits-danger) 12%, transparent) !important;
}

.sell-cart-line__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.375rem;
}

.sell-cart-line__meta {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--exits-text-xs);
  color: var(--exits-text-muted, var(--muted-foreground));
}

.sell-cart-line__unit-price {
  font-variant-numeric: tabular-nums;
}

.sell-cart-line__qty {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.25rem;
}

.sell-cart-line__qty-input {
  min-height: 1.75rem;
  width: 2.75rem;
  border-radius: var(--exits-radius-sm, var(--exits-radius-md));
  border: 1px solid var(--exits-border);
  background: var(--exits-surface);
  padding: 0 0.25rem;
  text-align: center;
  font-size: 0.65rem;
  font-variant-numeric: tabular-nums;
}

.sell-cart-line__edit {
  min-height: 1.75rem !important;
  height: auto !important;
  padding: 0 0.375rem !important;
  font-size: 0.65rem !important;
}

.sell-cart-line__override,
.sell-cart-line__stock {
  margin: 0.125rem 0 0;
  font-size: 0.65rem;
  line-height: 1.2;
}

.sell-cart-line__override {
  color: var(--exits-primary);
  font-weight: 600;
}

.sell-cart-line__stock {
  color: var(--exits-danger);
}

.sell-cart-line__price-was {
  font-weight: 400;
  text-decoration: line-through;
  color: var(--exits-text-muted, var(--muted-foreground));
}

.sell-cart-line__price-now {
  color: var(--exits-primary) !important;
}

.sell-cart-footer__hint {
  line-height: 1.2;
}

.sell-cart-pay {
  min-height: 2.5rem;
  font-size: var(--exits-text-sm);
  font-weight: 700;
  transition:
    background-color var(--exits-motion-normal),
    border-color var(--exits-motion-normal),
    opacity var(--exits-motion-normal),
    transform var(--exits-motion-fast);
}

.sell-cart-pay--ready:not(:disabled) {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--exits-primary) 35%, transparent);
}

.sell-cart-floating {
  position: fixed;
  left: max(0.75rem, env(safe-area-inset-left));
  right: max(0.75rem, env(safe-area-inset-right));
  /* Sit above the org bottom nav. */
  bottom: max(0.75rem, calc(4.25rem + env(safe-area-inset-bottom)));
  z-index: 25;
  display: flex;
  min-height: 3.5rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  border-radius: 9999px;
  border: 1px solid var(--exits-border);
  background: var(--exits-surface);
  padding: 0.625rem 0.75rem 0.625rem 1rem;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.28);
  text-align: left;
}

.sell-cart-bar__summary {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 0.625rem;
}

.sell-cart-bar__icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  color: inherit;
}

.sell-cart-bar__copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.0625rem;
}

.sell-cart-bar__copy--amount-only {
  justify-content: center;
}

.sell-cart-bar__count {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--exits-text-xs);
  font-weight: 600;
  line-height: 1.2;
  color: inherit;
  opacity: 0.9;
}

.sell-cart-bar__total {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--exits-text-md);
  font-weight: 700;
  line-height: 1.15;
  color: inherit;
}

.sell-cart-bar__action {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  color: inherit;
}

.sell-cart-bar__action-label {
  font-size: var(--exits-text-sm);
  font-weight: 700;
  line-height: 1;
}

.sell-cart-bar--filled {
  /* Solid primary accent + primary-foreground for readable contrast in light and dark. */
  border-color: var(--exits-primary-hover);
  background: var(--exits-primary);
  color: var(--exits-primary-foreground);
  box-shadow:
    var(--exits-shadow-lg),
    0 2px 8px color-mix(in srgb, var(--exits-primary) 28%, transparent);
}

.sell-cart-bar--filled .sell-cart-bar__icon,
.sell-cart-bar--filled .sell-cart-bar__action,
.sell-cart-bar--filled .sell-cart-bar__action-label,
.sell-cart-bar--filled .sell-cart-bar__total {
  color: var(--exits-primary-foreground);
}

.sell-cart-bar--filled .sell-cart-bar__count {
  color: var(--exits-primary-foreground);
  opacity: 0.88;
  font-weight: 500;
}

.sell-cart-bar--filled .sell-cart-bar__total {
  opacity: 1;
  font-weight: 700;
}

.sell-cart-bar--filled:hover {
  filter: brightness(1.04);
}

.sell-cart-bar--filled:active {
  transform: scale(0.985);
}

@media (min-width: 900px) {
  .sell-floor-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(19rem, 21.5rem);
    gap: 0.875rem; /* ~14px between panes */
    align-items: stretch;
    min-height: 0;
    flex: 1 1 auto;
  }

  .sell-cart-landscape {
    display: flex !important;
    align-self: stretch;
    height: 100%;
    max-height: 100%;
    min-height: 0;
  }

  .sell-cart-bar,
  .sell-cart-floating,
  .sell-cart-sheet,
  .sell-cart-sheet-backdrop {
    display: none !important;
  }

  /* No floating-cart bottom pad when side cart is permanent */
  .sell-floor-browse {
    padding-bottom: 0 !important;
    min-height: 0;
    height: 100%;
    overflow: hidden;
  }

  .sell-product-grid {
    min-height: 0;
  }
}

@media (max-width: 899.98px) {
  .sell-cart-landscape {
    display: none !important;
  }

  .sell-product-grid {
    min-height: 12rem;
  }

  /* Bottom sheet cart: use most of the phone viewport; items scroll; footer sticks */
  .sell-cart-sheet {
    top: auto;
    right: 0;
    bottom: 0;
    left: 0;
    height: min(88dvh, calc(100dvh - env(safe-area-inset-top, 0px)));
    max-height: min(88dvh, calc(100dvh - env(safe-area-inset-top, 0px)));
    min-height: 0;
    overflow: hidden;
    border-radius: 1rem 1rem 0 0;
    border-width: 1px 0 0;
  }

  .sell-cart-sheet__handle {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    padding: 0.25rem 0 0.125rem;
  }

  .sell-cart-sheet__handle-bar {
    display: block;
    width: 2.5rem;
    height: 0.25rem;
    border-radius: 9999px;
    background: color-mix(in srgb, var(--exits-text-muted) 55%, transparent);
  }

  .sell-cart-sheet .sell-cart-panel {
    flex: 1 1 auto;
    min-height: 0;
    max-height: 100%;
    height: 100%;
    overflow: hidden;
  }

  .sell-cart-sheet .sell-cart-empty {
    flex: 1 1 auto;
    justify-content: center;
    padding-block: 1.25rem;
  }

  .sell-cart-sheet .sell-cart-lines {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
  }

  .sell-cart-sheet .sell-cart-footer {
    margin-top: 0;
    padding-top: 0.75rem;
    padding-bottom: 0.125rem;
    background: var(--exits-surface);
  }
}

/* Sell floor uses nearly full viewport; other pages keep max-w-5xl.
   Class is set from the router (AppShell sellFloor) â€” avoid CSS :has() which
   forces expensive ancestor style invalidation on every desktop DOM change. */
.app-shell--sell-floor {
  max-width: min(100%, 100rem); /* ~1600px ceiling for ultra-wide */
  padding-left: max(1rem, env(safe-area-inset-left));
  padding-right: max(1rem, env(safe-area-inset-right));
  height: 100dvh;
  max-height: 100dvh;
  overflow: hidden;
}

.app-shell--sell-floor #main-content {
  min-height: 0;
  overflow: hidden;
}

/*
 * Crystal screen frame — Preferences primary rim around whole shell.
 * UI Standards: `.app-shell--full` · Personal: `.personal-crystal-screen`
 * Command: ext ui-standards crystal screen-border
 */
html:has(.app-shell--full),
html:has(.personal-crystal-screen),
body:has(.app-shell--full),
body:has(.personal-crystal-screen) {
  height: 100%;
  max-height: 100dvh;
  overflow: hidden;
  background: var(--exits-bg);
}

#root:has(.app-shell--full),
#root:has(.personal-crystal-screen) {
  height: 100%;
  max-height: 100dvh;
  overflow: hidden;
}

.app-shell.app-shell--full,
.personal-crystal-screen {
  --ui-standards-crystal-inset: 0.45rem;
  /* Match Soft Glass shell radius. */
  --ui-standards-crystal-radius: 1.1rem;
  box-sizing: border-box;
  position: relative;
  z-index: 1;
  max-width: none;
  width: calc(100% - (2 * var(--ui-standards-crystal-inset)));
  min-height: 0;
  height: calc(100dvh - (2 * var(--ui-standards-crystal-inset)));
  max-height: calc(100dvh - (2 * var(--ui-standards-crystal-inset)));
  margin: var(--ui-standards-crystal-inset);
  overflow: hidden;
  border: var(--soft-glass-crystal-border);
  border-radius: var(--ui-standards-crystal-radius);
  box-shadow: var(--soft-glass-crystal-rim);
  background-clip: padding-box;
}

.app-shell.app-shell--full {
  /* Override AppShell utilities: page gutters, safe-area top, pb-[max(2rem)]. */
  padding-top: 0 !important;
  padding-bottom: max(0px, env(safe-area-inset-bottom)) !important;
  padding-left: max(0px, env(safe-area-inset-left)) !important;
  padding-right: max(0px, env(safe-area-inset-right)) !important;
}

.personal-crystal-screen {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--exits-bg);
}

.personal-crystal-screen > .personal-shell {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  max-width: none;
  /* Shell fills the crystal frame; inset/margin live on the frame. */
  height: 100% !important;
  max-height: none !important;
  margin: 0;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

/* Pin mobile bottom nav to the crystal frame, not the viewport gutter. */
.personal-crystal-screen > .personal-bottom-nav {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  z-index: 50;
  isolation: isolate;
  overflow: hidden;
  border-top: 0;
  border-bottom-left-radius: calc(var(--ui-standards-crystal-radius) - 1px);
  border-bottom-right-radius: calc(var(--ui-standards-crystal-radius) - 1px);
  background: var(--exits-shell-content-bg, #e8ecf2);
}

/* Soft Glass edge — top + bottom of Personal bottom nav (same as top bar). */
.personal-crystal-screen > .personal-bottom-nav::before,
.personal-crystal-screen > .personal-bottom-nav::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  z-index: 4;
  height: 1.1rem;
  pointer-events: none;
}

.personal-crystal-screen > .personal-bottom-nav::before {
  inset-block-start: 0;
  background: linear-gradient(
    to top,
    transparent 0%,
    color-mix(in srgb, #fff 35%, transparent) 42%,
    color-mix(in srgb, #fff 72%, transparent) 100%
  );
  border-block-start: 1px solid color-mix(in srgb, #fff 78%, #cbd5e1);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 85%, transparent),
    0 -8px 22px color-mix(in srgb, #64748b 10%, transparent);
}

.personal-crystal-screen > .personal-bottom-nav::after {
  inset-block-end: 0;
  border-radius: 0 0 calc(var(--ui-standards-crystal-radius) - 1px)
    calc(var(--ui-standards-crystal-radius) - 1px);
  background: linear-gradient(
    to bottom,
    transparent 0%,
    color-mix(in srgb, #fff 35%, transparent) 42%,
    color-mix(in srgb, #fff 72%, transparent) 100%
  );
  border-block-end: 1px solid color-mix(in srgb, #fff 78%, #cbd5e1);
  box-shadow:
    inset 0 -1px 0 color-mix(in srgb, #fff 85%, transparent),
    0 8px 22px color-mix(in srgb, #64748b 10%, transparent);
}

[data-theme="dark"] .personal-crystal-screen > .personal-bottom-nav {
  background: var(--exits-shell-content-bg, var(--exits-bg));
}

[data-theme="dark"] .personal-crystal-screen > .personal-bottom-nav::before {
  background: linear-gradient(
    to top,
    transparent 0%,
    color-mix(in srgb, #fff 6%, transparent) 42%,
    color-mix(in srgb, #fff 12%, transparent) 100%
  );
  border-block-start-color: color-mix(in srgb, #fff 16%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 10%, transparent),
    0 -8px 22px color-mix(in srgb, #000 28%, transparent);
}

[data-theme="dark"] .personal-crystal-screen > .personal-bottom-nav::after {
  background: linear-gradient(
    to bottom,
    transparent 0%,
    color-mix(in srgb, #fff 6%, transparent) 42%,
    color-mix(in srgb, #fff 12%, transparent) 100%
  );
  border-block-end-color: color-mix(in srgb, #fff 16%, transparent);
  box-shadow:
    inset 0 -1px 0 color-mix(in srgb, #fff 10%, transparent),
    0 8px 22px color-mix(in srgb, #000 28%, transparent);
}

.app-shell--full #main-content {
  min-height: 0;
  overflow: hidden;
}

.app-shell--full .app-top-bar {
  margin-inline: 0;
  margin-right: 0;
  border-top-left-radius: calc(var(--ui-standards-crystal-radius) - 1px);
  border-top-right-radius: calc(var(--ui-standards-crystal-radius) - 1px);
}

/* Personal top bar Soft Glass radius is owned by `.personal-shell .app-top-bar--personal`. */
.personal-crystal-screen .app-top-bar--personal {
  margin-inline: 0;
  margin-right: 0;
}

@media (min-width: 900px) {
  .app-shell--sell-floor {
    padding-left: max(1.25rem, env(safe-area-inset-left));
    padding-right: max(1.25rem, env(safe-area-inset-right));
  }
}

.sell-floor-root {
  /* Contained by sell-floor shell / AppShell; panes scroll inside */
  width: 100%;
  min-width: 0;
  flex: 1 1 auto;
  min-height: 0;
  max-height: 100%;
  overflow: hidden;
  box-sizing: border-box;
  /* Operational gutter — same semantic token family as application pages. */
  padding-inline-start: max(var(--exits-page-gutter-ops-inline), env(safe-area-inset-left));
  padding-inline-end: max(var(--exits-page-gutter-ops-inline), env(safe-area-inset-right));
  padding-block-start: 0.25rem;
}

/* Ops shell already applies ops gutter on content — avoid double padding. */
.operations-shell--sell-floor .sell-floor-root {
  padding-inline: 0;
  padding-block-start: 0;
}

/* AppShell already pads with application gutter; replace with tighter ops gutter. */
.app-shell--sell-floor .sell-floor-root {
  margin-inline-start: calc(-1 * max(var(--exits-page-gutter-inline), env(safe-area-inset-left)));
  margin-inline-end: calc(-1 * max(var(--exits-page-gutter-inline), env(safe-area-inset-right)));
  padding-inline-start: max(var(--exits-page-gutter-ops-inline), env(safe-area-inset-left));
  padding-inline-end: max(var(--exits-page-gutter-ops-inline), env(safe-area-inset-right));
  width: auto;
}

/* Sell toolbar — compact PageHeader + optional tips panel */
.sell-floor-toolbar {
