  background: color-mix(in srgb, var(--exits-warning, #d97706) 10%, var(--exits-surface));
}

.sell-readiness-strip--banner-ready {
  border-color: color-mix(in srgb, var(--exits-success) 35%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-success) 8%, var(--exits-surface));
}

.sell-readiness-strip--banner-muted {
