/* Narrow tablet / phone (<900): keep 2 columns max (drawer cart). */
@media (max-width: 899.98px) {
  .sell-product-grid,
  .sell-product-grid__skeleton {
    grid-template-columns: repeat(2, minmax(0, 1fr));
