  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
  padding-inline: 0.75rem;
  font: inherit;
  font-size: var(--exits-text-md);
  color: var(--exits-text);
}

.sell-weight-entry__input:focus,
.sell-weight-entry__input:focus-visible {
  outline: none;
  border-color: var(--exits-field-border-focus);
  box-shadow: 0 0 0 var(--exits-field-focus-ring-width) var(--exits-field-focus-ring);
}

.sell-weight-entry__units {
  display: inline-flex;
  flex: 0 0 auto;
  overflow: hidden;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
}

.sell-weight-entry__unit {
  min-width: 2.75rem;
  height: var(--exits-control-height);
  padding: 0 0.65rem;
  border: 0;
  border-inline-start: 1px solid var(--exits-border);
  background: transparent;
  color: var(--exits-text-muted);
  font: inherit;
  font-size: var(--exits-text-sm);
  font-weight: 600;
  cursor: pointer;
}

.sell-weight-entry__unit:first-child {
  border-inline-start: 0;
}

.sell-weight-entry__unit--active {
  background: color-mix(in srgb, var(--exits-primary) 12%, var(--exits-surface));
  color: var(--exits-text);
}

.sell-weight-entry__unit:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--exits-ring);
}

/* Fixed kg suffix — Soft Glass weight dialog (no g/kg switch). */
.sell-weight-entry__unit-fixed {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  min-width: 2.75rem;
  height: var(--exits-control-height);
  padding: 0 0.75rem;
  border: 1px solid var(--exits-border);
  border-radius: var(--soft-glass-field-radius, var(--exits-radius-soft, 0.6875rem));
  background: color-mix(in srgb, var(--exits-primary) 10%, var(--exits-surface));
  color: var(--exits-text);
  font: inherit;
  font-size: var(--exits-text-sm);
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: lowercase;
}

.sell-weight-entry__summary {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface-muted);
  font-size: var(--exits-text-sm);
}

.sell-weight-entry__summary-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  color: var(--exits-text-muted);
}

.sell-weight-entry__summary-row--total {
  margin-top: 0.15rem;
  padding-top: 0.4rem;
  border-top: 1px solid color-mix(in srgb, var(--exits-border) 80%, transparent);
  color: var(--exits-text);
  font-weight: 600;
}

/*
 * Dense product pane (3+ columns): stack media above copy so height fits content.
 * Must follow base .sell-product-card rules so these win the cascade.
 */
@media (min-width: 900px) {
  @container sell-browse (min-width: 28rem) {
    .sell-product-grid .sell-product-card {
      grid-template-columns: minmax(0, 1fr);
      gap: 0.375rem;
      height: auto;
      min-height: auto;
      align-self: start;
      overflow: visible;
    }

    .sell-product-grid .sell-product-card__media {
      grid-column: 1;
      grid-row: auto;
      width: 100%;
      height: auto;
      aspect-ratio: 4 / 3;
      max-height: 4.5rem;
    }

    .sell-product-grid .sell-product-card__body {
      grid-column: 1;
      grid-row: auto;
      gap: 0.2rem;
    }

    .sell-product-grid .sell-product-card__name {
      font-size: var(--exits-text-sm);
    }

    .sell-product-grid .sell-product-card__price-row {
      flex-direction: column;
      align-items: flex-start;
      gap: 0.0625rem;
    }

    .sell-product-grid .sell-product-card__hint {
      white-space: normal;
      line-height: 1.2;
    }

    .sell-product-grid .sell-product-card__stock {
      margin-top: 0.25rem;
      padding-top: 0.25rem;
      border-top: 1px solid color-mix(in srgb, var(--exits-border) 80%, transparent);
      white-space: normal;
    }
  }

  @container sell-browse (min-width: 38rem) {
    .sell-product-grid .sell-product-card__media {
      max-height: 4rem;
    }

    .sell-product-grid .sell-product-card__name {
      font-size: var(--exits-text-xs);
    }
  }

  @container sell-browse (min-width: 48rem) {
    .sell-product-grid .sell-product-card__media {
      max-height: 3.5rem;
    }
  }
}

/* Category filter — FilterChip + sell scroll track (Control Shape via FilterChip). */
.sell-category-chip {
  scroll-snap-align: start;
  white-space: nowrap;
}

.sell-category-chip__icon {
  width: 0.875rem;
  height: 0.875rem;
  flex-shrink: 0;
}

/*
 * POS Soft Glass sell floor (UI-only).
 * Theme accent from --exits-primary. No backdrop-filter / heavy blur.
 * Tokens map semantic POS surface language onto existing ExItS vars.
 */
.sell-floor-root--soft-glass {
  --pos-surface: var(--exits-surface);
  --pos-surface-elevated: var(--exits-surface-elevated, var(--exits-surface));
  --pos-border: var(--exits-border);
  --pos-text: var(--exits-text);
  --pos-text-muted: var(--exits-text-muted, var(--muted-foreground));
  --pos-accent: var(--exits-primary);
  --pos-accent-soft: color-mix(in srgb, var(--exits-primary) 12%, var(--exits-surface));
  --pos-success: var(--exits-success);
  --pos-danger: var(--exits-danger);
  --pos-glass-wash: color-mix(in srgb, var(--exits-primary) 7%, var(--exits-surface));
  --pos-glass-mid: color-mix(in srgb, var(--exits-primary) 11%, var(--exits-surface-muted));
  --pos-glass-border: color-mix(in srgb, #e2e8f0 62%, color-mix(in srgb, var(--exits-primary) 28%, #cbd5e1));
  --pos-glass-ink: var(--exits-text);
  --pos-glass-shadow: 0 1px 0 rgba(255, 255, 255, 0.72) inset,
    0 4px 12px color-mix(in srgb, var(--exits-primary) 8%, transparent);
  --pos-transition: 140ms ease;
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--exits-primary) 5%, var(--exits-surface)) 0%,
      var(--exits-surface) 42%,
      color-mix(in srgb, var(--exits-surface-muted) 55%, var(--exits-surface)) 100%
    );
}

[data-theme="dark"] .sell-floor-root--soft-glass {
  --pos-glass-wash: color-mix(in srgb, var(--exits-primary) 10%, #1e293b);
  --pos-glass-mid: color-mix(in srgb, var(--exits-primary) 14%, #1e293b);
  --pos-glass-border: color-mix(in srgb, var(--exits-primary) 16%, #475569);
  --pos-glass-ink: #e2e8f0;
  --pos-glass-shadow: 0 1px 0 color-mix(in srgb, #fff 8%, transparent) inset,
    0 4px 14px rgba(0, 0, 0, 0.28);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--exits-primary) 8%, #1e293b) 0%,
      #1e293b 48%,
      color-mix(in srgb, #0f172a 70%, #1e293b) 100%
    );
}

.sell-floor-root--soft-glass .sell-floor-toolbar--soft-glass {
  margin-bottom: 0.625rem;
  padding: 0.375rem 0.625rem;
  border-radius: var(--soft-glass-radius, 1.1rem);
  border: 1px solid var(--pos-glass-border);
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 42%, transparent) 0%,
    color-mix(in srgb, var(--pos-glass-wash) 52%, transparent) 48%,
    color-mix(in srgb, var(--pos-glass-mid) 46%, transparent) 100%
  );
  box-shadow: var(--pos-glass-shadow);
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-floor-toolbar--soft-glass {
  background: linear-gradient(
    180deg,
    color-mix(in srgb, #fff 7%, #1e293b) 0%,
    color-mix(in srgb, #fff 3%, #1e293b) 48%,
    color-mix(in srgb, #0f172a 55%, #1e293b) 100%
  );
}

.sell-floor-root--soft-glass .sell-floor-header.page-header--compact {
  min-height: 2.5rem;
}

.sell-floor-root--soft-glass .sell-floor-toolbar__tips {
  border-color: var(--pos-glass-border);
  background: color-mix(in srgb, var(--pos-accent) 6%, var(--exits-surface-muted));
  border-radius: var(--soft-glass-field-radius, 0.6875rem);
}

.sell-floor-root--soft-glass .sell-floor-workspace {
  border-radius: var(--soft-glass-radius, 1.1rem);
  border: 1px solid var(--pos-glass-border);
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 48%, transparent) 0%,
    color-mix(in srgb, var(--pos-glass-wash) 48%, transparent) 52%,
    color-mix(in srgb, var(--pos-glass-mid) 42%, transparent) 100%
  );
  box-shadow: var(--pos-glass-shadow);
  overflow: hidden;
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-floor-workspace {
  background: linear-gradient(
    180deg,
    color-mix(in srgb, #fff 7%, #1e293b) 0%,
    color-mix(in srgb, #fff 3%, #1e293b) 48%,
    color-mix(in srgb, #0f172a 55%, #1e293b) 100%
  );
}

.sell-floor-root--soft-glass .sell-floor-workspace__search {
  padding: 0.75rem 0.875rem 0.625rem;
  border-bottom: 1px solid color-mix(in srgb, var(--pos-glass-border) 85%, transparent);
  background: transparent;
}

.sell-floor-root--soft-glass .sell-floor-workspace__search .exits-search-field {
  border-radius: var(--soft-glass-field-radius, 0.6875rem) !important;
  border-color: var(--pos-glass-border);
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 52%, transparent) 0%,
    color-mix(in srgb, var(--pos-glass-wash) 48%, transparent) 100%
  );
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset;
  transition:
    border-color var(--pos-transition),
    box-shadow var(--pos-transition),
    background-color var(--pos-transition);
}

.sell-floor-root--soft-glass .sell-floor-workspace__search .exits-search-field:focus-within {
  border-color: color-mix(in srgb, var(--pos-accent) 42%, var(--pos-glass-border));
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.78) inset,
    0 0 0 2px color-mix(in srgb, var(--pos-accent) 28%, transparent);
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-floor-workspace__search .exits-search-field {
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 4%, #1e293b) 0%,
    color-mix(in srgb, var(--pos-accent) 8%, #1e293b) 100%
  );
  box-shadow: 0 1px 0 color-mix(in srgb, #fff 6%, transparent) inset;
}

.sell-floor-root--soft-glass .sell-floor-workspace__categories {
  padding: 0.55rem 0.875rem 0.65rem;
  border-bottom: 1px solid color-mix(in srgb, var(--pos-glass-border) 85%, transparent);
  background: transparent;
}

.sell-floor-root--soft-glass .sell-categories-track {
  gap: 0.5rem;
  scroll-snap-type: x proximity;
  padding-bottom: 0.125rem;
}

.sell-floor-root--soft-glass .sell-category-chip {
  min-height: 2.25rem;
  padding-inline: 0.85rem;
  border: 1px solid color-mix(in srgb, var(--pos-glass-border) 90%, transparent);
  background: color-mix(in srgb, var(--exits-surface) 72%, transparent);
  color: var(--pos-text-muted);
  transition:
    background-color var(--pos-transition),
    border-color var(--pos-transition),
    color var(--pos-transition);
}

.sell-floor-root--soft-glass .sell-category-chip:hover {
  border-color: color-mix(in srgb, var(--pos-accent) 28%, var(--pos-glass-border));
  color: var(--pos-glass-ink);
}

.sell-floor-root--soft-glass .sell-category-chip--active,
.sell-floor-root--soft-glass .sell-category-chip[data-selected="true"] {
  border-color: color-mix(in srgb, var(--pos-accent) 42%, var(--pos-glass-border));
  background: color-mix(in srgb, var(--pos-accent) 14%, var(--exits-surface));
  color: var(--pos-glass-ink);
  box-shadow: inset 3px 0 0 var(--pos-accent);
}

.sell-floor-root--soft-glass .sell-category-chip:focus-visible {
  outline: 2px solid var(--exits-ring, var(--pos-accent));
  outline-offset: 2px;
}

.sell-floor-root--soft-glass .sell-floor-product-pane {
  padding: 0.625rem;
  padding-bottom: 1.25rem;
  background: color-mix(in srgb, var(--exits-surface-muted) 35%, transparent);
}

.sell-floor-root--soft-glass .sell-product-card {
  border: 1px solid var(--pos-glass-border);
  border-radius: var(--soft-glass-radius, 1.1rem);
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 42%, transparent) 0%,
    color-mix(in srgb, var(--pos-glass-wash) 52%, transparent) 48%,
    color-mix(in srgb, var(--pos-glass-mid) 46%, transparent) 100%
  );
  box-shadow: var(--pos-glass-shadow);
  transition:
    background-color var(--pos-transition),
    border-color var(--pos-transition),
    box-shadow var(--pos-transition);
}

.sell-floor-root--soft-glass .sell-product-card:hover:not(:disabled):not(.sell-product-card--unavailable) {
  border-color: color-mix(in srgb, var(--pos-accent) 38%, var(--pos-glass-border));
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 36%, transparent) 0%,
    color-mix(in srgb, var(--pos-glass-wash) 58%, transparent) 48%,
    color-mix(in srgb, var(--pos-glass-mid) 52%, transparent) 100%
  );
  transform: none;
}

.sell-floor-root--soft-glass .sell-product-card:active:not(:disabled):not(.sell-product-card--unavailable) {
  transform: none;
}

.sell-floor-root--soft-glass .sell-product-card--added,
.sell-floor-root--soft-glass .sell-product-card--selected {
  border-color: color-mix(in srgb, var(--pos-accent) 48%, var(--pos-glass-border));
  background: color-mix(in srgb, var(--pos-accent) 12%, var(--exits-surface));
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.72) inset,
    inset 0 0 0 1px color-mix(in srgb, var(--pos-accent) 28%, transparent),
    0 4px 12px color-mix(in srgb, var(--pos-accent) 10%, transparent);
}

.sell-floor-root--soft-glass .sell-product-card--unavailable {
  opacity: 0.55;
}

.sell-floor-root--soft-glass .sell-product-card__media {
  border-radius: var(--soft-glass-field-radius, 0.6875rem);
  border: 1px solid color-mix(in srgb, var(--pos-accent) 18%, var(--pos-glass-border));
  background: linear-gradient(
    160deg,
    color-mix(in srgb, var(--pos-accent) 16%, var(--exits-surface-muted)),
    color-mix(in srgb, var(--pos-accent) 8%, var(--exits-surface))
  );
  overflow: hidden;
}

.sell-floor-root--soft-glass .sell-product-card__fallback {
  display: flex;
  position: relative;
  width: 100%;
  height: 100%;
  min-height: inherit;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 30% 22%, color-mix(in srgb, #fff 28%, transparent), transparent 55%),
    linear-gradient(
      160deg,
      color-mix(in srgb, #fff 18%, var(--pos-accent)),
      var(--pos-accent) 58%,
      color-mix(in srgb, var(--pos-accent) 72%, #0f172a)
    );
}

.sell-floor-root--soft-glass .sell-product-card__fallback-icon {
  position: absolute;
  width: 1.35rem;
  height: 1.35rem;
  opacity: 0.28;
  color: #fff;
}

.sell-floor-root--soft-glass .sell-product-card__initial {
  position: relative;
  z-index: 1;
  font-size: var(--exits-text-md);
  font-weight: 700;
  line-height: 1;
  color: #fff;
  text-shadow: 0 1px 1px color-mix(in srgb, #0f172a 28%, transparent);
}

.sell-floor-root--soft-glass .sell-product-card__name {
  color: var(--pos-glass-ink);
  font-weight: 600;
}

.sell-floor-root--soft-glass .sell-product-card__price {
  color: var(--pos-accent) !important;
  font-weight: 650 !important;
}

.sell-floor-root--soft-glass .sell-product-card__hint {
  color: color-mix(in srgb, var(--pos-accent) 72%, var(--pos-text-muted));
}

.sell-floor-root--soft-glass .sell-product-card__hint--muted {
  color: var(--pos-text-muted);
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-product-card {
  border-color: var(--pos-glass-border);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, #fff 7%, #1e293b) 0%,
    color-mix(in srgb, #fff 3%, #1e293b) 48%,
    color-mix(in srgb, #0f172a 55%, #1e293b) 100%
  );
  color: #e2e8f0;
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-product-card:hover:not(:disabled):not(.sell-product-card--unavailable) {
  border-color: color-mix(in srgb, var(--pos-accent) 22%, #64748b);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, #fff 8%, #1e293b) 0%,
    color-mix(in srgb, #fff 4%, #1e293b) 48%,
    color-mix(in srgb, #0f172a 50%, #1e293b) 100%
  );
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-product-card__fallback {
  background:
    radial-gradient(circle at 30% 24%, color-mix(in srgb, #fff 14%, transparent), transparent 55%),
    linear-gradient(
      155deg,
      color-mix(in srgb, var(--pos-accent) 42%, #334155),
      color-mix(in srgb, var(--pos-accent) 58%, #1e293b)
    );
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-product-card__name,
[data-theme="dark"] .sell-floor-root--soft-glass .sell-product-card__price {
  color: #e2e8f0 !important;
}

.sell-floor-root--soft-glass .sell-cart-shell {
  border-radius: var(--soft-glass-radius, 1.1rem);
  /* Single rim only — no inset highlight (reads as double edge on rounded corners). */
  border: 1px solid var(--pos-glass-border);
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 42%, transparent) 0%,
    color-mix(in srgb, var(--pos-glass-wash) 52%, transparent) 48%,
    color-mix(in srgb, var(--pos-glass-mid) 46%, transparent) 100%
  );
  box-shadow: 0 4px 12px color-mix(in srgb, var(--exits-primary) 8%, transparent);
  overflow: hidden;
  outline: none;
}

[data-theme="dark"] .sell-floor-root--soft-glass .sell-cart-shell {
  border-color: color-mix(in srgb, var(--exits-primary) 16%, #475569);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, #fff 7%, #1e293b) 0%,
    color-mix(in srgb, #fff 3%, #1e293b) 48%,
    color-mix(in srgb, #0f172a 55%, #1e293b) 100%
  );
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}

.sell-floor-root--soft-glass .sell-cart-panel--soft-glass {
  background: transparent;
  border: 0;
  box-shadow: none;
  outline: none;
}

.sell-floor-root--soft-glass .sell-cart-panel__header {
  border-bottom-color: color-mix(in srgb, var(--pos-glass-border) 88%, transparent);
  padding-bottom: 0.5rem;
  margin-bottom: 0.25rem;
}

.sell-floor-root--soft-glass .sell-cart-line {
  border-bottom-color: color-mix(in srgb, var(--pos-glass-border) 80%, transparent);
  padding: 0.625rem 0;
  gap: 0.625rem;
}

.sell-floor-root--soft-glass .sell-cart-line__media {
  border-radius: var(--soft-glass-field-radius, 0.6875rem);
  border-color: color-mix(in srgb, var(--pos-accent) 18%, var(--pos-glass-border));
  background: color-mix(in srgb, var(--pos-accent) 10%, var(--exits-surface-muted));
}

.sell-floor-root--soft-glass .sell-cart-line__name {
  font-weight: 600;
  color: var(--pos-glass-ink);
}

.sell-floor-root--soft-glass .sell-cart-line__amount {
  font-weight: 650;
}

.sell-floor-root--soft-glass .sell-cart-line__remove {
  color: var(--pos-text-muted);
  border-radius: var(--soft-glass-field-radius, 0.6875rem);
}

.sell-floor-root--soft-glass .sell-cart-line__remove:hover {
  color: var(--pos-danger);
  background: color-mix(in srgb, var(--pos-danger) 10%, transparent);
}

.sell-floor-root--soft-glass .sell-cart-empty {
  gap: 0.5rem;
  padding: 1.25rem 0.75rem;
}

.sell-floor-root--soft-glass .sell-cart-footer {
  margin-top: auto;
  padding: 0.75rem 0 0.125rem;
  border-top: 1px solid color-mix(in srgb, var(--pos-glass-border) 88%, transparent);
  background: color-mix(in srgb, var(--pos-accent) 5%, transparent);
  gap: 0.625rem;
}

.sell-floor-root--soft-glass .sell-cart-footer__total-row {
  padding: 0.35rem 0.15rem;
}

.sell-floor-root--soft-glass .sell-cart-footer__total-label {
  font-size: var(--exits-text-sm);
  font-weight: 650;
  color: var(--pos-text-muted);
  letter-spacing: 0.01em;
  text-transform: uppercase;
}

.sell-floor-root--soft-glass .sell-cart-footer__total-amount {
  font-size: var(--exits-text-lg, 1.125rem) !important;
  font-weight: 750 !important;
  color: var(--pos-glass-ink) !important;
}

.sell-floor-root--soft-glass .sell-cart-pay {
  min-height: 2.5rem;
  border-radius: var(--soft-glass-field-radius, 0.6875rem);
  font-weight: 700;
}

.sell-floor-root--soft-glass .sell-cart-pay--ready:not(:disabled) {
  background: var(--pos-accent);
  border-color: color-mix(in srgb, var(--pos-accent) 80%, #0f172a);
  color: #fff;
  box-shadow: 0 1px 0 color-mix(in srgb, #fff 22%, transparent) inset;
}

.sell-floor-root--soft-glass .sell-cart-pay--disabled:disabled,
.sell-floor-root--soft-glass .sell-cart-pay:disabled {
  opacity: 0.55;
  box-shadow: none;
}

.sell-floor-root--soft-glass .sell-cart-footer__hint {
  margin-top: 0.125rem;
  line-height: 1.35;
  color: var(--pos-text-muted);
}

