/* Sell-floor motion (respects prefers-reduced-motion via global rule) */
@keyframes sell-readiness-in {
  from {
    opacity: 0;
    transform: translateY(-0.35rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sell-info-panel-in {
  from {
    opacity: 0;
    transform: translateY(-0.25rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sell-product-grid-in {
  from {
    opacity: 0;
    transform: translateY(0.35rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sell-product-added {
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--exits-primary) 35%, transparent);
  }
  45% {
    transform: scale(0.98);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--exits-primary) 28%, transparent);
  }
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes sell-cart-line-in {
  from {
    opacity: 0;
    transform: translateX(0.5rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes sell-cart-bar-in {
  from {
    opacity: 0;
    transform: translateY(0.75rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.sell-readiness-strip {
  animation: sell-readiness-in var(--exits-motion-normal) var(--exits-ease-emphasized);
}

.sell-readiness-strip--warning {
  border-color: color-mix(in srgb, var(--exits-warning, #d97706) 35%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-warning, #d97706) 8%, var(--exits-surface-muted));
}

.sell-readiness-strip__close {
  display: inline-flex;
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: var(--exits-radius-md);
  color: var(--exits-text-muted, var(--muted-foreground));
}

.sell-readiness-strip__close:hover {
  background: color-mix(in srgb, var(--foreground) 10%, transparent);
  color: var(--foreground);
}

.sell-readiness-strip__close:focus-visible {
  outline: 2px solid var(--exits-ring, var(--exits-primary));
  outline-offset: 2px;
}

.sell-readiness-strip--muted {
  animation: none;
}

.sell-info-panel {
  animation: sell-info-panel-in var(--exits-motion-normal) var(--exits-ease-emphasized);
}

.sell-info-panel__bar {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
}

.sell-info-panel__close {
  margin: -0.25rem -0.25rem 0 0;
}

.sell-product-grid--enter {
  animation: sell-product-grid-in var(--exits-motion-normal) var(--exits-ease-emphasized);
}

.sell-categories-track {
  scroll-snap-type: x proximity;
}

.sell-cart-line--enter {
  animation: sell-cart-line-in var(--exits-motion-normal) var(--exits-ease-emphasized);
}

.sell-cart-empty__icon {
