  width: 3rem;
  height: 3rem;
  align-items: center;
  justify-content: center;
  border-radius: var(--exits-radius-full);
  background: var(--exits-surface-muted);
  color: var(--exits-primary);
}

.sell-cart-bar--filled,
.sell-cart-bar--empty {
  animation: sell-cart-bar-in var(--exits-motion-normal) var(--exits-ease-emphasized);
}

.sell-cart-bar--empty {
  border-style: solid;
