  background: color-mix(in srgb, var(--exits-warning) 10%, var(--exits-surface));
}

/* Not tracked = muted/neutral (inactive capability). */
.inventory-row__badge--untracked {
  border-color: color-mix(in srgb, var(--exits-text-muted) 35%, var(--exits-border));
  color: var(--exits-text-muted);
