  padding: 1rem;
  border: 1px solid color-mix(in srgb, #e2e8f0 62%, var(--personal-qa-chip-soft));
  border-radius: 1.1rem;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, #fff 88%, transparent) 0%,
      color-mix(in srgb, #fff 70%, transparent) 42%,
      color-mix(in srgb, var(--personal-qa-chip-mid) 52%, transparent) 100%
