  font-weight: var(--exits-font-weight-medium);
  color: var(--exits-text-muted);
  line-height: var(--exits-leading-normal);
}

.dashboard-metric-card__tag {
  display: inline-flex;
  flex-shrink: 0;
  margin-inline-start: auto;
  align-items: center;
  gap: 0.35rem;
}

.dashboard-metric-card__label:has(.exits-status-chip) {
