}

.dashboard-metric-card__icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: var(--exits-radius-md);
  background: color-mix(in srgb, var(--exits-primary) 12%, var(--exits-surface-muted));
  color: var(--exits-primary);
}

.dashboard-metric-card--attention .dashboard-metric-card__icon {
  background: color-mix(in srgb, var(--exits-warning) 16%, var(--exits-surface-muted));
  color: var(--exits-warning);
}

.dashboard-metric-card--success .dashboard-metric-card__icon {
  background: color-mix(in srgb, var(--exits-success) 14%, var(--exits-surface-muted));
  color: var(--exits-success);
}

.dashboard-metric-card--shared .dashboard-metric-card__icon {
  background: color-mix(in srgb, var(--exits-info) 16%, var(--exits-surface-muted));
  color: var(--exits-info);
}

.dashboard-metric-card--shared .dashboard-metric-card__label,
.dashboard-metric-card--shared .dashboard-metric-card__meta {
  color: var(--exits-info);
}

.dashboard-metric-card__icon svg {
  width: 0.95rem;
  height: 0.95rem;
}

.dashboard-metric-card__value {
  font-size: var(--exits-text-lg);
  font-weight: var(--exits-font-weight-semibold);
  color: var(--exits-text);
  line-height: var(--exits-leading-tight);
  letter-spacing: -0.01em;
}

.dashboard-metric-card__meta {
  font-size: var(--exits-text-xs);
  font-weight: var(--exits-font-weight-regular);
  color: var(--exits-text-muted);
  line-height: var(--exits-leading-relaxed);
}

.dashboard-trend {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  padding: 0.45rem 0.55rem;
  border-radius: var(--exits-radius-md);
  background: color-mix(in srgb, var(--exits-surface-muted) 70%, var(--exits-surface));
}

.dashboard-trend--up {
  background: color-mix(in srgb, var(--exits-success) 12%, var(--exits-surface));
  color: var(--exits-success);
}

.dashboard-trend--down {
  background: color-mix(in srgb, var(--exits-danger, var(--destructive)) 10%, var(--exits-surface));
  color: var(--exits-danger, var(--destructive));
}

.dashboard-trend--flat {
  color: var(--exits-text-muted);
}

.dashboard-trend__icon {
  display: inline-flex;
  margin-top: 0.1rem;
}

.dashboard-trend__icon svg {
  width: 1rem;
  height: 1rem;
}

.dashboard-trend__copy {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.55rem;
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-medium);
}

.dashboard-trend__pct--muted,
.dashboard-trend__vs {
  font-weight: 500;
  color: var(--exits-text-muted);
}

.dashboard-chart-panel {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  padding: 0.85rem 0.9rem;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
}

.dashboard-spark {
  display: flex;
  align-items: flex-end;
  gap: 0.35rem;
  min-height: 7rem;
  padding-top: 0.25rem;
}

.dashboard-spark__col {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  height: 100%;
}

.dashboard-spark__bar {
  display: block;
  width: 100%;
  max-width: 1.75rem;
  margin-top: auto;
  border-radius: 0.35rem 0.35rem 0.15rem 0.15rem;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--exits-primary) 85%, white) 0%,
    var(--exits-primary) 100%
  );
  transition: height var(--exits-motion-normal) cubic-bezier(0.22, 1, 0.36, 1);
}

.dashboard-spark__tick {
  font-size: 0.65rem;
  color: var(--exits-text-muted);
  line-height: 1;
}

.dashboard-share-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.dashboard-share-row {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  padding: 0.7rem 0.8rem;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
  animation: exits-list-card-in var(--exits-motion-normal) cubic-bezier(0.22, 1, 0.36, 1) both;
}

.dashboard-share-list > .dashboard-share-row:nth-child(1) {
  animation-delay: 40ms;
}
.dashboard-share-list > .dashboard-share-row:nth-child(2) {
  animation-delay: 70ms;
}
.dashboard-share-list > .dashboard-share-row:nth-child(3) {
  animation-delay: 100ms;
}

.dashboard-share-row__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.dashboard-share-row__label {
  display: block;
  font-size: var(--exits-text-sm);
}

.dashboard-share-row__meta {
  margin-top: 0.15rem;
  font-size: var(--exits-text-xs);
  color: var(--exits-text-muted);
}

.dashboard-share-row__amount {
  flex-shrink: 0;
  font-weight: 700;
}

.dashboard-share-row__track {
  height: 0.4rem;
  overflow: hidden;
  border-radius: 9999px;
  background: var(--exits-surface-muted);
}

.dashboard-share-row__fill {
  display: block;
  height: 100%;
  border-radius: 9999px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--exits-primary) 70%, white),
    var(--exits-primary)
  );
  transition: width var(--exits-motion-normal) ease;
}

@media (prefers-reduced-motion: reduce) {
  .dashboard-metric-card:hover {
    transform: none;
  }
}

.dashboard-period-header {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.2rem;
}

.dashboard-section {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dashboard-section__header {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.dashboard-section__header--inline {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 0.75rem;
}

.dashboard-section__lede {
  margin: 0;
  font-size: var(--exits-text-sm);
  color: var(--muted);
}

.dashboard-scope-badge {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 0.125rem 0.5rem;
  border: 1px solid var(--border);
  border-radius: var(--exits-radius-sm, 0.25rem);
  background: color-mix(in srgb, var(--foreground) 4%, transparent);
  font-size: var(--exits-text-xs);
  font-weight: 600;
  line-height: 1.35;
  color: var(--foreground);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dashboard-hero-metric__head {
  margin-bottom: 0.25rem;
}

@media (max-width: 480px) {
  .dashboard-section__header--inline {
    flex-direction: column;
    align-items: flex-start;
  }

  .dashboard-scope-badge {
    max-width: 100%;
    white-space: normal;
  }
}

.dashboard-breakdown {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin-top: 0.25rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--exits-border);
}

.dashboard-page .exits-list,
.dashboard-page .exits-list.exits-list {
  grid-template-columns: 1fr;
}

.dashboard-payment-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.dashboard-payment-row__amount {
  flex-shrink: 0;
  font-weight: 600;
}

/* Premium executive dashboard (Recharts + motion) */
.dashboard-exec {
  gap: 1rem;
}

.dashboard-hero-metric--flagship {
  padding: 1.15rem 1.25rem;
}

.dashboard-metric-grid--secondary {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

@media (min-width: 900px) {
  .dashboard-metric-grid--secondary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 1200px) {
  .dashboard-metric-grid--secondary {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}

.dashboard-exec__analytics,
.dashboard-exec__ops {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

@media (min-width: 768px) {
  .dashboard-exec__analytics,
  .dashboard-exec__ops {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.dashboard-chart-panel--wide {
  min-width: 0;
}

.dashboard-chart-panel--muted {
  background: color-mix(in srgb, var(--exits-surface-muted) 55%, var(--exits-surface));
}

.dashboard-chart-panel:hover {
  border-color: color-mix(in srgb, var(--exits-primary) 28%, var(--exits-border));
  box-shadow: 0 8px 22px color-mix(in srgb, var(--exits-text) 5%, transparent);
  transition:
    border-color var(--exits-motion-fast) ease,
    box-shadow var(--exits-motion-fast) ease;
}

.dashboard-rechart {
  width: 100%;
  min-height: 220px;
  height: 240px;
}

.dashboard-rechart--ranked {
  min-height: 160px;
}

.dashboard-payment-mix {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.85rem;
  align-items: center;
}

@media (min-width: 480px) {
  .dashboard-payment-mix {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  }
}

.dashboard-payment-mix__chart {
  position: relative;
  width: 100%;
  min-height: 200px;
  height: 210px;
}

.dashboard-payment-mix__center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  text-align: center;
  padding: 2.5rem;
}

.dashboard-payment-mix__center-label {
  font-size: var(--exits-text-xs);
  font-weight: var(--exits-font-weight-medium);
  color: var(--exits-text-muted);
  text-transform: none;
  letter-spacing: var(--exits-tracking-normal);
}

.dashboard-payment-mix__center-value {
  font-size: var(--exits-text-lg) !important;
  font-weight: var(--exits-font-weight-semibold) !important;
}

.dashboard-payment-mix__legend {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.dashboard-payment-mix__legend-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  gap: 0.45rem 0.55rem;
  align-items: center;
  padding: 0.45rem 0.55rem;
  border-radius: var(--exits-radius-md);
  border: 1px solid transparent;
  transition:
    background-color var(--exits-motion-fast) ease,
    border-color var(--exits-motion-fast) ease;
}

.dashboard-payment-mix__legend-row--active {
  background: color-mix(in srgb, var(--exits-primary) 8%, var(--exits-surface));
  border-color: color-mix(in srgb, var(--exits-primary) 28%, var(--exits-border));
}

.dashboard-payment-mix__swatch {
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 9999px;
}

.dashboard-payment-mix__legend-label {
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-medium);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-payment-mix__legend-amount {
  font-size: var(--exits-text-sm) !important;
}

.dashboard-payment-mix__legend-pct {
  font-size: var(--exits-text-xs);
  font-weight: var(--exits-font-weight-medium);
  color: var(--exits-text-muted);
  min-width: 2.25rem;
  text-align: right;
}

.dashboard-radial {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.65rem;
}

.dashboard-radial__chart {
  position: relative;
  width: min(100%, 220px);
  height: 180px;
}

.dashboard-radial__center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  text-align: center;
}

.dashboard-radial__pct {
  font-size: clamp(1.5rem, 4vw, 1.85rem);
  font-weight: var(--exits-font-weight-semibold);
  letter-spacing: -0.02em;
  line-height: var(--exits-leading-tight);
}

.dashboard-radial__pct-label {
  margin-top: 0.2rem;
  font-size: var(--exits-text-xs);
  font-weight: var(--exits-font-weight-medium);
  color: var(--exits-text-muted);
}

.dashboard-radial__meta {
  text-align: center;
}

.dashboard-radial__amounts {
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-medium);
}

.dashboard-chart-link {
  display: block;
  color: inherit;
  text-decoration: none;
  border-radius: var(--exits-radius-md);
}

.dashboard-chart-link:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--exits-primary) 55%, transparent);
  outline-offset: 2px;
}

.dashboard-utang-facts {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

@media (min-width: 480px) {
  .dashboard-utang-facts {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.dashboard-status-bars {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.dashboard-status-bars__row {
  min-width: 0;
}

.dashboard-status-bars__link {
  display: block;
  color: inherit;
  text-decoration: none;
  border-radius: var(--exits-radius-md);
}

.dashboard-status-bars__link:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--exits-primary) 55%, transparent);
  outline-offset: 2px;
}

.dashboard-status-bars__top {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.3rem;
}

.dashboard-status-bars__label {
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-medium);
}

.dashboard-status-bars__count {
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-semibold);
}

.dashboard-status-bars__track {
  height: 0.55rem;
  overflow: hidden;
  border-radius: 9999px;
  background: var(--exits-surface-muted);
}

.dashboard-status-bars__fill {
  display: block;
  height: 100%;
  border-radius: 9999px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--exits-primary) 70%, white),
    var(--exits-primary)
  );
  transform-origin: left center;
  animation: dashboard-bar-grow var(--exits-motion-normal, 400ms) cubic-bezier(0.22, 1, 0.36, 1) both;
  transition: width 500ms cubic-bezier(0.22, 1, 0.36, 1);
}

.dashboard-status-bars__fill--attention {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--exits-warning) 65%, white),
    var(--exits-warning)
  );
}

.dashboard-status-bars__fill--danger {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--exits-danger) 65%, white),
    var(--exits-danger)
  );
}

.dashboard-status-bars__fill--instant {
  animation: none;
  transition: none;
}

.dashboard-status-bars__row--attention .dashboard-status-bars__count {
  color: var(--exits-warning);
}

.dashboard-status-bars__row--danger .dashboard-status-bars__count {
  color: var(--exits-danger);
}

@keyframes dashboard-bar-grow {
  from {
    transform: scaleX(0.15);
    opacity: 0.55;
  }
  to {
    transform: scaleX(1);
    opacity: 1;
  }
}

.dashboard-rank-toggle {
  display: inline-flex;
  gap: 0.25rem;
  padding: 0.2rem;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-control-radius);
  background: var(--exits-surface-muted);
}

.dashboard-rank-toggle__btn {
  border: 0;
  background: transparent;
  color: var(--exits-text-muted);
  font-size: var(--exits-text-xs);
  font-weight: var(--exits-font-weight-medium);
  padding: 0.35rem 0.65rem;
  border-radius: var(--exits-control-radius);
  cursor: pointer;
}

.dashboard-rank-toggle__btn--active {
  background: color-mix(in srgb, var(--exits-primary-soft) 80%, var(--exits-surface));
  color: var(--exits-primary);
  font-weight: var(--exits-font-weight-semibold);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--exits-primary) 12%, transparent);
}

.dashboard-skeleton {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.dashboard-skeleton__hero,
.dashboard-skeleton__chart,
.dashboard-skeleton__panel {
  border-radius: var(--exits-radius-md);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--exits-surface-muted) 70%, var(--exits-surface)) 0%,
    color-mix(in srgb, var(--exits-surface-muted) 40%, var(--exits-surface)) 50%,
    color-mix(in srgb, var(--exits-surface-muted) 70%, var(--exits-surface)) 100%
  );
  background-size: 200% 100%;
  animation: dashboard-skeleton-shimmer 1.2s ease-in-out infinite;
}

.dashboard-skeleton__hero {
  height: 6.5rem;
}

.dashboard-skeleton__chart {
  height: 14rem;
}

.dashboard-skeleton__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

@media (min-width: 768px) {
  .dashboard-skeleton__grid {
    grid-template-columns: 1fr 1fr;
  }
}

.dashboard-skeleton__panel {
  height: 12rem;
}

@keyframes dashboard-skeleton-shimmer {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

@keyframes dashboard-refresh-spin {
  to {
    transform: rotate(360deg);
  }
}

.dashboard-refresh-spin {
  animation: dashboard-refresh-spin 0.8s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .dashboard-chart-panel:hover {
    box-shadow: none;
  }

  .dashboard-status-bars__fill {
    animation: none;
    transition: none;
  }

  .dashboard-skeleton__hero,
  .dashboard-skeleton__chart,
  .dashboard-skeleton__panel {
    animation: none;
  }

  .dashboard-refresh-spin {
    animation: none;
  }
}

/* ===== Dashboard V2 visual composition ===== */
.dashboard-page--v2 {
  gap: 0.85rem;
}

.dashboard-toolbar {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: 0.85rem 0.95rem;
  border: 1px solid color-mix(in srgb, var(--exits-border) 70%, transparent);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
  box-shadow: var(--exits-shadow-sm);
}

.dashboard-toolbar__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem 0.75rem;
}

.dashboard-toolbar__presets {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.2rem;
  height: var(--exits-control-height);
  min-height: var(--exits-control-height);
  box-sizing: border-box;
  padding: 0.2rem;
  border: 1px solid color-mix(in srgb, var(--exits-border) 80%, transparent);
  border-radius: var(--exits-control-radius);
  background: color-mix(in srgb, var(--exits-surface-muted) 70%, var(--exits-surface));
}

.dashboard-toolbar__preset {
  border: 0;
  background: transparent;
  color: var(--exits-text-muted);
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-medium);
  padding: 0.25rem 0.7rem;
  border-radius: var(--exits-control-radius);
  cursor: pointer;
  height: calc(var(--exits-control-height) - 0.4rem);
  min-height: calc(var(--exits-control-height) - 0.4rem);
}

.dashboard-toolbar__preset--active {
  background: color-mix(in srgb, var(--exits-primary-soft) 80%, var(--exits-surface));
  color: var(--exits-primary);
  font-weight: var(--exits-font-weight-semibold);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--exits-primary) 12%, transparent);
}

.dashboard-toolbar__scope {
  min-width: 0;
  flex: 1 1 10rem;
  max-width: 16rem;
}

.dashboard-toolbar__select,
.exits-select.dashboard-toolbar__select,
.catalog-form-select.dashboard-toolbar__select {
  width: 100%;
  box-sizing: border-box;
  height: var(--exits-control-height);
  min-height: var(--exits-control-height);
  max-height: var(--exits-control-height);
  padding-block: 0;
  padding-inline: var(--exits-control-padding-x) calc(var(--exits-control-padding-x) + 1.25rem);
  font-size: var(--exits-text-sm);
  font-weight: var(--exits-font-weight-medium);
  line-height: calc(var(--exits-control-height) - 2px);
}

.dashboard-toolbar__actions {
