/* Ephemeral toast (Today's Prices + shared) */
.exits-toast-region {
  position: fixed;
  z-index: 80;
  left: 0.75rem;
  right: 0.75rem;
  bottom: calc(0.75rem + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  pointer-events: none;
}

@media (min-width: 768px) {
  .exits-toast-region {
    left: auto;
    right: 1rem;
    bottom: 1rem;
    width: min(24rem, calc(100vw - 2rem));
  }
}

.exits-toast-region.exits-toast-region--top {
  top: 0.75rem;
  right: 0.75rem;
  bottom: auto;
  left: auto;
  width: min(24rem, calc(100vw - 1.5rem));
}

@media (min-width: 768px) {
  .exits-toast-region.exits-toast-region--top {
    top: 1rem;
    right: 1rem;
    bottom: auto;
    left: auto;
    width: min(24rem, calc(100vw - 2rem));
  }
}

.exits-toast-region.exits-toast-region--center {
  top: 50%;
  bottom: auto;
  left: 50%;
  right: auto;
  width: min(22rem, calc(100vw - 1.5rem));
  transform: translate(-50%, -50%);
  z-index: 90;
}

.exits-toast {
  pointer-events: auto;
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.75rem 0.65rem 0.75rem 1rem;
  border-radius: var(--exits-radius-md);
  border: 1px solid var(--exits-border);
  background: var(--exits-surface);
  color: var(--exits-text);
  box-shadow: 0 8px 24px color-mix(in srgb, #000 14%, transparent);
  font-size: var(--exits-text-sm);
  line-height: 1.4;
  animation: exits-toast-in var(--exits-motion-fast) ease both;
}

.exits-toast__body {
  min-width: 0;
  flex: 1 1 auto;
}

.exits-toast__close {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  margin: -0.15rem -0.1rem 0 0;
  padding: 0;
  border: 0;
  border-radius: var(--exits-radius-sm);
  background: transparent;
  color: var(--exits-text-muted, var(--exits-muted));
  cursor: pointer;
}

.exits-toast__close:hover {
  background: color-mix(in srgb, var(--exits-surface-muted) 80%, transparent);
  color: var(--exits-text);
}

.exits-toast__close:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--exits-ring);
}

.exits-toast--interactive {
  pointer-events: auto;
}

.exits-toast__title {
  font-weight: 600;
  padding-right: 0.15rem;
}

.exits-toast__description {
  margin-top: 0.25rem;
  color: var(--exits-muted, var(--muted-foreground));
  white-space: pre-line;
}

.exits-toast__action {
  display: inline-flex;
  margin-top: 0.5rem;
  font-weight: 600;
  color: var(--exits-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.exits-toast--info {
  border-color: color-mix(in srgb, var(--exits-info) 45%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-info) 12%, var(--exits-surface));
}

.exits-toast--success {
  border-color: color-mix(in srgb, var(--exits-success) 45%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-success) 12%, var(--exits-surface));
}

.exits-toast--error {
  border-color: color-mix(in srgb, var(--exits-danger) 45%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-danger) 12%, var(--exits-surface));
}

.exits-toast--warning {
  border-color: color-mix(in srgb, var(--exits-warning) 50%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-warning) 14%, var(--exits-surface));
}

@keyframes exits-toast-in {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Open shift */
.shift-open-page > header {
