/* Denomination count helper */
.denom-helper--empty {
  padding: 0.65rem 0.75rem;
  border: 1px dashed var(--exits-border);
  border-radius: var(--exits-radius-md);
  background: color-mix(in srgb, var(--exits-surface-muted) 40%, transparent);
}

.denom-helper__grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

@media (min-width: 640px) {
  .denom-helper__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .denom-helper__grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.denom-helper__tile {
  display: flex;
  min-width: 0;
  align-items: stretch;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--exits-border) 85%, var(--exits-border-strong, #9ca3af));
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
  box-shadow: var(--exits-shadow-sm);
  transition:
    border-color var(--exits-motion-fast) ease,
    background-color var(--exits-motion-fast) ease,
    box-shadow var(--exits-motion-fast) ease;
}

.denom-helper__tile:hover {
  border-color: var(--exits-border-strong);
}

.denom-helper__tile--active {
  border-color: color-mix(in srgb, var(--exits-primary) 50%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-primary) 9%, var(--exits-surface));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--exits-primary) 18%, transparent);
}

.denom-helper__tile--disabled {
  opacity: 0.6;
  box-shadow: none;
}

.denom-helper__tap {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  min-height: var(--exits-control-height);
  height: var(--exits-control-height);
  padding: 0 0.65rem;
  border: 0;
  background: transparent;
  color: var(--exits-text);
  text-align: left;
  cursor: pointer;
}

.denom-helper__tap:disabled {
  cursor: not-allowed;
}

.denom-helper__tap:focus-visible {
  outline: 2px solid var(--exits-focus);
  outline-offset: -2px;
}

.denom-helper__tap:not(:disabled):active {
  transform: scale(0.99);
}

.denom-helper__value {
  font-size: var(--exits-text-sm);
  font-weight: 600;
  line-height: 1.2;
}

.denom-helper__qty {
  font-size: var(--exits-text-xs);
  font-weight: 500;
  color: var(--exits-text-muted);
}

.denom-helper__qty--active {
  color: var(--exits-primary);
  font-weight: 600;
}

.denom-helper__dec {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  min-height: var(--exits-control-height);
  height: var(--exits-control-height);
  border: 0;
  border-left: 1px solid var(--exits-border);
  background: color-mix(in srgb, var(--exits-surface-muted) 75%, var(--exits-surface));
  color: var(--exits-text-muted);
  cursor: pointer;
  transition:
    background-color var(--exits-motion-fast) ease,
    color var(--exits-motion-fast) ease;
}

.denom-helper__tile--active .denom-helper__dec {
  border-left-color: color-mix(in srgb, var(--exits-danger) 28%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-danger) 10%, var(--exits-surface));
  color: var(--exits-danger);
}

.denom-helper__dec:hover:not(:disabled) {
  background: color-mix(in srgb, var(--exits-danger) 16%, var(--exits-surface));
  color: var(--exits-danger);
}

.denom-helper__tile--active .denom-helper__dec:hover:not(:disabled) {
  background: color-mix(in srgb, var(--exits-danger) 20%, var(--exits-surface));
}

.denom-helper__dec:active:not(:disabled) {
  transform: scale(0.97);
}

.denom-helper__dec:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  color: var(--exits-text-muted);
  background: color-mix(in srgb, var(--exits-surface-muted) 50%, var(--exits-surface));
}

.denom-helper__dec:focus-visible {
  outline: 2px solid var(--exits-focus);
  outline-offset: -2px;
}

.denom-helper__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem 0.75rem;
  margin-top: 0.15rem;
  padding: 0.55rem 0.65rem;
