/*
 * Canonical ExItS Page Header surface — compact, subtle, structural radius.
 * Does not follow Control Shape (Pill) or Primary surface tint.
 */
.page-header {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--exits-text);
}

.exits-page > .page-header {
  /* Prefer flex gap on the page; keep header compact against following sections. */
