}

/* Operational POS header — same family, denser single row (~44–56px). */
.page-header--compact {
  padding-block: 0.35rem;
  padding-inline: 0.5rem;
  gap: 0;
}

.page-header--compact .page-header__head,
.page-header__head--compact {
