  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  padding: 0;
  border: 1px solid var(--exits-border);
  border-radius: 9999px;
  background: var(--exits-surface);
  color: var(--exits-text-muted);
  cursor: pointer;
  transition:
    background-color var(--exits-motion-fast) ease,
    border-color var(--exits-motion-fast) ease,
    color var(--exits-motion-fast) ease,
    box-shadow var(--exits-motion-fast) ease,
    transform var(--exits-motion-fast) cubic-bezier(0.22, 1, 0.36, 1);
}

.page-header__info:hover,
.page-header__info--visible {
  border-color: color-mix(in srgb, var(--exits-primary) 35%, var(--exits-border));
  background: var(--exits-surface-muted);
  color: var(--exits-text);
}

.page-header__info:hover {
  transform: translateY(-1px);
}

.page-header__info:active {
  transform: translateY(0) scale(0.97);
}

.page-header__info:focus-visible {
  outline: 2px solid var(--exits-focus);
  outline-offset: 2px;
}

.page-header__info--pinned {
  border-color: color-mix(in srgb, var(--exits-primary) 45%, var(--exits-border));
  background: color-mix(in srgb, var(--exits-primary) 12%, var(--exits-surface));
  color: var(--exits-primary);
}

.page-header__description-shell {
