.page-header__description-shell--open {
  grid-template-rows: 1fr;
  opacity: 1;
}

.page-header__description-clip {
  overflow: hidden;
  min-height: 0;
}

.page-header__description-shell--open .page-header__description {
  animation: exits-panel-in var(--exits-motion-normal) cubic-bezier(0.22, 1, 0.36, 1) both;
}

.page-header__subtitle {
  margin-top: -0.15rem;
}

.page-header__head {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.375rem;
}

.page-header__title-row {
  min-width: 0;
}

.page-header__trailing {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}

@media (min-width: 768px) {
  .page-header__head {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
  }

  .page-header__title-row {
    flex: 1 1 auto;
  }

  .page-header__trailing {
    flex: 0 0 auto;
    justify-content: flex-end;
  }
}

.catalog-product-form__header-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.375rem;
}

.catalog-form-page .page-header__subtitle {
  font-size: var(--exits-text-md);
  font-weight: 600;
  color: var(--exits-text);
}

/* Org / personal shell top bar */
.app-top-bar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.5rem;
  margin-inline: calc(-1 * max(var(--exits-page-padding), env(safe-area-inset-left)));
  margin-right: calc(-1 * max(var(--exits-page-padding), env(safe-area-inset-right)));
  padding: 0.5rem max(var(--exits-page-padding), env(safe-area-inset-left)) 0.55rem
    max(var(--exits-page-padding), env(safe-area-inset-right));
  border-bottom: 1px solid var(--exits-shell-divider, var(--exits-border));
  background: var(--exits-shell-topbar-bg, var(--exits-surface));
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  /* Shell chrome stays static — no entrance animation cost. */
  animation: none;
}

.app-top-bar__row {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.65rem;
}

@media (min-width: 768px) {
  .app-top-bar__row {
    grid-template-columns: minmax(0, 1fr) auto;
  }
}

@media (min-width: 1024px) {
  .app-top-bar__row {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr) auto;
  }

  .app-top-bar__row--shell-desktop {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .app-top-bar--shell-desktop {
    /* Content-column topbar: no bleed past sidebar edge. */
    margin-inline-start: 0;
    box-sizing: border-box;
    height: var(--exits-shell-chrome-height);
    min-height: var(--exits-shell-chrome-height);
    max-height: var(--exits-shell-chrome-height);
    padding-block: 0;
    justify-content: center;
  }

  .app-top-bar--shell-desktop .app-top-bar__row {
    height: 100%;
    min-height: 0;
  }

  /*
   * Personal shell: sidenav brand strip and top bar share one chrome height.
   * Top bar spans the content column; page body hosts the floating content panel.
   */
  .personal-shell .app-top-bar--personal {
    box-sizing: border-box;
    width: 100%;
    height: var(--exits-shell-chrome-height);
    min-height: var(--exits-shell-chrome-height);
    max-height: var(--exits-shell-chrome-height);
    margin-inline: 0;
    padding-block: 0;
    padding-inline: 0.35rem;
    justify-content: center;
    gap: 0;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__row--personal {
    display: flex;
    width: 100%;
    height: 100%;
    min-height: 0;
    min-width: 0;
    align-items: center;
    gap: 0.65rem;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__brand--personal {
    flex: 1 1 auto;
    min-width: 0;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__actions--personal {
    flex: 0 0 auto;
    margin-inline-start: auto;
    gap: 0.15rem;
  }

  /* Compact, consistent hit targets that fit the shared chrome height. */
  .personal-shell .app-top-bar--personal .app-top-bar__action,
  .personal-shell .app-top-bar--personal .app-top-bar__avatar,
  .personal-shell .app-top-bar--personal .shell-connection-trigger,
  .personal-shell .app-top-bar--personal [data-testid="personal-theme-mode"],
  .personal-shell .app-top-bar--personal [data-testid="personal-notification-bell"],
  .personal-shell .app-top-bar--personal [data-testid="shell-preferences-button"],
  .personal-shell .app-top-bar--personal [data-testid="shell-sidebar-mode-button"] {
    box-sizing: border-box;
    width: 2.5rem;
    height: 2.5rem;
    min-width: 2.5rem;
    min-height: 2.5rem;
    padding: 0;
    border-radius: var(--exits-radius-md) !important;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__action,
  .personal-shell .app-top-bar--personal .shell-connection-trigger,
  .personal-shell .app-top-bar--personal [data-testid="personal-theme-mode"],
  .personal-shell .app-top-bar--personal [data-testid="personal-notification-bell"],
  .personal-shell .app-top-bar--personal [data-testid="shell-preferences-button"] {
    color: #657792;
    background: transparent;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__action:hover,
  .personal-shell .app-top-bar--personal .shell-connection-trigger:hover,
  .personal-shell .app-top-bar--personal [data-testid="personal-theme-mode"]:hover,
  .personal-shell .app-top-bar--personal [data-testid="personal-notification-bell"]:hover,
  .personal-shell .app-top-bar--personal [data-testid="shell-preferences-button"]:hover {
    color: #4b5d78;
    background: color-mix(in srgb, #ffffff 62%, transparent);
  }

  .personal-shell .app-top-bar--personal [data-testid="shell-sidebar-mode-button"][data-intent="standard"],
  .personal-shell .app-top-bar--personal [data-testid="shell-sidebar-mode-button"][data-intent="standard"]:hover {
    color: color-mix(in srgb, #0f172a 72%, #64748b) !important;
    background:
      linear-gradient(
        160deg,
        color-mix(in srgb, #fff 78%, transparent),
        color-mix(in srgb, #fff 42%, transparent)
      ) !important;
    border: 1px solid color-mix(in srgb, #fff 72%, #94a3b8) !important;
    border-radius: 999px !important;
    box-shadow:
      0 1px 0 color-mix(in srgb, #fff 80%, transparent) inset,
      0 4px 12px color-mix(in srgb, #64748b 10%, transparent) !important;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__action svg,
  .personal-shell .app-top-bar--personal .shell-connection-trigger svg,
  .personal-shell .app-top-bar--personal [data-testid="personal-theme-mode"] svg,
  .personal-shell .app-top-bar--personal [data-testid="personal-notification-bell"] svg,
  .personal-shell .app-top-bar--personal [data-testid="shell-preferences-button"] svg,
  .personal-shell .app-top-bar--personal [data-testid="shell-sidebar-mode-button"] svg {
    width: 1.25rem;
    height: 1.25rem;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__workspace-org,
  .personal-shell .app-top-bar--personal .app-top-bar__workspace-branch {
    line-height: 1.2;
  }

  .personal-shell .app-top-bar--personal .app-top-bar__workspace-branch {
    font-size: var(--exits-text-xs);
  }

  .personal-shell .personal-sidebar .admin-sidebar__brand {
    position: relative;
    z-index: 2;
    height: 4.25rem;
    min-height: 4.25rem;
    max-height: 4.25rem;
    border-bottom: 0;
    background: transparent;
    box-shadow: none;
  }

  /* Personal keeps its brand label in the top bar (not hidden like org shell-desktop). */
  .personal-shell .app-top-bar.app-top-bar--shell-desktop .app-top-bar__brand {
    display: flex !important;
    flex-direction: row;
    align-items: center;
  }

  /*
   * Desktop shell branding lives in the sidebar only.
   * !important beats the unlayered .app-top-bar__brand { display: flex }, which
   * otherwise overrides Tailwind lg:hidden and leaves a stacked duplicate logo.
   */
  .app-top-bar.app-top-bar--shell-desktop .app-top-bar__brand,
  .app-top-bar.app-top-bar--shell-desktop .app-top-bar__brand--shell-mobile {
    display: none !important;
  }
}

/* Match Tailwind lg (64rem), not only 1024px, so zoomed roots still hide the duplicate. */
@media (min-width: 64rem) {
  .personal-shell .app-top-bar.app-top-bar--shell-desktop .app-top-bar__brand {
    display: flex !important;
  }

  .app-top-bar.app-top-bar--shell-desktop .app-top-bar__brand,
  .app-top-bar.app-top-bar--shell-desktop .app-top-bar__brand--shell-mobile {
    display: none !important;
  }

  .app-top-bar--shell-desktop:not(.app-top-bar--personal) {
    box-sizing: border-box;
    height: var(--exits-shell-chrome-height);
    min-height: var(--exits-shell-chrome-height);
    max-height: var(--exits-shell-chrome-height);
    padding-block: 0;
    justify-content: center;
    overflow: hidden;
  }

  .app-top-bar--shell-desktop:not(.app-top-bar--personal) .app-top-bar__row,
  .app-top-bar__row--shell-desktop {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: center;
    height: 100%;
    min-height: 0;
  }
}

.app-top-bar__leading {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  min-width: 0;
}

/*
 * UI Standards full-screen shell: sidenav toggle | title | actions.
 * Without this row, the leading toggle competes with brand/center in the
 * default 2/3-column grid and the topbar wraps or misaligns.
 */
.app-top-bar__row--ui-standards {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.5rem 0.75rem;
}

/*
 * UI Standards topbar — Soft Glass chrome (same recipe as Personal top bar).
 * Scoped to .app-top-bar--ui-standards only (does not restyle Personal / Org product topbars).
 * Data bindings unchanged: ExItS UI Standard title, sidenav toggle, connection / prefs / account.
 */
.app-top-bar--ui-standards {
  box-sizing: border-box;
  position: relative;
  isolation: isolate;
  z-index: 30;
  min-height: var(--exits-shell-chrome-height, 3.25rem);
  /* Blend into page content — Soft Glass lips carry the edge. */
  border-bottom: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-top-left-radius: calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px);
  border-top-right-radius: calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px);
  overflow: hidden;
}

/* Soft Glass edge — top + bottom of UI Standards top bar (same as Personal). */
.app-top-bar--ui-standards::before,
.app-top-bar--ui-standards::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  z-index: 4;
  height: 1.1rem;
  pointer-events: none;
}

.app-top-bar--ui-standards::before {
  inset-block-start: 0;
  border-radius: calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px)
    calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px) 0 0;
  background: linear-gradient(
    to top,
    transparent 0%,
    color-mix(in srgb, #fff 35%, transparent) 42%,
    color-mix(in srgb, #fff 72%, transparent) 100%
  );
  border-block-start: 1px solid color-mix(in srgb, #fff 78%, #cbd5e1);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 85%, transparent),
    0 -8px 22px color-mix(in srgb, #64748b 10%, transparent);
}

.app-top-bar--ui-standards::after {
  inset-block-end: 0;
  border-radius: 0 0 calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px)
    calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px);
  background: linear-gradient(
    to bottom,
    transparent 0%,
    color-mix(in srgb, #fff 35%, transparent) 42%,
    color-mix(in srgb, #fff 72%, transparent) 100%
  );
  border-block-end: 1px solid color-mix(in srgb, #fff 78%, #cbd5e1);
  box-shadow:
    inset 0 -1px 0 color-mix(in srgb, #fff 85%, transparent),
    0 8px 22px color-mix(in srgb, #64748b 10%, transparent);
}

[data-theme="dark"] .app-top-bar--ui-standards::before {
  background: linear-gradient(
    to top,
    transparent 0%,
    color-mix(in srgb, #fff 6%, transparent) 42%,
    color-mix(in srgb, #fff 12%, transparent) 100%
  );
  border-block-start-color: color-mix(in srgb, #fff 16%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 10%, transparent),
    0 -8px 22px color-mix(in srgb, #000 28%, transparent);
}

[data-theme="dark"] .app-top-bar--ui-standards::after {
  background: linear-gradient(
    to bottom,
    transparent 0%,
    color-mix(in srgb, #fff 6%, transparent) 42%,
    color-mix(in srgb, #fff 12%, transparent) 100%
  );
  border-block-end-color: color-mix(in srgb, #fff 16%, transparent);
  box-shadow:
    inset 0 -1px 0 color-mix(in srgb, #fff 10%, transparent),
    0 8px 22px color-mix(in srgb, #000 28%, transparent);
}

.app-top-bar__brand--ui-standards {
  min-width: 0;
}

.app-top-bar__brand--ui-standards .app-top-bar__app-name {
