.quantity-stepper--cart .quantity-stepper__btn,
.quantity-stepper--cart .quantity-stepper__btn--minus,
.quantity-stepper--cart .quantity-stepper__btn--plus {
  background: transparent;
  color: var(--exits-primary-foreground);
  font-size: 1.05rem;
