}

.quantity-stepper--cart .quantity-stepper__btn--minus:hover:not(:disabled),
.quantity-stepper--cart .quantity-stepper__btn--minus:focus-visible:not(:disabled),
.quantity-stepper--cart .quantity-stepper__btn--plus:hover:not(:disabled),
