}

.quantity-stepper--cart .quantity-stepper__value {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* Compact form defaults use 12ch; cart/auto capsule must keep narrow ch or + clips. */
.quantity-stepper--cart.quantity-stepper--compact .quantity-stepper__input,
.quantity-stepper--cart.quantity-stepper--compact .quantity-stepper__value,
.quantity-stepper--cart .quantity-stepper__input--compact {
  --quantity-stepper-input-min-ch: 7ch;
  --quantity-stepper-input-max-ch: 12ch;
}

.quantity-stepper--cart.quantity-stepper--invalid .quantity-stepper__group {
  border-color: var(--exits-danger);
}

.quantity-stepper--cart .quantity-stepper__value--button {
  color: var(--exits-primary-foreground);
}

.quantity-stepper__group {
  box-sizing: border-box;
  display: inline-flex;
  align-items: stretch;
  min-width: 0;
  height: var(--quantity-stepper-height);
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-field-radius, var(--exits-radius-md));
  background: var(--exits-surface);
  overflow: hidden;
}

.quantity-stepper__middle {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  height: 100%;
  width: var(--quantity-stepper-input-width, auto);
  min-width: var(--quantity-stepper-input-width, var(--quantity-stepper-input-min-ch, 12ch));
  max-width: 100%;
}

.quantity-stepper__middle .quantity-stepper__input,
.quantity-stepper__middle .quantity-stepper__value {
  width: var(--quantity-stepper-input-width, auto);
  min-width: 0;
  max-width: none;
  flex: 0 0 auto;
}

.quantity-stepper__group:focus-within {
  border-color: var(--exits-field-border-focus);
  box-shadow: 0 0 0 var(--exits-field-focus-ring-width) var(--exits-field-focus-ring);
}

.quantity-stepper--invalid .quantity-stepper__group {
  border-color: var(--exits-field-border-error);
}

.quantity-stepper--invalid .quantity-stepper__group:focus-within {
  border-color: var(--exits-field-border-error);
  box-shadow: 0 0 0 var(--exits-field-focus-ring-width) var(--exits-field-focus-ring-error);
}

.quantity-stepper--disabled .quantity-stepper__group {
