}

.quantity-stepper__btn.exits-btn,
.quantity-stepper__btn {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--quantity-stepper-btn-size);
  min-width: var(--quantity-stepper-btn-size);
  height: auto;
  min-height: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--exits-text);
  font: inherit;
  font-size: var(--exits-text-md);
  font-weight: 600;
  line-height: 1;
  cursor: pointer;
  appearance: none;
  box-shadow: none;
  transform: none;
  transition:
    background-color var(--exits-motion-fast) var(--exits-ease-standard),
    color var(--exits-motion-fast) var(--exits-ease-standard),
    opacity var(--exits-motion-fast) var(--exits-ease-standard);
}

.quantity-stepper__btn:focus,
.quantity-stepper__btn:focus-visible,
.quantity-stepper__input:focus,
.quantity-stepper__input:focus-visible {
  outline: none !important;
  box-shadow: none !important;
}

/* Neutral minus — never danger (decrease is not a destructive action) */
.quantity-stepper__btn--minus {
  background: var(--exits-surface-muted);
  color: var(--exits-text);
}

.quantity-stepper__btn--minus:hover:not(:disabled),
.quantity-stepper__btn--minus:focus-visible:not(:disabled) {
  background: color-mix(in srgb, var(--exits-text) 8%, var(--exits-surface-muted));
  color: var(--exits-text);
}

/* Primary plus — follows global Primary Palette */
.quantity-stepper__btn--plus {
  background: var(--exits-primary);
  color: var(--exits-primary-foreground);
}

.quantity-stepper__btn--plus:hover:not(:disabled),
.quantity-stepper__btn--plus:focus-visible:not(:disabled) {
  background: var(--exits-primary-hover);
  color: var(--exits-primary-foreground);
}

/* Normal disabled styling (not danger-tinted) */
.quantity-stepper__btn:disabled {
  cursor: not-allowed;
  pointer-events: none;
  opacity: 0.5;
  filter: none;
}

.quantity-stepper__btn--minus:disabled {
  background: var(--exits-surface-muted);
  color: var(--exits-muted, var(--exits-text));
}

.quantity-stepper__btn--plus:disabled {
  background: var(--exits-primary);
  color: var(--exits-primary-foreground);
}

.quantity-stepper__input,
.quantity-stepper__value {
  --quantity-stepper-input-min-ch: 12ch;
  --quantity-stepper-input-max-ch: 20ch;
  box-sizing: border-box;
  flex: 0 1 auto;
  min-width: var(--quantity-stepper-input-min-ch);
  max-width: var(--quantity-stepper-input-max-ch);
  width: var(--quantity-stepper-input-width, var(--quantity-stepper-input-min-ch));
  height: auto;
  margin: 0;
  border: 0;
  border-inline: 1px solid var(--exits-border);
  border-radius: 0;
  background: transparent;
  padding: 0;
  overflow: hidden;
  text-overflow: clip;
  text-align: center;
  font: inherit;
  font-size: var(--exits-text-sm);
  font-weight: 600;
  color: var(--exits-text);
  appearance: none;
  box-shadow: none;
}

/* Native <input> text is not flex-centered — match control height line box. */
.quantity-stepper__input {
  display: block;
  padding-block: 0;
  line-height: calc(var(--quantity-stepper-height) - 2px);
  vertical-align: middle;
}

.quantity-stepper__value {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.quantity-stepper__value--button {
