  color: inherit;
}

.quantity-stepper__value--button:hover:not(:disabled),
.quantity-stepper__value--button:focus-visible:not(:disabled) {
  background: color-mix(in srgb, #fff 14%, transparent);
}

.quantity-stepper__value--button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.quantity-stepper__input:focus,
.quantity-stepper__input:focus-visible {
  outline: none;
  border-color: var(--exits-border);
  box-shadow: none;
}

.quantity-stepper__input[aria-invalid="true"] {
  border-color: var(--exits-border);
  box-shadow: none;
}

.quantity-stepper__input--compact,
.quantity-stepper--compact .quantity-stepper__value {
