.exits-input[aria-invalid="true"]:focus,
.exits-input[aria-invalid="true"]:focus-visible,
.exits-input.border-destructive:focus,
.exits-input.border-destructive:focus-visible {
  outline: none;
  border-color: var(--exits-field-border-error);
