/* ---- ExItS Currency Field (one shell; inline ₱ prefix; Form Field Focus) ---- */
.exits-currency-field {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  width: 100%;
  min-width: 0;
  min-height: var(--exits-control-height);
  border: 1px solid var(--exits-field-border, var(--exits-border));
  border-radius: var(--exits-field-radius, var(--exits-radius-md));
