/* Global chip bar â€” density tokens (default = balance) drive size app-wide */
.exits-chip-bar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--exits-chip-gap);
  min-width: 0;
}

.exits-chip-bar--equal {
