}

/*
 * Visually hidden file input. Native file controls have a large intrinsic
 * width; inside a transformed Soft Glass modal that used to force horizontal
 * scroll when Upload QR opened the picker.
 */
.qr-file-input {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
  opacity: 0;
  pointer-events: none;
}

.qr-manual-entry__field {
  position: relative;
  display: flex;
  min-width: 0;
  align-items: center;
}

.qr-manual-entry__input {
