  top: 50%;
  right: 0.35rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  padding: 0;
  border: 0;
  border-radius: var(--exits-radius-md);
  background: transparent;
  color: var(--exits-text-muted, var(--exits-muted, #6b7280));
  transform: translateY(-50%);
  cursor: pointer;
}

.qr-manual-entry__clear:hover:not(:disabled) {
  color: var(--exits-text, inherit);
