    padding-bottom: 0.125rem;
    -webkit-overflow-scrolling: touch;
  }
}

/* List-toolbar filter chips — shared height; radius follows Control Shape */
.exits-filter-pill {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 0.375rem;
  min-height: var(--exits-chip-min-height);
  height: var(--exits-chip-min-height);
  padding-inline: var(--exits-chip-padding-x);
  padding-block: 0;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-control-radius);
  background: var(--exits-surface);
  color: var(--exits-text);
  font-size: var(--exits-chip-font-size);
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
  transition:
    background-color var(--exits-motion-fast) ease,
    border-color var(--exits-motion-fast) ease,
    color var(--exits-motion-fast) ease,
    border-radius var(--exits-motion-fast) var(--exits-ease-standard),
    box-shadow var(--exits-motion-fast) ease;
}

button.exits-filter-pill {
  cursor: pointer;
}

button.exits-filter-pill:hover:not(:disabled) {
  background: var(--exits-surface-muted);
}

button.exits-filter-pill:focus-visible {
  outline: none;
  border-color: var(--exits-primary);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--exits-primary) 28%, transparent);
}

button.exits-filter-pill.exits-filter-pill--button {
  min-height: var(--exits-chip-min-height);
  height: var(--exits-chip-min-height);
  padding-block: 0;
  background: transparent;
}

.exits-filter-pill__badge {
  display: inline-flex;
  min-height: 1.25rem;
