  border-radius: var(--exits-control-radius);
  background: var(--exits-surface);
  color: var(--exits-text);
  font-size: var(--exits-chip-font-size);
  font-weight: 500;
  line-height: 1.2;
  white-space: nowrap;
  transform: translateZ(0);
  animation: exits-chip-in var(--exits-motion-normal) cubic-bezier(0.22, 1, 0.36, 1) both;
  transition:
    background-color var(--exits-motion-fast) ease,
    border-color var(--exits-motion-fast) ease,
    color var(--exits-motion-fast) ease,
    border-radius var(--exits-motion-fast) var(--exits-ease-standard),
    box-shadow var(--exits-motion-fast) ease,
    transform var(--exits-motion-fast) cubic-bezier(0.22, 1, 0.36, 1);
}

/* Steps keep a stable field-like radius (not global Control Shape). */
.exits-chip-bar--steps .exits-chip {
  border-radius: var(--exits-radius-md);
}

.exits-chip:nth-child(1) {
