/*
 * Button closed-field for ExitsSelect / ExitsMultiSelect.
 * Native chrome only targets select.exits-select — without this, the trigger is a
 * borderless “ghost” control (invisible in BottomSheet / form fields).
 * Toolbar outline variant remains under .po-category-multiselect (more specific).
 */
.receive-stock-category-trigger.exits-select,
.receive-stock-category-trigger.catalog-form-select {
  box-sizing: border-box;
  display: inline-flex;
  width: 100%;
  min-width: 0;
  height: var(--exits-control-height);
  min-height: var(--exits-control-height);
  max-height: var(--exits-control-height);
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin: 0;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-field-radius, var(--exits-radius-md));
  background-color: var(--exits-surface);
  /* Drop native select caret; Lucide ChevronDown is the single indicator. */
  background-image: none;
  padding-block: 0;
  padding-inline: var(--exits-control-padding-x);
  font: inherit;
  font-size: var(--exits-text-md);
  font-weight: 400;
  line-height: calc(var(--exits-control-height) - 2px);
  color: var(--exits-text);
  text-align: start;
  cursor: pointer;
  transition:
    border-color var(--exits-motion-fast) ease,
    box-shadow var(--exits-motion-fast) ease,
    background-color var(--exits-motion-fast) ease;
}

.receive-stock-category-trigger.exits-select:hover:not(:disabled):not(:focus-visible),
.receive-stock-category-trigger.catalog-form-select:hover:not(:disabled):not(:focus-visible) {
  border-color: var(--exits-border-strong);
}

.receive-stock-category-trigger.exits-select:focus-visible,
.receive-stock-category-trigger.catalog-form-select:focus-visible {
  outline: none;
  border-color: var(--exits-field-border-focus);
  box-shadow: 0 0 0 var(--exits-field-focus-ring-width) var(--exits-field-focus-ring);
}

.receive-stock-category-trigger.exits-select[aria-invalid="true"],
.receive-stock-category-trigger.catalog-form-select[aria-invalid="true"],
.receive-stock-category-trigger.exits-select.border-destructive,
.receive-stock-category-trigger.catalog-form-select.border-destructive {
  border-color: var(--exits-field-border-error);
}

.receive-stock-category-trigger.exits-select[aria-invalid="true"]:focus-visible,
.receive-stock-category-trigger.catalog-form-select[aria-invalid="true"]:focus-visible,
.receive-stock-category-trigger.exits-select.border-destructive:focus-visible,
.receive-stock-category-trigger.catalog-form-select.border-destructive:focus-visible {
  outline: none;
  border-color: var(--exits-field-border-error);
  box-shadow: 0 0 0 var(--exits-field-focus-ring-width) var(--exits-field-focus-ring-error);
}

.receive-stock-category-trigger.exits-select:disabled,
.receive-stock-category-trigger.catalog-form-select:disabled {
  cursor: not-allowed;
  opacity: 0.5;
  background-color: var(--exits-surface-muted);
  color: var(--exits-text-muted);
}

[data-theme="dark"] .receive-stock-category-trigger.exits-select,
[data-theme="dark"] .receive-stock-category-trigger.catalog-form-select,
[data-theme="system"] .receive-stock-category-trigger.exits-select,
[data-theme="system"] .receive-stock-category-trigger.catalog-form-select,
:root:not([data-theme]) .receive-stock-category-trigger.exits-select,
:root:not([data-theme]) .receive-stock-category-trigger.catalog-form-select {
  background-image: none;
}

@media (prefers-color-scheme: dark) {
  [data-theme="system"] .receive-stock-category-trigger.exits-select,
  [data-theme="system"] .receive-stock-category-trigger.catalog-form-select,
  :root:not([data-theme]) .receive-stock-category-trigger.exits-select,
