  margin: 0;
  padding: 0.25rem 0 0.5rem;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.exits-activity-timeline__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--exits-timeline-marker) minmax(0, 1fr);
  column-gap: 0.75rem;
  align-items: start;
  padding-bottom: 1.25rem;
}

.exits-activity-timeline__item:last-child {
  padding-bottom: 0;
}

.exits-activity-timeline__item[data-side="start"] .exits-activity-timeline__when {
  grid-column: 1;
  grid-row: 1;
  justify-self: end;
  text-align: end;
}

.exits-activity-timeline__item[data-side="start"] .exits-activity-timeline__card {
  grid-column: 3;
  grid-row: 1;
}

.exits-activity-timeline__item[data-side="end"] .exits-activity-timeline__card {
  grid-column: 1;
  grid-row: 1;
  justify-self: stretch;
}

.exits-activity-timeline__item[data-side="end"] .exits-activity-timeline__when {
  grid-column: 3;
  grid-row: 1;
  justify-self: start;
  text-align: start;
}

.exits-activity-timeline__rail {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  align-self: stretch;
  min-height: 100%;
}

