@keyframes exits-panel-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Right/left side drawer (preferences, etc.) */
.exits-side-drawer {
  position: fixed;
  inset: 0;
  z-index: 70;
  pointer-events: none;
}

/* VISUALLY HIDDEN OR LOGICALLY CLOSED OVERLAYS MUST NEVER HIT-TEST.
   Exiting / not-yet-entered: never steal clicks (opacity alone still hit-tests;
   parent PE:none is insufficient when descendants use PE:auto — Case B). */
.exits-side-drawer[data-interactive="false"],
.exits-side-drawer[data-interactive="false"] * {
  pointer-events: none !important;
}

.exits-side-drawer__backdrop {
  position: absolute;
  inset: 0;
  background: color-mix(in srgb, #0f172a 52%, transparent);
  opacity: 0;
  /* Hit-testing is gated by data-interactive (open && entered), not opacity alone. */
  pointer-events: none;
  transition: opacity var(--exits-motion-normal) var(--exits-ease-standard);
}

.exits-side-drawer__backdrop[data-open="true"] {
  opacity: 1;
}

.exits-side-drawer__backdrop[data-interactive="true"] {
  pointer-events: auto;
}

.exits-side-drawer__panel {
  position: absolute;
  top: max(0.75rem, env(safe-area-inset-top, 0px));
  bottom: max(0.75rem, env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  width: min(calc(100% - (2 * 0.75rem)), 26rem);
  max-width: calc(100% - (2 * 0.75rem));
  height: auto;
  max-height: none;
  pointer-events: none;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--exits-border) 72%, transparent);
  border-radius: var(--exits-radius-md);
  background: var(--exits-surface);
  box-shadow:
    0 4px 16px color-mix(in srgb, #0f172a 10%, transparent),
    0 16px 48px color-mix(in srgb, #0f172a 16%, transparent);
  transition: transform var(--exits-motion-slow) var(--exits-ease-emphasized);
}

.exits-side-drawer__panel[data-side="right"] {
  right: max(0.75rem, env(safe-area-inset-right, 0px));
  transform: translateX(calc(100% + 1.25rem));
}

.exits-side-drawer__panel[data-side="left"] {
  left: max(0.75rem, env(safe-area-inset-left, 0px));
  transform: translateX(calc(-100% - 1.25rem));
}

.exits-side-drawer__panel[data-open="true"] {
  transform: translateX(0);
}

.exits-side-drawer__panel[data-interactive="true"] {
  pointer-events: auto;
}

/* Large: FormDrawer / responsive SideDrawer — centered dialog instead of side slide. */
@media (min-width: 1024px) {
  .exits-side-drawer--center-lg .exits-side-drawer__panel,
  .exits-side-drawer--center-lg .exits-side-drawer__panel[data-side="right"],
  .exits-side-drawer--center-lg .exits-side-drawer__panel[data-side="left"] {
    /* Horizontally centered, top-anchored — not mid-viewport (keeps footer off screen middle). */
    top: max(1.25rem, env(safe-area-inset-top, 0px), 8vh);
    left: 50%;
    right: auto;
    bottom: auto;
    width: min(30rem, calc(100vw - 2.5rem));
    max-width: min(30rem, calc(100vw - 2.5rem));
    height: auto;
    max-height: none;
    opacity: 0;
    overflow: visible;
    transform: translate(-50%, 0.75rem) scale(0.96);
    transition:
      transform var(--exits-motion-slow) var(--exits-ease-emphasized),
      opacity var(--exits-motion-normal) var(--exits-ease-standard);
  }

  .exits-side-drawer--center-lg .exits-side-drawer__panel[data-open="true"] {
    opacity: 1;
    transform: translate(-50%, 0) scale(1);
  }

  .exits-side-drawer--center-lg .exits-form-drawer__footer,
  .exits-side-drawer--center-lg .exits-form-drawer__footer-actions {
    justify-content: flex-end;
  }

  .exits-side-drawer--center-lg .exits-form-drawer__footer-actions > button {
    flex: 0 0 auto;
  }

  /* Centered shell sizes to content — no inner scrollbar. */
  .exits-side-drawer--center-lg .exits-side-drawer__body,
  .exits-side-drawer--center-lg .exits-form-drawer__panel .exits-side-drawer__body {
    flex: 0 0 auto;
    min-height: 0;
    overflow: visible;
  }

  .exits-side-drawer--center-lg .exits-form-drawer {
    flex: 0 0 auto;
    height: auto;
    max-height: none;
    overflow: visible;
  }

  .exits-side-drawer--center-lg .exits-form-drawer__body {
    flex: 0 0 auto;
    min-height: 0;
    overflow: visible;
    overflow-y: visible;
  }

  .exits-side-drawer--center-lg .exits-form-drawer__panel--sm {
    width: min(24rem, calc(100vw - 2.5rem));
    max-width: min(24rem, calc(100vw - 2.5rem));
  }

  .exits-side-drawer--center-lg .exits-form-drawer__panel--md {
    width: min(30rem, calc(100vw - 2.5rem));
    max-width: min(30rem, calc(100vw - 2.5rem));
  }

  .exits-side-drawer--center-lg .exits-form-drawer__panel--lg {
    width: min(36rem, calc(100vw - 2.5rem));
    max-width: min(36rem, calc(100vw - 2.5rem));
  }
}

