/* Personal shell: every page root uses the full content column. */
.personal-shell .personal-page,
.personal-shell .personal-commerce-page,
.personal-shell .personal-commerce-page.personal-page,
.personal-shell .admin-shell__content > .exits-page,
.personal-shell .personal-shell__content > .exits-page {
