  margin-inline: 0;
  width: 100%;
}

/*
 * Personal uses shared shell tokens (solid chrome — no glass / blur).
 * Paint html/body/#root too — otherwise the old --exits-bg wash hides shell changes.
 */
html:has(.personal-shell),
html:has(.personal-shell) body,
html:has(.personal-shell) #root,
.personal-shell,
[data-background] .personal-shell {
  background: var(--exits-shell-content-bg, #e8ecf2) !important;
  background-image: none !important;
  color: var(--exits-text);
}

html:has(.admin-shell):not(:has(.personal-shell)),
html:has(.admin-shell):not(:has(.personal-shell)) body,
html:has(.admin-shell):not(:has(.personal-shell)) #root,
html:has(.operations-shell),
html:has(.operations-shell) body,
html:has(.operations-shell) #root,
.admin-shell,
.operations-shell {
  background: var(--exits-shell-content-bg, #e8ecf2) !important;
  background-image: none !important;
}

.personal-shell .personal-sidebar .admin-sidebar__brand {
  background: transparent;
  box-shadow: none;
  border-bottom: 1px solid var(--exits-shell-divider, var(--exits-border));
}

/* Personal low-cost effects: shadows change instantly on hover. Only transform and colors animate. */
.personal-shell .exits-list__card {
  transition:
    border-color var(--exits-motion-fast) ease,
    background-color var(--exits-motion-fast) ease,
    transform var(--exits-motion-fast) cubic-bezier(0.22, 1, 0.36, 1);
}

/* A resting card does not hold its own GPU layer; long lists stay cheap. */
.personal-shell .exits-list__card:not(:hover):not(:active) {
  transform: none;
}

.personal-shell .role-action-tile {
  transition:
    background-color var(--exits-motion-fast) ease,
    border-color var(--exits-motion-fast) ease,
    opacity var(--exits-motion-fast) ease,
    transform var(--exits-motion-fast) ease;
}

.personal-shell .role-action-tile--primary:hover {
  box-shadow: 0 2px 6px color-mix(in srgb, var(--exits-primary) 24%, transparent);
}

.personal-shell .app-top-bar--personal {
  position: relative;
  isolation: isolate;
  z-index: 30;
  /* Blend into page content — no separate chrome strip. */
  border-bottom: 0 !important;
  background: var(--exits-shell-content-bg, #e8ecf2) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  animation: none !important;
  /* Same radius as Soft Glass screen edge (concentric with 1px frame border). */
  border-top-left-radius: calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px);
  border-top-right-radius: calc(var(--ui-standards-crystal-radius, var(--soft-glass-radius, 1.1rem)) - 1px);
  overflow: hidden;
}

/*
 * Soft Glass edge — top + bottom of Personal top bar (same recipe as sidenav).
 * Top (::before) mirrors bottom (::after) so both lips match the Soft Glass screen edge.
 */
.personal-shell .app-top-bar--personal::before,
.personal-shell .app-top-bar--personal::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  z-index: 4;
  height: 1.1rem;
  pointer-events: none;
}

.personal-shell .app-top-bar--personal::before {
  inset-block-start: 0;
