.personal-home-infodata-card {
  --personal-infodata-size: 4.25rem;
  --personal-infodata: var(--exits-primary);
  position: relative;
  display: flex;
  align-items: center;
  box-sizing: border-box;
  /* Leave room for the overhanging circle so the bar aligns with cards above. */
  width: calc(100% - var(--personal-infodata-size) * 0.42);
  max-width: calc(100% - var(--personal-infodata-size) * 0.42);
  min-width: 0;
  height: var(--personal-infodata-size);
  min-height: var(--personal-infodata-size);
  margin: 0.35rem 0 0.15rem calc(var(--personal-infodata-size) * 0.42);
  padding: 0.45rem 1.1rem 0.45rem calc(var(--personal-infodata-size) * 0.92);
  overflow: visible;
  border: 0;
  border-radius: 0.2rem;
  color: #fff;
  text-decoration: none;
  background-color: var(--personal-infodata);
  background-image: linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.34),
    rgba(255, 255, 255, 0) 48%,
    rgba(0, 0, 0, 0.14)
  );
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 2px 6px color-mix(in srgb, var(--personal-infodata) 18%, transparent);
  transition: transform 160ms ease;
}

.personal-home-infodata-card:hover {
  transform: scale(1.02);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.45),
