/*
 * Soft Glass radius tokens (LOCKED — soft-glass-card-global-default).
 * SOFT_GLASS_RADIUS / SOFT_GLASS_RIBBON_RADIUS — command: ext soft-glass ribbon radius
 *
 * Crystal screen-edge tokens: UI Standards `.app-shell--full` + Personal `.personal-crystal-screen`
 * (whole screen: top bar + sidenav + main). Color follows Preferences primary.
 */
:root {
  --soft-glass-radius: 1.1rem;
  --soft-glass-ribbon-radius: 1.1rem 1.1rem 1.1rem 0;
  /* LOCKED: SOFT_GLASS_FIELD_RADIUS — Soft Glass input / dropdown (Soft control). */
  --soft-glass-field-radius: 0.6875rem;
  /*
   * Screen-edge Soft Glass rim (Personal + UI Standards) — same recipe as Soft Glass cards:
   * 1px slate+primary soft border, inset top highlight, soft primary elevation. No hard glow.
   */
  --soft-glass-crystal-soft: color-mix(in srgb, var(--exits-primary) 42%, #fff);
  --soft-glass-crystal-edge: color-mix(in srgb, #e2e8f0 62%, var(--soft-glass-crystal-soft));
  --soft-glass-crystal-border: 1px solid var(--soft-glass-crystal-edge);
  --soft-glass-crystal-rim:
    0 1px 0 rgba(255, 255, 255, 0.78) inset,
    0 4px 12px color-mix(in srgb, var(--exits-primary) 8%, transparent);
}

[data-theme="dark"] {
  --soft-glass-crystal-soft: color-mix(in srgb, var(--exits-primary) 42%, #1e293b);
  --soft-glass-crystal-edge: color-mix(in srgb, var(--exits-primary) 16%, #475569);
  --soft-glass-crystal-rim:
    0 1px 0 color-mix(in srgb, #fff 12%, transparent) inset,
    0 4px 14px rgba(0, 0, 0, 0.28);
}

/* Legacy overhanging ribbon — still used on non–Soft Glass People / Profile / workplaces. */
.personal-tracker-card__ribbon {
  position: absolute;
  top: 0.45rem;
  left: -0.7rem;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0;
  padding: 0.35rem 0.85rem;
  border-radius: 0.2rem 0.2rem 0.2rem 0;
  /* Success — distinct from Quick actions (warn) and Todo (info). */
  background-color: var(--exits-severity-success, #22c55e);
  color: var(--exits-severity-success-foreground, #fff);
  font-size: 0.9375rem;
