/*
 * Money I lent / I owe — Soft Glass actions Card (ribbon + chips).
 * Beat exits-card / personal transparent section chrome so the glass shell is visible.
 */
.utang-money-page .utang-money-main-card.utang-money-glass[data-shell="soft-glass"],
.utang-money-page .utang-money-main-card.utang-ribbon-card.utang-money-glass,
.utang-money-page .utang-money-actions-card.utang-money-glass[data-shell="soft-glass"],
.utang-money-page .utang-money-actions-card.utang-ribbon-card.utang-money-glass {
  /* Soft Glass shell + ribbon follow Preferences global primary. */
  --utang-money-glass-chip: var(--exits-primary);
  --utang-money-glass-deep: var(--exits-primary-hover);
  --utang-money-glass-soft: color-mix(in srgb, var(--exits-primary) 42%, #fff);
  --utang-money-glass-wash: color-mix(in srgb, var(--exits-primary) 8%, #fff);
  --utang-money-glass-mid: color-mix(in srgb, var(--exits-primary) 16%, #fff);
  --utang-money-glass-ink: color-mix(in srgb, #000 28%, var(--exits-primary));
  position: relative;
  overflow: visible;
  margin-left: 0.9rem;
  margin-right: 0.9rem;
  /* Extra top: overhanging ribbon + gap before Soft Glass quick actions.
   * Shell left/right gap matched (follow left). */
  padding: 4rem 0.65rem 0.9rem 0.65rem;
  border: 1px solid color-mix(in srgb, #e2e8f0 55%, var(--utang-money-glass-soft));
  border-radius: 1.1rem;
  background: linear-gradient(
    165deg,
    color-mix(in srgb, #fff 72%, var(--utang-money-glass-wash)) 0%,
    color-mix(in srgb, var(--utang-money-glass-wash) 78%, #fff) 48%,
    color-mix(in srgb, var(--utang-money-glass-mid) 70%, #fff) 100%
  );
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.85) inset,
    0 6px 16px color-mix(in srgb, var(--utang-money-glass-chip) 12%, transparent);
  transition:
    background-color 120ms ease,
    border-color 120ms ease,
    color 120ms ease;
