/*
 * Activity table: auto layout so Status/Created size to content.
 * Fixed layout crushed columns to header text; body spilled under wrong headers on h-scroll.
 */
.utang-activity-table .exits-table {
  table-layout: auto;
  width: max-content;
  min-width: 100%;
}

.utang-activity-table .exits-table-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/* Activity Entry: narrower than default flex; ellipsis for long titles. */
.utang-activity-table .utang-activity-col-entry {
  width: 8.5rem;
  min-width: 6.5rem;
  max-width: 9.5rem;
}

/* Activity Status: Soft Glass tags — column width = 3 tags (one row). */
.utang-activity-table .utang-activity-col-status {
  width: 1%;
  white-space: nowrap;
}

.utang-activity-table .utang-activity-status-tags {
  width: max-content;
}

.utang-activity-table .utang-activity-status-tags .exits-status-chip {
  flex: 0 0 auto;
  white-space: nowrap;
}

/* Activity Due: shrink to label · date (e.g. Overdue · 10/22/2026). */
.utang-activity-table .utang-activity-col-due {
  width: 1%;
  white-space: nowrap;
}

/* Activity Created: full date-time, column only as wide as the value. */
.utang-activity-table .utang-activity-col-created {
  width: 1%;
  white-space: nowrap;
}

.utang-activity-table .utang-activity-created-date {
  display: inline-block;
  font-variant-numeric: tabular-nums;
}

/* Amount can show balance-after — wider than Entry. */
.utang-activity-table .exits-table__col--numeric,
.utang-activity-table .utang-activity-col-amount {
  max-width: none;
  width: 1%;
  min-width: 10.5rem;
  white-space: nowrap;
}

.utang-activity-table .utang-activity-balance-after,
.utang-activity-table .utang-activity-col-due .utang-settings-card__tab-text--danger {
