}

/* Workplace membership cards reuse the Card pin shape. */
.personal-workplace-pin {
  --qcard-pin-from: var(--exits-primary);
  --qcard-pin-to: color-mix(in srgb, var(--exits-primary) 58%, #fff);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  align-self: center;
  width: 50%;
  margin-top: -0.9rem;
  padding: 1.35rem 0 0.85rem;
  overflow: visible;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.personal-workplace-pin__shell {
  position: relative;
  z-index: 1;
  display: flex;
  width: 100%;
  flex-direction: column;
  align-items: center;
  padding: 2.15rem 1.05rem 2.65rem;
  overflow: visible;
  background: transparent;
  color: var(--exits-text);
}

.personal-workplace-pin__shell::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--exits-surface);
  pointer-events: none;
  clip-path: polygon(
    0 0,
    100% 0,
    100% calc(100% - 1.85rem),
    50% 100%,
    0 calc(100% - 1.85rem)
  );
  filter: drop-shadow(0 14px 28px rgba(15, 23, 42, 0.14));
}

.personal-workplace-pin__medallion {
  position: absolute;
  top: 0;
  left: 50%;
  z-index: 3;
  display: grid;
  place-items: center;
  width: 3.65rem;
  height: 3.65rem;
  transform: translateX(-50%);
  border-radius: 999px;
  color: var(--exits-primary-foreground, #fff);
  background: linear-gradient(to bottom, var(--qcard-pin-from) 0%, var(--qcard-pin-to) 100%);
  box-shadow:
    0 0 0 0.28rem var(--exits-surface),
    0 8px 18px color-mix(in srgb, var(--qcard-pin-from) 40%, transparent);
}

.personal-workplace-pin__medallion svg {
  width: 1.45rem;
  height: 1.45rem;
}

.personal-workplace-pin__ribbon {
  position: relative;
  z-index: 2;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: calc(100% + 3.7rem);
  margin: 0.55rem 0 0.85rem;
  padding: 0.45rem 1rem;
  color: var(--exits-primary-foreground, #fff);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-align: center;
  text-transform: uppercase;
  background: linear-gradient(to right, var(--qcard-pin-from) 0%, var(--qcard-pin-to) 100%);
  box-shadow: 0 6px 14px color-mix(in srgb, var(--qcard-pin-from) 32%, transparent);
}

.personal-workplace-pin__fold {
  position: absolute;
  top: 100%;
  width: 0;
  height: 0;
  pointer-events: none;
}

.personal-workplace-pin__fold--left {
  left: 0;
  border-top: 0.45rem solid color-mix(in srgb, #000 35%, var(--qcard-pin-from));
  border-left: 0.7rem solid transparent;
}

.personal-workplace-pin__fold--right {
  right: 0;
  border-top: 0.45rem solid color-mix(in srgb, #000 35%, var(--qcard-pin-to));
  border-right: 0.7rem solid transparent;
}

.personal-workplace-pin__body {
  position: relative;
  z-index: 1;
  display: flex;
  width: 80%;
  flex-direction: column;
  align-items: center;
  gap: 0.55rem;
  text-align: center;
}

.personal-workplace-pin__login {
  width: 72%;
}

/*
 * Workplaces Soft Glass — stores (mine) / info (pending).
 * Lock: soft-glass-card-global-default. No blur, neon, or lift.
 */
.workplaces-page .workplaces-glass[data-shell="soft-glass"],
.workplaces-page .workplaces-glass.person-ribbon-card {
