/* Shared ExItS loading system */
.exits-loader-mark {
  position: relative;
  width: 3.25rem;
  height: 3.25rem;
}

.exits-loader-mark--sm {
  width: 1.25rem;
  height: 1.25rem;
}

.exits-loader-mark--lg {
  width: 3.75rem;
  height: 3.75rem;
}

.exits-loader-mark__ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 3px solid var(--exits-surface-muted);
  border-top-color: var(--exits-primary);
  animation: exits-context-switch-spin 0.9s linear infinite;
}

.exits-loader-mark--sm .exits-loader-mark__ring {
  border-width: 2px;
}

.exits-loader-mark__core {
  position: absolute;
  inset: 28%;
  border-radius: 50%;
  background: color-mix(in srgb, var(--exits-primary) 22%, var(--exits-surface-muted));
  animation: exits-context-switch-pulse 1.4s ease-in-out infinite;
}

.exits-app-boot-loader {
  background:
    radial-gradient(
      120% 80% at 50% 0%,
      color-mix(in srgb, var(--exits-primary) 10%, transparent),
      transparent 55%
    ),
    var(--exits-surface);
}

.exits-app-boot-loader__brand {
  letter-spacing: -0.02em;
}

.exits-workspace-transition {
  position: fixed;
  inset: 0;
  z-index: 1400;
  display: grid;
  place-items: center;
  /* Only block while actively binding — never by default. */
  pointer-events: none;
}

.exits-workspace-transition[data-active="true"] {
  pointer-events: auto;
}

/* VISUALLY HIDDEN OR LOGICALLY CLOSED OVERLAYS MUST NEVER HIT-TEST.
   Min-visible fade after bind settles — paint only, do not block the shell.
   Parent PE:none is not enough: descendants with PE:auto still hit-test (Case B). */
.exits-workspace-transition[data-active="false"],
.exits-workspace-transition[data-active="false"] * {
  pointer-events: none !important;
}

.exits-workspace-transition__panel {
  position: relative;
  z-index: 1;
  display: flex;
  min-width: min(18rem, calc(100vw - 2rem));
  max-width: 22rem;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
  border: 1px solid var(--exits-border);
  border-radius: var(--exits-radius-lg);
  background: var(--exits-surface);
  padding: 1.25rem 1.35rem;
  box-shadow: 0 12px 40px color-mix(in srgb, #000 12%, transparent);
}

.exits-inline-spinner {
  display: inline-block;
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, currentColor 25%, transparent);
  border-top-color: currentColor;
  animation: exits-context-switch-spin 0.75s linear infinite;
}

.exits-background-refresh {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.exits-background-refresh::before {
  content: "";
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  border: 1.5px solid color-mix(in srgb, var(--exits-primary) 30%, transparent);
  border-top-color: var(--exits-primary);
  animation: exits-context-switch-spin 0.8s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .exits-loader-mark__ring,
  .exits-loader-mark__core,
  .exits-inline-spinner,
  .exits-background-refresh::before {
    animation: none;
  }

  .exits-loader-mark__core {
    opacity: 0.9;
    transform: none;
  }

  .exits-inline-spinner,
  .exits-background-refresh::before {
    border-top-color: color-mix(in srgb, currentColor 55%, transparent);
  }
}

/* ---- Manage Business admin shell ---- */
.operations-shell__body {
  width: 100%;
  max-width: 1600px;
  margin-inline: auto;
}

/* Operations: always viewport-locked; main content scrolls when needed. */
.operations-shell--viewport-lock {
  height: 100dvh;
  max-height: 100dvh;
  overflow: hidden;
}

.operations-shell--viewport-lock .operations-shell__body,
.operations-shell--viewport-lock .operations-shell__main {
  min-height: 0;
  overflow: hidden;
}

.operations-shell--viewport-lock .operations-shell__content {
  display: flex;
  width: 100%;
  min-width: 0;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  box-sizing: border-box;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior-y: contain;
  /* Block padding only here — equal inline gutters are desktop-only (sidebar breathing room). */
  padding-block: var(--exits-page-gutter-block);
}

/*
 * Desktop content gutter: equal internal padding after the sidenav divider.
 * Not a shell column gap — sidebar and content region still touch.
 * Start + end must match so page surfaces are not flush to the scrollbar.
 */
@media (min-width: 1024px) {
  .operations-shell--viewport-lock:not(.operations-shell--sell-floor) .operations-shell__content {
    padding-inline: var(--exits-page-gutter-inline);
  }

  .admin-shell__content {
    padding-inline: var(--exits-page-gutter-inline);
    padding-block: var(--exits-page-gutter-block);
    box-sizing: border-box;
  }
}

.operations-shell--sell-floor .operations-shell__body {
  max-width: min(100%, 100rem);
}

.operations-shell--sell-floor .operations-shell__content {
  overflow: hidden;
  padding-block: 0.35rem;
  padding-inline: 0;
}

@media (min-width: 1024px) {
  .operations-shell--sell-floor .operations-shell__content {
    padding-inline: var(--exits-page-gutter-ops-inline);
  }
}

/* Ops sidebar: stretch to locked shell height with internal nav scroll. */
.operations-shell .operations-sidebar.admin-sidebar {
  position: relative;
  top: auto;
  align-self: stretch;
