/* Portaled Soft Glass tooltip (escapes table / sidebar overflow). Lock: tooltip-global-default. */
.exits-tooltip {
  --exits-tooltip-chip: var(--exits-primary);
  --exits-tooltip-fill: var(--exits-surface-elevated);
  --exits-tooltip-edge: color-mix(in srgb, #64748b 55%, var(--exits-tooltip-chip));
  --exits-tooltip-arrow: 0.5rem;
  position: fixed;
  max-width: min(16rem, calc(100vw - 1rem));
  padding: 0.35rem 0.65rem;
  border-radius: 0.5rem;
  border: 1px solid var(--exits-tooltip-edge);
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--exits-tooltip-chip) 14%, transparent) 0%,
      color-mix(in srgb, var(--exits-tooltip-fill) 92%, transparent) 55%,
      color-mix(in srgb, var(--exits-tooltip-fill) 96%, transparent) 100%
    ),
    var(--exits-tooltip-fill);
  color: var(--exits-text);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 55%, transparent),
    0 1px 2px color-mix(in srgb, #0f172a 6%, transparent),
    0 6px 16px color-mix(in srgb, var(--exits-tooltip-chip) 12%, transparent);
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: var(--exits-tracking-normal);
  white-space: nowrap;
  pointer-events: none;
  animation: exits-tooltip-in var(--exits-motion-fast) var(--exits-ease-standard) both;
}

.exits-tooltip__arrow {
  position: absolute;
  width: var(--exits-tooltip-arrow);
  height: var(--exits-tooltip-arrow);
  background: var(--exits-tooltip-fill);
  border: 1px solid var(--exits-tooltip-edge);
  transform: rotate(45deg);
  box-sizing: border-box;
}

/* Tip above trigger → caret points down. */
.exits-tooltip[data-placement="top"] .exits-tooltip__arrow {
  bottom: calc(var(--exits-tooltip-arrow) / -2);
  left: 50%;
  margin-left: calc(var(--exits-tooltip-arrow) / -2);
  border-top: none;
  border-left: none;
  box-shadow: 1px 1px 2px color-mix(in srgb, #0f172a 5%, transparent);
}

/* Tip below trigger → caret points up. */
.exits-tooltip[data-placement="bottom"] .exits-tooltip__arrow {
  top: calc(var(--exits-tooltip-arrow) / -2);
  left: 50%;
  margin-left: calc(var(--exits-tooltip-arrow) / -2);
  border-bottom: none;
  border-right: none;
  box-shadow: -1px -1px 1px color-mix(in srgb, #fff 40%, transparent);
}

/* Tip to the end (right in LTR) → caret points toward trigger (start). */
.exits-tooltip[data-placement="end"] .exits-tooltip__arrow {
  left: calc(var(--exits-tooltip-arrow) / -2);
  top: 50%;
  margin-top: calc(var(--exits-tooltip-arrow) / -2);
  border-top: none;
  border-right: none;
  box-shadow: -1px 1px 2px color-mix(in srgb, #0f172a 5%, transparent);
}

/* Tip to the start (left in LTR) → caret points toward trigger (end). */
.exits-tooltip[data-placement="start"] .exits-tooltip__arrow {
  right: calc(var(--exits-tooltip-arrow) / -2);
  top: 50%;
  margin-top: calc(var(--exits-tooltip-arrow) / -2);
  border-bottom: none;
  border-left: none;
  box-shadow: 1px -1px 2px color-mix(in srgb, #0f172a 5%, transparent);
}

[data-theme="dark"] .exits-tooltip {
  --exits-tooltip-fill: #1e293b;
  --exits-tooltip-edge: color-mix(in srgb, #94a3b8 40%, var(--exits-tooltip-chip));
  background:
    linear-gradient(
      165deg,
