}

[data-theme="dark"] .exits-tooltip[data-placement="top"] .exits-tooltip__arrow {
  box-shadow: 1px 1px 2px color-mix(in srgb, #000 30%, transparent);
}

[data-theme="dark"] .exits-tooltip[data-placement="bottom"] .exits-tooltip__arrow {
