}

.ui-standards-qcheckbox {
  display: inline-flex;
  align-items: center;
  flex-wrap: nowrap;
  cursor: pointer;
  color: var(--exits-text, rgba(0, 0, 0, 0.87));
  font-size: 14px;
  line-height: 1.25;
  user-select: none;
}

.ui-standards-qcheckbox--disabled {
  opacity: 0.75;
  cursor: default;
}

.ui-standards-qcheckbox__inner {
  position: relative;
  width: 2.857em;
  min-width: 2.857em;
  height: 2.857em;
  border-radius: 50%;
  color: rgba(0, 0, 0, 0.54);
}

.ui-standards-qcheckbox:not(.ui-standards-qcheckbox--disabled) .ui-standards-qcheckbox__inner::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.12;
  transform: scale(0);
  transition: transform 0.22s cubic-bezier(0, 0, 0.2, 1);
  pointer-events: none;
}

.ui-standards-qcheckbox:not(.ui-standards-qcheckbox--disabled):focus-visible .ui-standards-qcheckbox__inner::before {
  transform: scale(1);
}

.ui-standards-qcheckbox--dense:not(.ui-standards-qcheckbox--disabled):focus-visible .ui-standards-qcheckbox__inner::before {
  transform: scale(1.4);
}

@media (any-hover: hover) {
  .ui-standards-qcheckbox:not(.ui-standards-qcheckbox--disabled):hover .ui-standards-qcheckbox__inner::before {
    transform: scale(1);
  }

  .ui-standards-qcheckbox--dense:not(.ui-standards-qcheckbox--disabled):hover .ui-standards-qcheckbox__inner::before {
    transform: scale(1.4);
  }
}

[data-theme="dark"] .ui-standards-qcheckbox__inner::before,
.ui-standards-qcheckbox--on-dark .ui-standards-qcheckbox__inner::before {
  opacity: 0.32 !important;
}

.ui-standards-qcheckbox__bg {
  position: absolute;
  top: 25%;
  left: 25%;
  width: 50%;
  height: 50%;
  border: 2px solid currentColor;
  border-radius: 2px;
  background: transparent;
}

.ui-standards-qcheckbox__svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  color: #ffffff;
}

.ui-standards-qcheckbox__truthy {
  fill: none;
  stroke: currentColor;
  stroke-width: 3.12px;
  stroke-dasharray: 29.78334;
  stroke-dashoffset: 29.78334;
}

.ui-standards-qcheckbox__inner--truthy {
  color: var(--qcheckbox-color, var(--exits-primary));
}

.ui-standards-qcheckbox__inner--truthy .ui-standards-qcheckbox__bg {
  background: currentColor;
}

.ui-standards-qcheckbox__inner--truthy .ui-standards-qcheckbox__truthy {
  stroke-dashoffset: 0;
}

.ui-standards-qcheckbox--dense .ui-standards-qcheckbox__inner {
  width: 1.429em;
  min-width: 1.429em;
  height: 1.429em;
}

.ui-standards-qcheckbox--dense .ui-standards-qcheckbox__bg {
  top: 5%;
  left: 5%;
  width: 90%;
  height: 90%;
}

.ui-standards-qcheckbox--dense .ui-standards-qcheckbox__label {
  padding-left: 0.5em;
}

[data-theme="dark"] .ui-standards-qcheckbox__inner--truthy,
[data-theme="dark"] .ui-standards-qcheckbox__inner--indet {
  color: var(--qcheckbox-color, var(--exits-primary));
}

@media (prefers-color-scheme: dark) {

  [data-theme="system"] .ui-standards-qcheckbox__inner--truthy,
  [data-theme="system"] .ui-standards-qcheckbox__inner--indet,
  :root:not([data-theme]) .ui-standards-qcheckbox__inner--truthy,
  :root:not([data-theme]) .ui-standards-qcheckbox__inner--indet {
    color: var(--qcheckbox-color, var(--exits-primary));
  }
}

.ui-standards-qbtn--raised {
  box-shadow:
    0 5px 5px -3px rgba(0, 0, 0, 0.28),
    0 8px 10px 1px rgba(0, 0, 0, 0.18),
    0 3px 14px 2px rgba(0, 0, 0, 0.14);
}

.ui-standards-qbtn--raised:hover {
  filter: none;
  transform: translateY(-2px);
  box-shadow:
    0 7px 8px -4px rgba(0, 0, 0, 0.28),
    0 12px 17px 2px rgba(0, 0, 0, 0.18),
    0 5px 22px 4px rgba(0, 0, 0, 0.14);
}

.ui-standards-qbtn--raised:active {
  transform: translateY(0);
}

/* Glossy — sheen over the filled button, same split as the Button standard. */
.exits-btn--glossy {
  background-image: linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.32),
    rgba(255, 255, 255, 0.08) 48%,
    rgba(255, 255, 255, 0.14) 50%,
    rgba(0, 0, 0, 0.08) 52%,
    rgba(0, 0, 0, 0.04)
  );
}

.exits-btn--glossy:disabled {
  background-image: none;
}

/* Button group — joined ExItS buttons (UI standards Button group / split dropdown). */
.exits-btn-group {
  display: inline-flex;
  align-items: stretch;
  max-width: 100%;
  border-radius: var(--exits-control-radius, var(--exits-radius-md));
}

.exits-btn-group > * {
  position: relative;
  margin: 0;
  border-radius: 0;
  box-shadow: none;
}

.exits-btn-group > * > button,
.exits-btn-group > button {
  border-radius: 0;
}

.exits-btn-group > :first-child,
.exits-btn-group > :first-child > button {
  border-start-start-radius: inherit;
  border-end-start-radius: inherit;
}

.exits-btn-group > :last-child,
.exits-btn-group > :last-child > button {
  border-start-end-radius: inherit;
  border-end-end-radius: inherit;
}

.exits-btn-group > :first-child > button,
.exits-btn-group > :last-child > button {
  border-radius: inherit;
}

.exits-btn-group > * + * {
  margin-inline-start: -1px;
}

.exits-btn-group > button:hover,
.exits-btn-group > button:focus-visible,
.exits-btn-group > button[aria-pressed="true"] {
  z-index: 1;
}

.exits-btn-group > button + button,
.exits-btn-group > button + * > button {
  border-inline-start-color: color-mix(in srgb, currentColor 22%, transparent);
}

.exits-btn-group--raised {
  box-shadow: var(--exits-shadow-md);
}

.exits-btn-group--pill {
  border-radius: 999px;
}

.exits-btn-group--spread {
  display: flex;
  width: 100%;
}

.exits-btn-group--spread > * {
  flex: 1 1 0;
}

/* ExitsModal open / close motion. Closing waits for these animations before unmounting. */
.exits-modal-backdrop[data-state="open"] {
  animation: exits-modal-fade-in 200ms var(--exits-ease-standard, cubic-bezier(0.2, 0, 0, 1));
}

.exits-modal-backdrop[data-state="closed"] {
  pointer-events: none;
  animation: exits-modal-fade-out 160ms ease-in forwards;
}

.exits-modal-panel[data-state="open"] {
  animation: exits-modal-panel-in 240ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.exits-modal-panel[data-state="closed"] {
  animation: exits-modal-panel-out 180ms ease-in forwards;
}

@keyframes exits-modal-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes exits-modal-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes exits-modal-panel-in {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes exits-modal-panel-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.92);
  }
}

@media (prefers-reduced-motion: reduce) {
  .exits-modal-backdrop[data-state],
  .exits-modal-panel[data-state] {
    animation: none;
  }
}

/* ExitsModal ribbon title — overhangs the panel's left edge (panel padding 1rem + 0.7rem). */
.exits-modal__ribbon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  max-width: calc(100% + 1.7rem);
  margin: -0.45rem 0 0 -1.7rem;
  padding: 0.35rem 0.85rem;
  border-radius: 0.2rem 0.2rem 0.2rem 0;
  background-color: var(--exits-modal-ribbon, var(--exits-primary));
  color: var(--exits-modal-ribbon-ink, var(--exits-primary-foreground, #fff));
  font-size: 0.9375rem;
  font-weight: 550;
  line-height: 1.3;
  letter-spacing: 0.01em;
  box-shadow:
    0 5px 5px -3px rgba(0, 0, 0, 0.28),
    0 8px 10px 1px rgba(0, 0, 0, 0.18),
    0 3px 14px 2px rgba(0, 0, 0, 0.14);
}

.exits-modal__ribbon::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 0;
  width: 0;
  height: 0;
  border-top: 0.5rem solid color-mix(in srgb, #000 38%, var(--exits-modal-ribbon, var(--exits-primary)));
  border-left: 0.7rem solid transparent;
}

/*
 * FormDrawer ribbon: absolute on the panel so it is not clipped by
 * overflow-x:hidden (which also forces y-clip). After modal + form-drawer rules.
 */
.exits-side-drawer__panel--ribbon,
.exits-side-drawer__panel--ribbon.exits-form-drawer__panel {
  overflow: visible !important;
}

.exits-side-drawer__header--ribbon {
  position: relative;
  overflow: visible;
  /* Clear absolute ribbon + fold under it. */
  padding-top: 2.75rem;
}

.exits-side-drawer__ribbon.exits-modal__ribbon {
  position: absolute;
  /* Sit on the panel top edge; left overhang for fold tail. */
  top: 0.35rem;
  left: -0.7rem;
  z-index: 4;
  margin: 0 !important;
  max-width: calc(100% - 2.5rem);
}

/* Keep close on the top-right with the ribbon (not pushed down by header pad). */
